insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (81, 5, 8, 19, 'سورة المائدة ٨ – ١٩', 'كونوا قوّامين لله، ونقض أهل الكتاب الميثاق، و«قد جاءكم من الله نور»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 81) = $j$[{"lbl": "الآيات ٨ – ١١", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ كُونُواْ قَوَّـٰمِينَ لِلَّهِ شُهَدَآءَ بِٱلۡقِسۡطِۖ وَلَا يَجۡرِمَنَّكُمۡ شَنَـَٔانُ قَوۡمٍ عَلَىٰٓ أَلَّا تَعۡدِلُواْۚ ٱعۡدِلُواْ هُوَ أَقۡرَبُ لِلتَّقۡوَىٰۖ وَٱتَّقُواْ ٱللَّهَۚ إِنَّ ٱللَّهَ خَبِيرُۢ بِمَا تَعۡمَلُونَ ﴿٨﴾ وَعَدَ ٱللَّهُ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ لَهُم مَّغۡفِرَةٞ وَأَجۡرٌ عَظِيمٞ ﴿٩﴾ وَٱلَّذِينَ كَفَرُواْ وَكَذَّبُواْ بِـَٔايَٰتِنَآ أُوْلَـٰٓئِكَ أَصۡحَٰبُ ٱلۡجَحِيمِ ﴿١٠﴾ يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱذۡكُرُواْ نِعۡمَتَ ٱللَّهِ عَلَيۡكُمۡ إِذۡ هَمَّ قَوۡمٌ أَن يَبۡسُطُوٓاْ إِلَيۡكُمۡ أَيۡدِيَهُمۡ فَكَفَّ أَيۡدِيَهُمۡ عَنكُمۡۖ وَٱتَّقُواْ ٱللَّهَۚ وَعَلَى ٱللَّهِ فَلۡيَتَوَكَّلِ ٱلۡمُؤۡمِنُونَ ﴿١١﴾", "w": [["قوّامين لله", "جمع قوّام، وهو كثير القيام لله بحقوقه، وبحقوق الغير أيضاً، لا يفرّط في شيء من ذلك."], ["شنآن", "بغض وعداوة."], ["العدل", "خلاف الجور، وهو المساواة بلا حيف."], ["هو أقرب للتقوى", "العدل أقرب للتقوى من الجور."], ["همّ قوم", "أرادوا وعزموا، والقوم هم يهود بني النضير."], ["يبسطوا إليكم أيديهم", "ليقتلوا نبيكم ﷺ."], ["فكفّ أيديهم", "لم يمكّنهم مما أرادوه من قتل النبي ﷺ."]], "m": "ما زال السياق في إرشاد المؤمنين إلى ما يكملهم: فأمرهم الله أن يكونوا قوّامين لله بسائر حقوقه، شهداء بالعدل لا يحيفون، سواء كان المشهود عليه ولياً أو عدواً، ونهاهم أن يحملهم بغض قوم على ترك العدل، وأعلمهم أن العدل أقرب للتقوى؛ لأن من كانت ملكة العدل صفة له كان أقدر على أداء الحقوق واجتناب المنهيات، ثم أمرهم بالتقوى وأعلمهم أنه خبير بما يعملون. ثم بشّر الذين آمنوا وعملوا الصالحات بالمغفرة والأجر العظيم، وتوعّد الكافرين المكذّبين بآياته بأنهم أصحاب الجحيم. ثم ذكّرهم بنعمة نجاة نبيهم ﷺ من القتل: إذ خرج ومعه الخلفاء الأربعة وعبد الرحمن بن عوف إلى بني النضير يطالبونهم بالمشاركة في دية قتيلين بموجب المعاهدة، فاستقبلوه بالحفاوة وأجلسوه تحت جدار، وتآمروا أن يُلقي أحدهم عليه حجر رحى من السطح، فأوحى الله إليه بما دبّروا فانصرف، ففاتتهم الفرصة واستوجبوا إلغاء المعاهدة وإجلاءهم. ثم أمرهم بتقواه، وأرشدهم إلى التوكل عليه: «وعلى الله فليتوكل المؤمنون».", "h": ["وجوب القيام بحق الله تعالى على العبد، وهو ذكره وشكره بطاعته.", "وجوب العدل في الحكم والقول والشهادة والفعل، مع الولي والعدو سواء.", "تأكيد الأمر بتقوى الله عز وجل.", "الترغيب والترهيب بذكر الوعد والوعيد.", "وجوب ذكر النعمة حتى يُؤدّى شكرها.", "وجوب التوكل على الله تعالى، والمضيّ في أداء ما أوجب الله."], "k": "«ولا يجرمنّكم شنآن قوم على ألا تعدلوا»… هل أنصف من أختلف معه أو لا أحبه؟"}, {"lbl": "الآية ١٢", "q": "۞وَلَقَدۡ أَخَذَ ٱللَّهُ مِيثَٰقَ بَنِيٓ إِسۡرَـٰٓءِيلَ وَبَعَثۡنَا مِنۡهُمُ ٱثۡنَيۡ عَشَرَ نَقِيبٗاۖ وَقَالَ ٱللَّهُ إِنِّي مَعَكُمۡۖ لَئِنۡ أَقَمۡتُمُ ٱلصَّلَوٰةَ وَءَاتَيۡتُمُ ٱلزَّكَوٰةَ وَءَامَنتُم بِرُسُلِي وَعَزَّرۡتُمُوهُمۡ وَأَقۡرَضۡتُمُ ٱللَّهَ قَرۡضًا حَسَنٗا لَّأُكَفِّرَنَّ عَنكُمۡ سَيِّـَٔاتِكُمۡ وَلَأُدۡخِلَنَّكُمۡ جَنَّـٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُۚ فَمَن كَفَرَ بَعۡدَ ذَٰلِكَ مِنكُمۡ فَقَدۡ ضَلَّ سَوَآءَ ٱلسَّبِيلِ ﴿١٢﴾", "w": [["الميثاق", "العهد المؤكد بالأيمان."], ["بني إسرائيل", "اليهود."], ["نقيباً", "نقيب القوم: من ينقّب عنهم ويبحث عن شؤونهم ويتولّى أمورهم."], ["وعزّرتموهم", "نصرتموهم ودافعتم عنهم معظّمين لهم."], ["وأقرضتم الله", "أنفقتم في سبيله ترجون الجزاء منه."], ["لأكفّرنّ عنكم سيئاتكم", "أسترها ولا أؤاخذكم بها."], ["فقد ضلّ سواء السبيل", "أخطأ طريق الهدى الذي يفلح سالكه."]], "m": "لما طالب الله المؤمنين بالوفاء بعهودهم، ذكّرهم بما أخذ على بني إسرائيل من ميثاق فنقضوه فاستوجبوا خزي الدنيا وعذاب الآخرة، عبرةً لهم، وإبطالاً لاستعظام من استعظم غدر اليهود وهمّهم بقتل النبي ﷺ. ولقد أخذ الله ميثاق بني إسرائيل، وبعث منهم اثني عشر نقيباً، من كل قبيلة نقيباً يرعاهم، وهم الذين بعثهم موسى ﵇ إلى فلسطين ليتعرفوا أحوال الكنعانيين قبل قتالهم، وقال الله: إني معكم، لئن أقمتم الصلاة، وآتيتم الزكاة، وآمنتم برسلي ونصرتموهم وعظّمتموهم، وأقرضتم الله قرضاً حسناً زيادةً على الزكاة، لأكفّرنّ عنكم سيئاتكم، ولأدخلنّكم جنات تجري من تحتها الأنهار، فمن كفر بعد ذلك فنقض الميثاق فقد أخطأ طريق الفلاح في الدنيا والآخرة.", "h": ["الحث على الوفاء بالالتزامات الشرعية.", "إبطال استغراب من يستغرب من اليهود مكرهم ونقضهم وخبثهم.", "إقام الصلاة وإيتاء الزكاة والإنفاق في سبيل الله تعبّد الله بها من قبل هذه الأمة.", "وجوب تعظيم الرسول ﷺ ونصرته في أمته ودينه."], "k": "«وعزّرتموهم»… كيف أنصر نبيي ﷺ اليوم: باتباع سنته، والدفاع عنها، وتعليمها؟"}, {"lbl": "الآيتان ١٣ – ١٤", "q": "فَبِمَا نَقۡضِهِم مِّيثَٰقَهُمۡ لَعَنَّـٰهُمۡ وَجَعَلۡنَا قُلُوبَهُمۡ قَٰسِيَةٗۖ يُحَرِّفُونَ ٱلۡكَلِمَ عَن مَّوَاضِعِهِۦ وَنَسُواْ حَظّٗا مِّمَّا ذُكِّرُواْ بِهِۦۚ وَلَا تَزَالُ تَطَّلِعُ عَلَىٰ خَآئِنَةٖ مِّنۡهُمۡ إِلَّا قَلِيلٗا مِّنۡهُمۡۖ فَٱعۡفُ عَنۡهُمۡ وَٱصۡفَحۡۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلۡمُحۡسِنِينَ ﴿١٣﴾ وَمِنَ ٱلَّذِينَ قَالُوٓاْ إِنَّا نَصَٰرَىٰٓ أَخَذۡنَا مِيثَٰقَهُمۡ فَنَسُواْ حَظّٗا مِّمَّا ذُكِّرُواْ بِهِۦ فَأَغۡرَيۡنَا بَيۡنَهُمُ ٱلۡعَدَاوَةَ وَٱلۡبَغۡضَآءَ إِلَىٰ يَوۡمِ ٱلۡقِيَٰمَةِۚ وَسَوۡفَ يُنَبِّئُهُمُ ٱللَّهُ بِمَا كَانُواْ يَصۡنَعُونَ ﴿١٤﴾", "w": [["نقض الميثاق", "حلّه بعدم الالتزام بما تضمّنه من أمر ونهي."], ["لعنّاهم", "طردناهم من موجبات الرحمة ومقتضيات العز والكمال."], ["يحرّفون الكلم", "يبدّلون الكلام ويؤوّلون معانيه لأغراض فاسدة."], ["ونسوا حظاً مما ذُكّروا به", "تركوا قسطاً كبيراً مما أمرهم الله به في كتابهم."], ["خائنة", "خيانة، أو طائفة خائنة منهم."], ["فاعفُ عنهم واصفح", "لا تؤاخذهم، واصرف وجهك عنهم محسناً إليهم بذلك."], ["إنا نصارى", "ابتدعوا بدعة النصرانية فقالوا: إنا نصارى."], ["فأغرينا بينهم العداوة", "الإغراء: التحريش، والمراد: أوجدنا لهم أسباب الفرقة والخلاف إلى يوم القيامة."]], "m": "ما زال السياق في بيان خبث اليهود وغدرهم: فبنقضهم ميثاقهم الذي أُخذ عليهم أن يعملوا بالتوراة ويطيعوا رسولهم، لعنّاهم فأبعدناهم من الرحمة، وجعلنا قلوبهم قاسية لا ترقّ لموعظة ولا تلين لقبول هدى، يحرّفون الكلم عن مواضعه، فيقدّمون ويؤخّرون ويحذفون ويؤوّلون، ومن ذلك تأويلهم الآيات الدالة على نبوة عيسى ومحمد ﷺ في التوراة، ونسوا حظاً مما ذُكّروا به من الشرائع والأحكام، ولا تزال تطّلع على خيانة منهم، كخيانة بني النضير، إلا قليلاً منهم كعبد الله بن سلام، فاعفُ عنهم واصفح، إن الله يحب المحسنين. ثم أخبر عن النصارى وأن حالهم كحال اليهود: أخذ ميثاقهم على الإيمان به وبرسله والعمل بشرعه، فنسوا حظاً كثيراً مما ذُكّروا به، فأغرى بينهم العداوة والبغضاء ثمرةً لنقضهم الميثاق، فتعصّبت كل طائفة لرأيها، وستستمر إلى يوم القيامة، وسوف ينبّئهم الله بما كانوا يصنعون.", "h": ["حرمة نقض المواثيق ونكث العهود، ولا سيما ما كان بين العبد وربه.", "الخيانة وصف لازم لأكثر اليهود، فقلّ من سلم منهم من هذا الوصف.", "استحباب العفو عند القدرة، وهو من خلال الصالحين.", "حال النصارى لا تختلف كثيراً عن حال اليهود، فلا يُستغرب منهم الشر، وهم في عداوة الإسلام متعاونون."], "k": "«وجعلنا قلوبهم قاسية»… ما الذي يُليّن قلبي إذا قسا: القرآن، أم ذكر الموت، أم الإحسان إلى المسكين؟"}, {"lbl": "الآيتان ١٥ – ١٦", "q": "يَـٰٓأَهۡلَ ٱلۡكِتَٰبِ قَدۡ جَآءَكُمۡ رَسُولُنَا يُبَيِّنُ لَكُمۡ كَثِيرٗا مِّمَّا كُنتُمۡ تُخۡفُونَ مِنَ ٱلۡكِتَٰبِ وَيَعۡفُواْ عَن كَثِيرٖۚ قَدۡ جَآءَكُم مِّنَ ٱللَّهِ نُورٞ وَكِتَٰبٞ مُّبِينٞ ﴿١٥﴾ يَهۡدِي بِهِ ٱللَّهُ مَنِ ٱتَّبَعَ رِضۡوَٰنَهُۥ سُبُلَ ٱلسَّلَٰمِ وَيُخۡرِجُهُم مِّنَ ٱلظُّلُمَٰتِ إِلَى ٱلنُّورِ بِإِذۡنِهِۦ وَيَهۡدِيهِمۡ إِلَىٰ صِرَٰطٖ مُّسۡتَقِيمٖ ﴿١٦﴾", "w": [["أهل الكتاب", "اليهود والنصارى معاً."], ["قد جاءكم رسولنا", "محمد ﷺ."], ["تخفون من الكتاب", "صفات النبي ﷺ وبعض الأحكام كالرجم، يجحدونها خوف المعرّة."], ["ويعفو عن كثير", "لا يذكرها لكم لعدم الفائدة من ذكرها."], ["نور وكتاب مبين", "النور: محمد ﷺ، والكتاب: القرآن الكريم."], ["إلى صراط مستقيم", "الإسلام، الدين الحق الذي لا نجاة إلا به."]], "m": "ما زال السياق في أهل الكتاب؛ فبعد أن بيّن باطلهم، دعاهم ربهم، وهو أرحم بهم من أنفسهم، إلى سبيل نجاتهم: يا أهل الكتاب قد جاءكم رسولنا محمد ﷺ يبيّن لكم كثيراً مما كنتم تخفون من الكتاب خشية الفضيحة، كنعوت النبي الأمي وحكم الرجم في التوراة، ويعفو عن كثير فلا يذكره لعدم الداعي إليه. قد جاءكم من الله نور، هو رسولنا محمد ﷺ، وكتاب مبين، هو القرآن الذي بيّن كل ما تتوقف عليه سعادة الإنسان وكماله، يهدي به الله من اتبع رضوانه، بالرغبة الصادقة في فعل محابّه وترك مساخطه، سبل السلام، أي طرق السعادة والكمال، ويخرجهم من ظلمات الكفر والشرك والشك إلى نور الإيمان بإذنه، ويهديهم إلى صراط مستقيم، هو الإسلام.", "h": ["نصح الله تعالى لأهل الكتاب بدعوتهم إلى سبل السلام بالدخول في الإسلام.", "بيان جحود اليهود والنصارى لكثير من الأحكام الشرعية ودلائل النبوة المحمدية، مكراً وحسداً، حتى لا يؤمن الناس بالإسلام.", "اتباع السنة المحمدية يهدي صاحبه إلى سعادته وكماله.", "القرآن حجة على الناس كافة، لبيانه الحق في كل شيء.", "طالب رضا الله بصدق يفوز بكل خير، وينجو من كل ضير."], "k": "«يهدي به الله من اتبع رضوانه سبل السلام»… هل أبحث عن رضا الله في قراراتي قبل رضا الناس؟"}, {"lbl": "الآيات ١٧ – ١٩", "q": "لَّقَدۡ كَفَرَ ٱلَّذِينَ قَالُوٓاْ إِنَّ ٱللَّهَ هُوَ ٱلۡمَسِيحُ ٱبۡنُ مَرۡيَمَۚ قُلۡ فَمَن يَمۡلِكُ مِنَ ٱللَّهِ شَيۡـًٔا إِنۡ أَرَادَ أَن يُهۡلِكَ ٱلۡمَسِيحَ ٱبۡنَ مَرۡيَمَ وَأُمَّهُۥ وَمَن فِي ٱلۡأَرۡضِ جَمِيعٗاۗ وَلِلَّهِ مُلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَمَا بَيۡنَهُمَاۚ يَخۡلُقُ مَا يَشَآءُۚ وَٱللَّهُ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ ﴿١٧﴾ وَقَالَتِ ٱلۡيَهُودُ وَٱلنَّصَٰرَىٰ نَحۡنُ أَبۡنَـٰٓؤُاْ ٱللَّهِ وَأَحِبَّـٰٓؤُهُۥۚ قُلۡ فَلِمَ يُعَذِّبُكُم بِذُنُوبِكُمۖ بَلۡ أَنتُم بَشَرٞ مِّمَّنۡ خَلَقَۚ يَغۡفِرُ لِمَن يَشَآءُ وَيُعَذِّبُ مَن يَشَآءُۚ وَلِلَّهِ مُلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَمَا بَيۡنَهُمَاۖ وَإِلَيۡهِ ٱلۡمَصِيرُ ﴿١٨﴾ يَـٰٓأَهۡلَ ٱلۡكِتَٰبِ قَدۡ جَآءَكُمۡ رَسُولُنَا يُبَيِّنُ لَكُمۡ عَلَىٰ فَتۡرَةٖ مِّنَ ٱلرُّسُلِ أَن تَقُولُواْ مَا جَآءَنَا مِنۢ بَشِيرٖ وَلَا نَذِيرٖۖ فَقَدۡ جَآءَكُم بَشِيرٞ وَنَذِيرٞۗ وَٱللَّهُ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ ﴿١٩﴾", "w": [["لقد كفر الذين", "لأنهم جحدوا الحق وقالوا كذباً: الله هو المسيح ابن مريم."], ["المسيح", "لقب لعيسى ابن مريم، عبد الله ورسوله ﵇."], ["مريم", "بنت عمران، من صلحاء بني إسرائيل، والدة عيسى ﵇."], ["يُهلك", "يُميت ويُبيد."], ["قدير", "قادر على إيجاد وإعدام كل شيء أراد."], ["الأحبّاء", "واحده حبيب."], ["على فترة", "الفترة: زمن انقطاع الوحي لعدم إرسال الله رسولاً."], ["بشير ونذير", "البشير: المبشّر بالخير، والنذير: المنذر من الشر، وهو رسول الله ﷺ."]], "m": "ما زال السياق في أهل الكتاب، فأخبر الله مؤكّداً: لقد كفر الذين قالوا إن الله هو المسيح ابن مريم؛ إذ جعلوا المخلوق المربوب هو الخالق الرب، وهو من أقبح أنواع الكفر، والراضي به مؤاخذ؛ لأن الرضا بالكفر كفر. ثم علّم رسوله كيف يحتج: قل فمن يملك من الله شيئاً إن أراد أن يهلك المسيح ابن مريم وأمه ومن في الأرض جميعاً؟ لا أحد، فكيف يكون عبد الله هو الله؟ ولله ملك السموات والأرض وما بينهما، يخلق ما يشاء: خلق آدم من تراب بلا أب ولا أم، وحواء من آدم، وعيسى من مريم بلا أب، فلا يستلزم ذلك أن يكون إلهاً. ثم ذكر دعوى اليهود والنصارى: نحن أبناء الله وأحباؤه، فأمر رسوله أن يردّ: فلِمَ يعذّبكم بذنوبكم، وأنتم تقرّون أنكم ستُعذّبون أياماً معدودة؟ بل أنتم بشر ممن خلق، يغفر لمن يشاء ويعذّب من يشاء، وإليه المصير. ثم أقام الحجة: يا أهل الكتاب قد جاءكم رسولنا يبيّن لكم على حين فترة من الرسل، إذ انقطع الوحي منذ رُفع عيسى قرابة خمسمائة وسبعين سنة، أن تقولوا ما جاءنا من بشير ولا نذير، فقد جاءكم بشير ونذير، والله على كل شيء قدير.", "h": ["كفر من ينسب إلى الله تعالى ما هو منزّه عنه من سائر النقائص.", "بطلان دعوى اليهود والنصارى أنهم أبناء الله وأحباؤه، بالدليل العقلي.", "نسبة المخلوقات لله تعالى لا تتجاوز كونها خلقاً له مملوكة يتصرّف فيها كما شاء.", "قطع عذر أهل الكتاب بإرسال الرسول محمد ﷺ على حين فترة من الرسل."], "k": "«بل أنتم بشر ممن خلق»… هل أتّكل على انتسابي للإسلام وأنسى أن الجزاء بالعمل؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 81;
insert into public.tdb_cards(topic, i, body) select 81, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٨ – ١١", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ كُونُواْ قَوَّـٰمِينَ لِلَّهِ شُهَدَآءَ بِٱلۡقِسۡطِۖ وَلَا يَجۡرِمَنَّكُمۡ شَنَـَٔانُ قَوۡمٍ عَلَىٰٓ أَلَّا تَعۡدِلُواْۚ ٱعۡدِلُواْ هُوَ أَقۡرَبُ لِلتَّقۡوَىٰۖ وَٱتَّقُواْ ٱللَّهَۚ إِنَّ ٱللَّهَ خَبِيرُۢ بِمَا تَعۡمَلُونَ ﴿٨﴾ وَعَدَ ٱللَّهُ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ لَهُم مَّغۡفِرَةٞ وَأَجۡرٌ عَظِيمٞ ﴿٩﴾ وَٱلَّذِينَ كَفَرُواْ وَكَذَّبُواْ بِـَٔايَٰتِنَآ أُوْلَـٰٓئِكَ أَصۡحَٰبُ ٱلۡجَحِيمِ ﴿١٠﴾ يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱذۡكُرُواْ نِعۡمَتَ ٱللَّهِ عَلَيۡكُمۡ إِذۡ هَمَّ قَوۡمٌ أَن يَبۡسُطُوٓاْ إِلَيۡكُمۡ أَيۡدِيَهُمۡ فَكَفَّ أَيۡدِيَهُمۡ عَنكُمۡۖ وَٱتَّقُواْ ٱللَّهَۚ وَعَلَى ٱللَّهِ فَلۡيَتَوَكَّلِ ٱلۡمُؤۡمِنُونَ ﴿١١﴾", "w": [["قوّامين لله", "جمع قوّام، وهو كثير القيام لله بحقوقه، وبحقوق الغير أيضاً، لا يفرّط في شيء من ذلك."], ["شنآن", "بغض وعداوة."], ["العدل", "خلاف الجور، وهو المساواة بلا حيف."], ["هو أقرب للتقوى", "العدل أقرب للتقوى من الجور."], ["همّ قوم", "أرادوا وعزموا، والقوم هم يهود بني النضير."], ["يبسطوا إليكم أيديهم", "ليقتلوا نبيكم ﷺ."], ["فكفّ أيديهم", "لم يمكّنهم مما أرادوه من قتل النبي ﷺ."]], "m": "ما زال السياق في إرشاد المؤمنين إلى ما يكملهم: فأمرهم الله أن يكونوا قوّامين لله بسائر حقوقه، شهداء بالعدل لا يحيفون، سواء كان المشهود عليه ولياً أو عدواً، ونهاهم أن يحملهم بغض قوم على ترك العدل، وأعلمهم أن العدل أقرب للتقوى؛ لأن من كانت ملكة العدل صفة له كان أقدر على أداء الحقوق واجتناب المنهيات، ثم أمرهم بالتقوى وأعلمهم أنه خبير بما يعملون. ثم بشّر الذين آمنوا وعملوا الصالحات بالمغفرة والأجر العظيم، وتوعّد الكافرين المكذّبين بآياته بأنهم أصحاب الجحيم. ثم ذكّرهم بنعمة نجاة نبيهم ﷺ من القتل: إذ خرج ومعه الخلفاء الأربعة وعبد الرحمن بن عوف إلى بني النضير يطالبونهم بالمشاركة في دية قتيلين بموجب المعاهدة، فاستقبلوه بالحفاوة وأجلسوه تحت جدار، وتآمروا أن يُلقي أحدهم عليه حجر رحى من السطح، فأوحى الله إليه بما دبّروا فانصرف، ففاتتهم الفرصة واستوجبوا إلغاء المعاهدة وإجلاءهم. ثم أمرهم بتقواه، وأرشدهم إلى التوكل عليه: «وعلى الله فليتوكل المؤمنون».", "h": ["وجوب القيام بحق الله تعالى على العبد، وهو ذكره وشكره بطاعته.", "وجوب العدل في الحكم والقول والشهادة والفعل، مع الولي والعدو سواء.", "تأكيد الأمر بتقوى الله عز وجل.", "الترغيب والترهيب بذكر الوعد والوعيد.", "وجوب ذكر النعمة حتى يُؤدّى شكرها.", "وجوب التوكل على الله تعالى، والمضيّ في أداء ما أوجب الله."], "k": "«ولا يجرمنّكم شنآن قوم على ألا تعدلوا»… هل أنصف من أختلف معه أو لا أحبه؟"}, {"lbl": "الآية ١٢", "q": "۞وَلَقَدۡ أَخَذَ ٱللَّهُ مِيثَٰقَ بَنِيٓ إِسۡرَـٰٓءِيلَ وَبَعَثۡنَا مِنۡهُمُ ٱثۡنَيۡ عَشَرَ نَقِيبٗاۖ وَقَالَ ٱللَّهُ إِنِّي مَعَكُمۡۖ لَئِنۡ أَقَمۡتُمُ ٱلصَّلَوٰةَ وَءَاتَيۡتُمُ ٱلزَّكَوٰةَ وَءَامَنتُم بِرُسُلِي وَعَزَّرۡتُمُوهُمۡ وَأَقۡرَضۡتُمُ ٱللَّهَ قَرۡضًا حَسَنٗا لَّأُكَفِّرَنَّ عَنكُمۡ سَيِّـَٔاتِكُمۡ وَلَأُدۡخِلَنَّكُمۡ جَنَّـٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُۚ فَمَن كَفَرَ بَعۡدَ ذَٰلِكَ مِنكُمۡ فَقَدۡ ضَلَّ سَوَآءَ ٱلسَّبِيلِ ﴿١٢﴾", "w": [["الميثاق", "العهد المؤكد بالأيمان."], ["بني إسرائيل", "اليهود."], ["نقيباً", "نقيب القوم: من ينقّب عنهم ويبحث عن شؤونهم ويتولّى أمورهم."], ["وعزّرتموهم", "نصرتموهم ودافعتم عنهم معظّمين لهم."], ["وأقرضتم الله", "أنفقتم في سبيله ترجون الجزاء منه."], ["لأكفّرنّ عنكم سيئاتكم", "أسترها ولا أؤاخذكم بها."], ["فقد ضلّ سواء السبيل", "أخطأ طريق الهدى الذي يفلح سالكه."]], "m": "لما طالب الله المؤمنين بالوفاء بعهودهم، ذكّرهم بما أخذ على بني إسرائيل من ميثاق فنقضوه فاستوجبوا خزي الدنيا وعذاب الآخرة، عبرةً لهم، وإبطالاً لاستعظام من استعظم غدر اليهود وهمّهم بقتل النبي ﷺ. ولقد أخذ الله ميثاق بني إسرائيل، وبعث منهم اثني عشر نقيباً، من كل قبيلة نقيباً يرعاهم، وهم الذين بعثهم موسى ﵇ إلى فلسطين ليتعرفوا أحوال الكنعانيين قبل قتالهم، وقال الله: إني معكم، لئن أقمتم الصلاة، وآتيتم الزكاة، وآمنتم برسلي ونصرتموهم وعظّمتموهم، وأقرضتم الله قرضاً حسناً زيادةً على الزكاة، لأكفّرنّ عنكم سيئاتكم، ولأدخلنّكم جنات تجري من تحتها الأنهار، فمن كفر بعد ذلك فنقض الميثاق فقد أخطأ طريق الفلاح في الدنيا والآخرة.", "h": ["الحث على الوفاء بالالتزامات الشرعية.", "إبطال استغراب من يستغرب من اليهود مكرهم ونقضهم وخبثهم.", "إقام الصلاة وإيتاء الزكاة والإنفاق في سبيل الله تعبّد الله بها من قبل هذه الأمة.", "وجوب تعظيم الرسول ﷺ ونصرته في أمته ودينه."], "k": "«وعزّرتموهم»… كيف أنصر نبيي ﷺ اليوم: باتباع سنته، والدفاع عنها، وتعليمها؟"}, {"lbl": "الآيتان ١٣ – ١٤", "q": "فَبِمَا نَقۡضِهِم مِّيثَٰقَهُمۡ لَعَنَّـٰهُمۡ وَجَعَلۡنَا قُلُوبَهُمۡ قَٰسِيَةٗۖ يُحَرِّفُونَ ٱلۡكَلِمَ عَن مَّوَاضِعِهِۦ وَنَسُواْ حَظّٗا مِّمَّا ذُكِّرُواْ بِهِۦۚ وَلَا تَزَالُ تَطَّلِعُ عَلَىٰ خَآئِنَةٖ مِّنۡهُمۡ إِلَّا قَلِيلٗا مِّنۡهُمۡۖ فَٱعۡفُ عَنۡهُمۡ وَٱصۡفَحۡۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلۡمُحۡسِنِينَ ﴿١٣﴾ وَمِنَ ٱلَّذِينَ قَالُوٓاْ إِنَّا نَصَٰرَىٰٓ أَخَذۡنَا مِيثَٰقَهُمۡ فَنَسُواْ حَظّٗا مِّمَّا ذُكِّرُواْ بِهِۦ فَأَغۡرَيۡنَا بَيۡنَهُمُ ٱلۡعَدَاوَةَ وَٱلۡبَغۡضَآءَ إِلَىٰ يَوۡمِ ٱلۡقِيَٰمَةِۚ وَسَوۡفَ يُنَبِّئُهُمُ ٱللَّهُ بِمَا كَانُواْ يَصۡنَعُونَ ﴿١٤﴾", "w": [["نقض الميثاق", "حلّه بعدم الالتزام بما تضمّنه من أمر ونهي."], ["لعنّاهم", "طردناهم من موجبات الرحمة ومقتضيات العز والكمال."], ["يحرّفون الكلم", "يبدّلون الكلام ويؤوّلون معانيه لأغراض فاسدة."], ["ونسوا حظاً مما ذُكّروا به", "تركوا قسطاً كبيراً مما أمرهم الله به في كتابهم."], ["خائنة", "خيانة، أو طائفة خائنة منهم."], ["فاعفُ عنهم واصفح", "لا تؤاخذهم، واصرف وجهك عنهم محسناً إليهم بذلك."], ["إنا نصارى", "ابتدعوا بدعة النصرانية فقالوا: إنا نصارى."], ["فأغرينا بينهم العداوة", "الإغراء: التحريش، والمراد: أوجدنا لهم أسباب الفرقة والخلاف إلى يوم القيامة."]], "m": "ما زال السياق في بيان خبث اليهود وغدرهم: فبنقضهم ميثاقهم الذي أُخذ عليهم أن يعملوا بالتوراة ويطيعوا رسولهم، لعنّاهم فأبعدناهم من الرحمة، وجعلنا قلوبهم قاسية لا ترقّ لموعظة ولا تلين لقبول هدى، يحرّفون الكلم عن مواضعه، فيقدّمون ويؤخّرون ويحذفون ويؤوّلون، ومن ذلك تأويلهم الآيات الدالة على نبوة عيسى ومحمد ﷺ في التوراة، ونسوا حظاً مما ذُكّروا به من الشرائع والأحكام، ولا تزال تطّلع على خيانة منهم، كخيانة بني النضير، إلا قليلاً منهم كعبد الله بن سلام، فاعفُ عنهم واصفح، إن الله يحب المحسنين. ثم أخبر عن النصارى وأن حالهم كحال اليهود: أخذ ميثاقهم على الإيمان به وبرسله والعمل بشرعه، فنسوا حظاً كثيراً مما ذُكّروا به، فأغرى بينهم العداوة والبغضاء ثمرةً لنقضهم الميثاق، فتعصّبت كل طائفة لرأيها، وستستمر إلى يوم القيامة، وسوف ينبّئهم الله بما كانوا يصنعون.", "h": ["حرمة نقض المواثيق ونكث العهود، ولا سيما ما كان بين العبد وربه.", "الخيانة وصف لازم لأكثر اليهود، فقلّ من سلم منهم من هذا الوصف.", "استحباب العفو عند القدرة، وهو من خلال الصالحين.", "حال النصارى لا تختلف كثيراً عن حال اليهود، فلا يُستغرب منهم الشر، وهم في عداوة الإسلام متعاونون."], "k": "«وجعلنا قلوبهم قاسية»… ما الذي يُليّن قلبي إذا قسا: القرآن، أم ذكر الموت، أم الإحسان إلى المسكين؟"}, {"lbl": "الآيتان ١٥ – ١٦", "q": "يَـٰٓأَهۡلَ ٱلۡكِتَٰبِ قَدۡ جَآءَكُمۡ رَسُولُنَا يُبَيِّنُ لَكُمۡ كَثِيرٗا مِّمَّا كُنتُمۡ تُخۡفُونَ مِنَ ٱلۡكِتَٰبِ وَيَعۡفُواْ عَن كَثِيرٖۚ قَدۡ جَآءَكُم مِّنَ ٱللَّهِ نُورٞ وَكِتَٰبٞ مُّبِينٞ ﴿١٥﴾ يَهۡدِي بِهِ ٱللَّهُ مَنِ ٱتَّبَعَ رِضۡوَٰنَهُۥ سُبُلَ ٱلسَّلَٰمِ وَيُخۡرِجُهُم مِّنَ ٱلظُّلُمَٰتِ إِلَى ٱلنُّورِ بِإِذۡنِهِۦ وَيَهۡدِيهِمۡ إِلَىٰ صِرَٰطٖ مُّسۡتَقِيمٖ ﴿١٦﴾", "w": [["أهل الكتاب", "اليهود والنصارى معاً."], ["قد جاءكم رسولنا", "محمد ﷺ."], ["تخفون من الكتاب", "صفات النبي ﷺ وبعض الأحكام كالرجم، يجحدونها خوف المعرّة."], ["ويعفو عن كثير", "لا يذكرها لكم لعدم الفائدة من ذكرها."], ["نور وكتاب مبين", "النور: محمد ﷺ، والكتاب: القرآن الكريم."], ["إلى صراط مستقيم", "الإسلام، الدين الحق الذي لا نجاة إلا به."]], "m": "ما زال السياق في أهل الكتاب؛ فبعد أن بيّن باطلهم، دعاهم ربهم، وهو أرحم بهم من أنفسهم، إلى سبيل نجاتهم: يا أهل الكتاب قد جاءكم رسولنا محمد ﷺ يبيّن لكم كثيراً مما كنتم تخفون من الكتاب خشية الفضيحة، كنعوت النبي الأمي وحكم الرجم في التوراة، ويعفو عن كثير فلا يذكره لعدم الداعي إليه. قد جاءكم من الله نور، هو رسولنا محمد ﷺ، وكتاب مبين، هو القرآن الذي بيّن كل ما تتوقف عليه سعادة الإنسان وكماله، يهدي به الله من اتبع رضوانه، بالرغبة الصادقة في فعل محابّه وترك مساخطه، سبل السلام، أي طرق السعادة والكمال، ويخرجهم من ظلمات الكفر والشرك والشك إلى نور الإيمان بإذنه، ويهديهم إلى صراط مستقيم، هو الإسلام.", "h": ["نصح الله تعالى لأهل الكتاب بدعوتهم إلى سبل السلام بالدخول في الإسلام.", "بيان جحود اليهود والنصارى لكثير من الأحكام الشرعية ودلائل النبوة المحمدية، مكراً وحسداً، حتى لا يؤمن الناس بالإسلام.", "اتباع السنة المحمدية يهدي صاحبه إلى سعادته وكماله.", "القرآن حجة على الناس كافة، لبيانه الحق في كل شيء.", "طالب رضا الله بصدق يفوز بكل خير، وينجو من كل ضير."], "k": "«يهدي به الله من اتبع رضوانه سبل السلام»… هل أبحث عن رضا الله في قراراتي قبل رضا الناس؟"}, {"lbl": "الآيات ١٧ – ١٩", "q": "لَّقَدۡ كَفَرَ ٱلَّذِينَ قَالُوٓاْ إِنَّ ٱللَّهَ هُوَ ٱلۡمَسِيحُ ٱبۡنُ مَرۡيَمَۚ قُلۡ فَمَن يَمۡلِكُ مِنَ ٱللَّهِ شَيۡـًٔا إِنۡ أَرَادَ أَن يُهۡلِكَ ٱلۡمَسِيحَ ٱبۡنَ مَرۡيَمَ وَأُمَّهُۥ وَمَن فِي ٱلۡأَرۡضِ جَمِيعٗاۗ وَلِلَّهِ مُلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَمَا بَيۡنَهُمَاۚ يَخۡلُقُ مَا يَشَآءُۚ وَٱللَّهُ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ ﴿١٧﴾ وَقَالَتِ ٱلۡيَهُودُ وَٱلنَّصَٰرَىٰ نَحۡنُ أَبۡنَـٰٓؤُاْ ٱللَّهِ وَأَحِبَّـٰٓؤُهُۥۚ قُلۡ فَلِمَ يُعَذِّبُكُم بِذُنُوبِكُمۖ بَلۡ أَنتُم بَشَرٞ مِّمَّنۡ خَلَقَۚ يَغۡفِرُ لِمَن يَشَآءُ وَيُعَذِّبُ مَن يَشَآءُۚ وَلِلَّهِ مُلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَمَا بَيۡنَهُمَاۖ وَإِلَيۡهِ ٱلۡمَصِيرُ ﴿١٨﴾ يَـٰٓأَهۡلَ ٱلۡكِتَٰبِ قَدۡ جَآءَكُمۡ رَسُولُنَا يُبَيِّنُ لَكُمۡ عَلَىٰ فَتۡرَةٖ مِّنَ ٱلرُّسُلِ أَن تَقُولُواْ مَا جَآءَنَا مِنۢ بَشِيرٖ وَلَا نَذِيرٖۖ فَقَدۡ جَآءَكُم بَشِيرٞ وَنَذِيرٞۗ وَٱللَّهُ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ ﴿١٩﴾", "w": [["لقد كفر الذين", "لأنهم جحدوا الحق وقالوا كذباً: الله هو المسيح ابن مريم."], ["المسيح", "لقب لعيسى ابن مريم، عبد الله ورسوله ﵇."], ["مريم", "بنت عمران، من صلحاء بني إسرائيل، والدة عيسى ﵇."], ["يُهلك", "يُميت ويُبيد."], ["قدير", "قادر على إيجاد وإعدام كل شيء أراد."], ["الأحبّاء", "واحده حبيب."], ["على فترة", "الفترة: زمن انقطاع الوحي لعدم إرسال الله رسولاً."], ["بشير ونذير", "البشير: المبشّر بالخير، والنذير: المنذر من الشر، وهو رسول الله ﷺ."]], "m": "ما زال السياق في أهل الكتاب، فأخبر الله مؤكّداً: لقد كفر الذين قالوا إن الله هو المسيح ابن مريم؛ إذ جعلوا المخلوق المربوب هو الخالق الرب، وهو من أقبح أنواع الكفر، والراضي به مؤاخذ؛ لأن الرضا بالكفر كفر. ثم علّم رسوله كيف يحتج: قل فمن يملك من الله شيئاً إن أراد أن يهلك المسيح ابن مريم وأمه ومن في الأرض جميعاً؟ لا أحد، فكيف يكون عبد الله هو الله؟ ولله ملك السموات والأرض وما بينهما، يخلق ما يشاء: خلق آدم من تراب بلا أب ولا أم، وحواء من آدم، وعيسى من مريم بلا أب، فلا يستلزم ذلك أن يكون إلهاً. ثم ذكر دعوى اليهود والنصارى: نحن أبناء الله وأحباؤه، فأمر رسوله أن يردّ: فلِمَ يعذّبكم بذنوبكم، وأنتم تقرّون أنكم ستُعذّبون أياماً معدودة؟ بل أنتم بشر ممن خلق، يغفر لمن يشاء ويعذّب من يشاء، وإليه المصير. ثم أقام الحجة: يا أهل الكتاب قد جاءكم رسولنا يبيّن لكم على حين فترة من الرسل، إذ انقطع الوحي منذ رُفع عيسى قرابة خمسمائة وسبعين سنة، أن تقولوا ما جاءنا من بشير ولا نذير، فقد جاءكم بشير ونذير، والله على كل شيء قدير.", "h": ["كفر من ينسب إلى الله تعالى ما هو منزّه عنه من سائر النقائص.", "بطلان دعوى اليهود والنصارى أنهم أبناء الله وأحباؤه، بالدليل العقلي.", "نسبة المخلوقات لله تعالى لا تتجاوز كونها خلقاً له مملوكة يتصرّف فيها كما شاء.", "قطع عذر أهل الكتاب بإرسال الرسول محمد ﷺ على حين فترة من الرسل."], "k": "«بل أنتم بشر ممن خلق»… هل أتّكل على انتسابي للإسلام وأنسى أن الجزاء بالعمل؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (82, 5, 20, 37, 'سورة المائدة ٢٠ – ٣٧', 'ادخلوا الأرض المقدسة، وابنا آدم، و«من أحياها فكأنما أحيا الناس جميعاً»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 82) = $j$[{"lbl": "الآيات ٢٠ – ٢٣", "q": "وَإِذۡ قَالَ مُوسَىٰ لِقَوۡمِهِۦ يَٰقَوۡمِ ٱذۡكُرُواْ نِعۡمَةَ ٱللَّهِ عَلَيۡكُمۡ إِذۡ جَعَلَ فِيكُمۡ أَنۢبِيَآءَ وَجَعَلَكُم مُّلُوكٗا وَءَاتَىٰكُم مَّا لَمۡ يُؤۡتِ أَحَدٗا مِّنَ ٱلۡعَٰلَمِينَ ﴿٢٠﴾ يَٰقَوۡمِ ٱدۡخُلُواْ ٱلۡأَرۡضَ ٱلۡمُقَدَّسَةَ ٱلَّتِي كَتَبَ ٱللَّهُ لَكُمۡ وَلَا تَرۡتَدُّواْ عَلَىٰٓ أَدۡبَارِكُمۡ فَتَنقَلِبُواْ خَٰسِرِينَ ﴿٢١﴾ قَالُواْ يَٰمُوسَىٰٓ إِنَّ فِيهَا قَوۡمٗا جَبَّارِينَ وَإِنَّا لَن نَّدۡخُلَهَا حَتَّىٰ يَخۡرُجُواْ مِنۡهَا فَإِن يَخۡرُجُواْ مِنۡهَا فَإِنَّا دَٰخِلُونَ ﴿٢٢﴾ قَالَ رَجُلَانِ مِنَ ٱلَّذِينَ يَخَافُونَ أَنۡعَمَ ٱللَّهُ عَلَيۡهِمَا ٱدۡخُلُواْ عَلَيۡهِمُ ٱلۡبَابَ فَإِذَا دَخَلۡتُمُوهُ فَإِنَّكُمۡ غَٰلِبُونَۚ وَعَلَى ٱللَّهِ فَتَوَكَّلُوٓاْ إِن كُنتُم مُّؤۡمِنِينَ ﴿٢٣﴾", "w": [["نعمة الله عليكم", "منها نجاتهم من فرعون وملئه."], ["إذ جعل فيكم أنبياء", "منهم موسى وهارون ﵉."], ["وجعلكم ملوكاً", "مالكين أمر أنفسكم بعد الاستعباد الفرعوني."], ["العالمين", "المعاصرين لهم والسابقين."], ["الأرض المقدسة التي كتب الله لكم", "المطهّرة التي فرض الله عليكم دخولها والسكن فيها."], ["ولا ترتدّوا على أدباركم", "لا ترجعوا منهزمين إلى الوراء."], ["قوماً جبّارين", "عظام الأجسام أقوياء الأبدان، يجبرون على طاعتهم من شاؤوا."], ["يخافون", "مخالفة أمر الله ومعصية رسوله."], ["أنعم الله عليهما", "بنعمة العصمة، فلم يُفشيا سرّ ما شاهداه في أرض الجبّارين، وهما يوشع وكالب من النقباء."]], "m": "ما زال السياق في اليهود، فقال الله لرسوله ﷺ: واذكر إذ قال موسى لقومه: اذكروا نعمة الله عليكم إذ جعل فيكم أنبياء، وجعلكم ملوكاً تملكون أنفسكم، وآتاكم ما لم يؤتِ أحداً من العالمين، يا قوم ادخلوا الأرض المقدسة التي كتب الله لكم، فافتحوا باب المدينة وباغتوا العدو، ولا ترجعوا منهزمين فتنقلبوا خاسرين. فقالوا: يا موسى إن فيها قوماً جبّارين، وإنا لن ندخلها حتى يخرجوا منها؛ وكان سبب هذه الهزيمة الروحية ما أذاعه النقباء من أخبار مهولة عن العمالقة، إلا اثنين منهم: يوشع بن نون وكالب بن يوحنا، خافا الله فعصمهما من إفشاء ما رأيا إلا لموسى، فقالا للقوم: ادخلوا عليهم الباب، فإذا دخلتموه فإنكم غالبون، لعنصر المباغتة، وعلى الله فتوكلوا إن كنتم مؤمنين. وفي ذلك تسلية للرسول ﷺ ليزول استعظامه همّهم بقتله.", "h": ["تسلية الرسول ﷺ بإعلامه بخبث اليهود وشدة ضعفهم ومرض قلوبهم.", "فضح اليهود بكشف الآيات عن مخازيهم مع أنبيائهم.", "بيان الأثر السيئ الذي تركته إذاعة النقباء للأخبار الكاذبة المهولة.", "بيان سنة الله تعالى أنه لا يخلو زمان ولا مكان من عبد صالح تقوم به الحجة.", "فائدة عنصر المباغتة في الحرب، وأنه عنصر فعّال في كسب الانتصار."], "k": "«قال رجلان من الذين يخافون أنعم الله عليهما»… هل أكون صوت الثبات حين يُرجف الناس، أم أنشر الخوف؟"}, {"lbl": "الآيات ٢٤ – ٢٦", "q": "قَالُواْ يَٰمُوسَىٰٓ إِنَّا لَن نَّدۡخُلَهَآ أَبَدٗا مَّا دَامُواْ فِيهَا فَٱذۡهَبۡ أَنتَ وَرَبُّكَ فَقَٰتِلَآ إِنَّا هَٰهُنَا قَٰعِدُونَ ﴿٢٤﴾ قَالَ رَبِّ إِنِّي لَآ أَمۡلِكُ إِلَّا نَفۡسِي وَأَخِيۖ فَٱفۡرُقۡ بَيۡنَنَا وَبَيۡنَ ٱلۡقَوۡمِ ٱلۡفَٰسِقِينَ ﴿٢٥﴾ قَالَ فَإِنَّهَا مُحَرَّمَةٌ عَلَيۡهِمۡۛ أَرۡبَعِينَ سَنَةٗۛ يَتِيهُونَ فِي ٱلۡأَرۡضِۚ فَلَا تَأۡسَ عَلَى ٱلۡقَوۡمِ ٱلۡفَٰسِقِينَ ﴿٢٦﴾", "w": [["الفاسقين", "الخارجين عن أمر الله ورسوله بتركهم الجهاد جبناً وخوفاً."], ["محرّمة عليهم", "تحريماً كونياً قضائياً، لا شرعياً تعبّدياً."], ["يتيهون في الأرض", "في أرض سيناء متحيّرين، لا يدرون أين يذهبون، مدة أربعين سنة."], ["فلا تأسَ", "لا تحزن ولا تتأسّف."]], "m": "هذا جواب القوم على الرجلين الصالحين، إذ قالوا بكل وقاحة: يا موسى إنا لن ندخلها أبداً ما داموا فيها، فاذهب أنت وربك فقاتلا إنا هاهنا قاعدون؛ فأيّ تمرّد وجبن وسوء أدب أعظم من هذا؟ فقال موسى متبرّئاً منهم: رب إني لا أملك إلا نفسي وأخي هارون، فافرق بيننا وبين القوم الفاسقين. فأجابه ربه: فإنها محرّمة عليهم أربعين سنة، فما دخلوها إلا بعد مضيّها، يتيهون في أرض سيناء متحيّرين لا يدرون أين يذهبون ولا من أين يأتون، فلا تأسَ على القوم الفاسقين، فهذا جزاؤهم عُجّل لهم.", "h": ["بيان جبن اليهود، وسوء أدبهم مع ربهم وأنبيائهم.", "وجوب البراءة من أهل الفسق ببغض عملهم، وتركهم لنقمة الله تنزل بهم.", "حرمة الحزن والتأسّف على الفاسقين والظالمين إذا حلّت بهم العقوبة الإلهية جزاء فسقهم وظلمهم."], "k": "«إنا هاهنا قاعدون»… في أي خير قعدتُ وانتظرت غيري أن يقوم به عني؟"}, {"lbl": "الآيات ٢٧ – ٣١", "q": "۞وَٱتۡلُ عَلَيۡهِمۡ نَبَأَ ٱبۡنَيۡ ءَادَمَ بِٱلۡحَقِّ إِذۡ قَرَّبَا قُرۡبَانٗا فَتُقُبِّلَ مِنۡ أَحَدِهِمَا وَلَمۡ يُتَقَبَّلۡ مِنَ ٱلۡأٓخَرِ قَالَ لَأَقۡتُلَنَّكَۖ قَالَ إِنَّمَا يَتَقَبَّلُ ٱللَّهُ مِنَ ٱلۡمُتَّقِينَ ﴿٢٧﴾ لَئِنۢ بَسَطتَ إِلَيَّ يَدَكَ لِتَقۡتُلَنِي مَآ أَنَا۠ بِبَاسِطٖ يَدِيَ إِلَيۡكَ لِأَقۡتُلَكَۖ إِنِّيٓ أَخَافُ ٱللَّهَ رَبَّ ٱلۡعَٰلَمِينَ ﴿٢٨﴾ إِنِّيٓ أُرِيدُ أَن تَبُوٓأَ بِإِثۡمِي وَإِثۡمِكَ فَتَكُونَ مِنۡ أَصۡحَٰبِ ٱلنَّارِۚ وَذَٰلِكَ جَزَـٰٓؤُاْ ٱلظَّـٰلِمِينَ ﴿٢٩﴾ فَطَوَّعَتۡ لَهُۥ نَفۡسُهُۥ قَتۡلَ أَخِيهِ فَقَتَلَهُۥ فَأَصۡبَحَ مِنَ ٱلۡخَٰسِرِينَ ﴿٣٠﴾ فَبَعَثَ ٱللَّهُ غُرَابٗا يَبۡحَثُ فِي ٱلۡأَرۡضِ لِيُرِيَهُۥ كَيۡفَ يُوَٰرِي سَوۡءَةَ أَخِيهِۚ قَالَ يَٰوَيۡلَتَىٰٓ أَعَجَزۡتُ أَنۡ أَكُونَ مِثۡلَ هَٰذَا ٱلۡغُرَابِ فَأُوَٰرِيَ سَوۡءَةَ أَخِيۖ فَأَصۡبَحَ مِنَ ٱلنَّـٰدِمِينَ ﴿٣١﴾", "w": [["واتلُ عليهم", "واقرأ على اليهود الذين همّوا بقتلك وقتل أصحابك."], ["نبأ ابني آدم", "خبر ابني آدم: هابيل وقابيل."], ["قرباناً", "ما يُتقرّب به إلى الله تعالى كالصلاة والصدقات."], ["بسطت إليّ يدك", "مددت إليّ يدك."], ["أن تبوء بإثمي وإثمك", "ترجع إلى الله يوم القيامة بإثم قتلك إياي، وإثمك في معاصيك."], ["فطوّعت له نفسه", "شجّعته على القتل وزيّنته له حتى فعله."], ["غراباً", "طائراً أسود معروفاً."], ["يواري سوأة أخيه", "يستر بالتراب جسد أخيه، والسوأة ما يُكره النظر إليه."]], "m": "ما زال السياق في يهود بني النضير الذين همّوا بقتل النبي ﷺ، فقال تعالى لرسوله: اقرأ عليهم قصة ابني آدم ليعلموا عاقبة جريمة القتل التي همّوا بها، إذ قرّبا قرباناً، فتُقبّل من هابيل لأنه كان من أحسن ماله ونفسه به طيبة، ولم يُتقبّل من قابيل لأنه كان من أردأ ماله، فقال لأخيه حسداً: لأقتلنّك، كما حسدك اليهود على النبوة. فقال له أخوه: إنما يتقبّل الله من المتقين، فلو أخلصت لتُقبّل منك، والله لئن بسطت إليّ يدك لتقتلني ما أنا بباسط يدي إليك لأقتلك، إني أخاف الله رب العالمين، أن ألقاه بدم أرقته ظلماً، إني أريد أن تبوء بإثمي وإثمك فتكون من أصحاب النار، وذلك جزاء الظالمين. فزيّنت له نفسه قتل أخيه فقتله فأصبح من الخاسرين، وحمله على عاتقه لا يدري ما يصنع به حتى أنتن، فبعث الله غراباً ينبش الأرض ويواري غراباً ميتاً، ليريه كيف يواري سوأة أخيه، فقال متحسّراً: يا ويلتا أعجزت أن أكون مثل هذا الغراب فأواري سوأة أخي؟ فأصبح من النادمين، ومجرد الندم لا يكون توبة.", "h": ["مشروعية التقرّب إلى الله تعالى بما يحب أن يُتقرّب به إليه.", "عظم جريمة الحسد، وما يترتب عليها من الآثار السيئة.", "قبول الأعمال الصالحة يتوقف على الإخلاص فيها لله تعالى.", "بيان أول من سنّ جريمة القتل، وهو قابيل، ولذا ورد: «ما من نفس تُقتل ظلماً إلا كان على ابن آدم الأول كِفل منها، لأنه أول من سنّ القتل».", "مشروعية الدفن، وبيان زمنه.", "خير ابني آدم المقتول ظلماً، وشرّهما القاتل ظلماً."], "k": "«إنما يتقبّل الله من المتقين»… هل أعطي لله من أحسن ما عندي، أم من فُضول ما لا أحتاجه؟"}, {"lbl": "الآية ٣٢", "q": "مِنۡ أَجۡلِ ذَٰلِكَ كَتَبۡنَا عَلَىٰ بَنِيٓ إِسۡرَـٰٓءِيلَ أَنَّهُۥ مَن قَتَلَ نَفۡسَۢا بِغَيۡرِ نَفۡسٍ أَوۡ فَسَادٖ فِي ٱلۡأَرۡضِ فَكَأَنَّمَا قَتَلَ ٱلنَّاسَ جَمِيعٗا وَمَنۡ أَحۡيَاهَا فَكَأَنَّمَآ أَحۡيَا ٱلنَّاسَ جَمِيعٗاۚ وَلَقَدۡ جَآءَتۡهُمۡ رُسُلُنَا بِٱلۡبَيِّنَٰتِ ثُمَّ إِنَّ كَثِيرٗا مِّنۡهُم بَعۡدَ ذَٰلِكَ فِي ٱلۡأَرۡضِ لَمُسۡرِفُونَ ﴿٣٢﴾", "w": [["من أجل ذلك", "بسبب ذلك القتل."], ["كتبنا", "أوحينا."], ["أو فساد في الأرض", "بحربه لله ورسوله والمؤمنين."], ["ومن أحياها", "قدر على قتلها وهي مستوجبة له فتركها."], ["بالبيّنات", "الآيات الواضحات الحاملة للشرائع والدلائل."], ["مسرفون", "مكثرون من المعاصي والذنوب."]], "m": "من أجل قبح جريمة القتل وما يترتب عليها من مفاسد، شدّد الله على بني إسرائيل لكثرة ما شاع بينهم من سفك الدماء، فقد قتلوا زكريا ويحيى، وهمّوا بقتل عيسى ومحمد ﷺ: أنه من قتل نفساً بغير نفس، أو بغير فساد في الأرض بحرب الله ورسوله والمؤمنين، فكأنما قتل الناس جميعاً، بمعنى يُعذّب عذاب من قتل الناس جميعاً، ومن أحياها بأن عفا عنها وقد استوجبت القتل فكأنما أحيا الناس جميعاً، فيُعطى أجر ذلك، تنفيراً لهم من القتل وترغيباً في العفو. ولقد جاءتهم رسلهم بالبيّنات، فلم يكن شرّهم عن جهل، بل هم قوم متمرّدون، ثم إن كثيراً منهم بعد ذلك في الأرض لمسرفون. وبهذا انتهى الحديث عن اليهود المتعلق بهمّهم بقتل الرسول ﷺ وأصحابه، تسليةً له ولكل مؤمن يتعرّض لمكرهم.", "h": ["تأديب الرب تعالى لبني إسرائيل، ومع الأسف لم ينتفعوا به.", "فساد بني إسرائيل لم ينشأ عن الجهل وقلة العلم، بل كان اتباعاً للأهواء وجرياً وراء عرض الدنيا، فلذا غضب الله عليهم ولعنهم لأنهم عالمون.", "بالرغم من تضعيف جزاء الجريمة على اليهود ومضاعفة أجر الحسنة لهم، فإنهم أكثر الناس إسرافاً في الشر والفساد في الأرض."], "k": "«ومن أحياها فكأنما أحيا الناس جميعاً»… هل أستطيع اليوم أن «أحيي» نفساً: بإنقاذ، أو عفو، أو مساعدة مريض؟"}, {"lbl": "الآيتان ٣٣ – ٣٤", "q": "إِنَّمَا جَزَـٰٓؤُاْ ٱلَّذِينَ يُحَارِبُونَ ٱللَّهَ وَرَسُولَهُۥ وَيَسۡعَوۡنَ فِي ٱلۡأَرۡضِ فَسَادًا أَن يُقَتَّلُوٓاْ أَوۡ يُصَلَّبُوٓاْ أَوۡ تُقَطَّعَ أَيۡدِيهِمۡ وَأَرۡجُلُهُم مِّنۡ خِلَٰفٍ أَوۡ يُنفَوۡاْ مِنَ ٱلۡأَرۡضِۚ ذَٰلِكَ لَهُمۡ خِزۡيٞ فِي ٱلدُّنۡيَاۖ وَلَهُمۡ فِي ٱلۡأٓخِرَةِ عَذَابٌ عَظِيمٌ ﴿٣٣﴾ إِلَّا ٱلَّذِينَ تَابُواْ مِن قَبۡلِ أَن تَقۡدِرُواْ عَلَيۡهِمۡۖ فَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ غَفُورٞ رَّحِيمٞ ﴿٣٤﴾", "w": [["يحاربون الله ورسوله", "بالخروج عن طاعتهما، وحمل السلاح على المؤمنين وقتلهم وسلب أموالهم."], ["ويسعون في الأرض فساداً", "بإخافة الناس وقطع طرقهم وسلب أموالهم والاعتداء على حرماتهم."], ["أو يُصلّبوا", "يُشدّون على أعواد الخشب بعد أن يُقتلوا."], ["من خلاف", "بأن تُقطع اليد اليمنى والرجل اليسرى، أو العكس."], ["أو يُنفوا من الأرض", "من أرض الإسلام."], ["خزي في الدنيا", "ذلّ ومهانة."], ["عذاب عظيم", "عذاب جهنم."]], "m": "لما ذكر الله ما أوجبه على اليهود من شدة العقوبة على القتل والفساد، ذكر حكم من يحارب المسلمين ويسعى بالفساد في ديارهم: إنما جزاء الذين يحاربون الله ورسوله بالقتل والسلب، ويسعون في الأرض فساداً بتخويف المسلمين وقطع طرقهم وأخذ أموالهم والاعتداء على أعراضهم، أن يُقتّلوا، أو يُصلّبوا بعد القتل مدة، أو تُقطّع أيديهم وأرجلهم من خلاف، أو يُنفوا من دار الإسلام أو يُحبسوا حتى ينجو المسلمون من شرّهم، ذلك لهم خزي في الدنيا، ولهم في الآخرة عذاب عظيم. إلا الذين تابوا من قبل أن تقدروا عليهم، فجاؤوا تائبين، فاعلموا أن الله غفور رحيم: فإن كان كافراً فأسلم فالإسلام يجُبّ ما قبله، وإن كان مسلماً سقط عنه حدّ الحرابة ووجب عليه ردّ المال إن بقي في يده.", "h": ["بيان حكم الحرابة وحقيقتها: خروج جماعة لهم شوكة وبأيديهم سلاح، بعيداً عن المدن، يشنّون هجمات على المسلمين فيقتلون ويسلبون ويعتدون على الأعراض.", "الإمام مخيّر في إنزال العقوبة التي يرى أنها مناسبة لاستتباب الأمن.", "من تاب من المحاربين قبل التمكّن منه عُفي عنه، إلا أن يكون بيده مال سلبه فيردّه على ذويه.", "عظم عفو الله ورحمته بعباده، لمغفرته لمن تاب ورحمته له."], "k": "أمن الناس على أنفسهم وأموالهم عند الله عظيم… فهل يأمن الناس من لساني ويدي؟"}, {"lbl": "الآيات ٣٥ – ٣٧", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱتَّقُواْ ٱللَّهَ وَٱبۡتَغُوٓاْ إِلَيۡهِ ٱلۡوَسِيلَةَ وَجَٰهِدُواْ فِي سَبِيلِهِۦ لَعَلَّكُمۡ تُفۡلِحُونَ ﴿٣٥﴾ إِنَّ ٱلَّذِينَ كَفَرُواْ لَوۡ أَنَّ لَهُم مَّا فِي ٱلۡأَرۡضِ جَمِيعٗا وَمِثۡلَهُۥ مَعَهُۥ لِيَفۡتَدُواْ بِهِۦ مِنۡ عَذَابِ يَوۡمِ ٱلۡقِيَٰمَةِ مَا تُقُبِّلَ مِنۡهُمۡۖ وَلَهُمۡ عَذَابٌ أَلِيمٞ ﴿٣٦﴾ يُرِيدُونَ أَن يَخۡرُجُواْ مِنَ ٱلنَّارِ وَمَا هُم بِخَٰرِجِينَ مِنۡهَاۖ وَلَهُمۡ عَذَابٞ مُّقِيمٞ ﴿٣٧﴾", "w": [["اتقوا الله", "خافوا عذابه، فامتثلوا أمره وأمر رسوله واجتنبوا نهيهما."], ["وابتغوا", "اطلبوا."], ["الوسيلة", "تقرّبوا إليه بفعل محابّه وترك مساخطه تظفروا بالقرب منه."], ["وجاهدوا في سبيله", "جاهدوا أنفسكم بحملها على أن تتعلم وتعمل وتعلّم، وأعداءه بدعوتهم إلى الإسلام."], ["تفلحون", "تنجون من النار وتدخلون الجنة."], ["عذاب مقيم", "دائم لا يزول."]], "m": "ينادي الله عباده المؤمنين ليرشدهم إلى ما ينجيهم من العذاب وما يدنيهم من الرحمة: اتقوا الله، فإن عذابه لا يُتّقى إلا بالتقوى، وابتغوا إليه الوسيلة، أي تقرّبوا إليه بفعل ما يحب وترك ما يكره تفوزوا بالقرب منه، وجاهدوا في سبيله أنفسكم في طاعته، والشيطان في معصيته، والكفار في دعوتهم إلى الإسلام، باذلين كل ما في وسعكم، لعلكم تفلحون. ثم علّل ذلك بأن العذاب الذي أُمروا باتقائه لا يُطاق: فلو أن للذين كفروا ما في الأرض جميعاً ومثله معه ليفتدوا به من عذاب يوم القيامة ما تُقبّل منهم، ولهم عذاب أليم، يتمنّون بكل قلوبهم أن يخرجوا من النار وما هم بخارجين منها، ولهم عذاب مقيم.", "h": ["وجوب تقوى الله عز وجل، وطلب القربة إليه، والجهاد في سبيله.", "مشروعية التوسّل إلى الله تعالى بالإيمان وصالح الأعمال.", "عظم عذاب يوم القيامة وشدته غير المتناهية.", "لا فدية يوم القيامة، ولا شفاعة تنفع الكافر فيخرج بها من النار.", "حسن التعليل للأمر والنهي، بما يشجّع على الامتثال والترك."], "k": "«وابتغوا إليه الوسيلة»… ما العمل الذي أتقرّب به إلى الله اليوم، وأرجو أن يكون وسيلتي إليه؟"}]$j$::jsonb then 0 else 1 end;
