insert into public.tdb_cards(topic, i, body) select 82, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٢٠ – ٢٣", "q": "وَإِذۡ قَالَ مُوسَىٰ لِقَوۡمِهِۦ يَٰقَوۡمِ ٱذۡكُرُواْ نِعۡمَةَ ٱللَّهِ عَلَيۡكُمۡ إِذۡ جَعَلَ فِيكُمۡ أَنۢبِيَآءَ وَجَعَلَكُم مُّلُوكٗا وَءَاتَىٰكُم مَّا لَمۡ يُؤۡتِ أَحَدٗا مِّنَ ٱلۡعَٰلَمِينَ ﴿٢٠﴾ يَٰقَوۡمِ ٱدۡخُلُواْ ٱلۡأَرۡضَ ٱلۡمُقَدَّسَةَ ٱلَّتِي كَتَبَ ٱللَّهُ لَكُمۡ وَلَا تَرۡتَدُّواْ عَلَىٰٓ أَدۡبَارِكُمۡ فَتَنقَلِبُواْ خَٰسِرِينَ ﴿٢١﴾ قَالُواْ يَٰمُوسَىٰٓ إِنَّ فِيهَا قَوۡمٗا جَبَّارِينَ وَإِنَّا لَن نَّدۡخُلَهَا حَتَّىٰ يَخۡرُجُواْ مِنۡهَا فَإِن يَخۡرُجُواْ مِنۡهَا فَإِنَّا دَٰخِلُونَ ﴿٢٢﴾ قَالَ رَجُلَانِ مِنَ ٱلَّذِينَ يَخَافُونَ أَنۡعَمَ ٱللَّهُ عَلَيۡهِمَا ٱدۡخُلُواْ عَلَيۡهِمُ ٱلۡبَابَ فَإِذَا دَخَلۡتُمُوهُ فَإِنَّكُمۡ غَٰلِبُونَۚ وَعَلَى ٱللَّهِ فَتَوَكَّلُوٓاْ إِن كُنتُم مُّؤۡمِنِينَ ﴿٢٣﴾", "w": [["نعمة الله عليكم", "منها نجاتهم من فرعون وملئه."], ["إذ جعل فيكم أنبياء", "منهم موسى وهارون ﵉."], ["وجعلكم ملوكاً", "مالكين أمر أنفسكم بعد الاستعباد الفرعوني."], ["العالمين", "المعاصرين لهم والسابقين."], ["الأرض المقدسة التي كتب الله لكم", "المطهّرة التي فرض الله عليكم دخولها والسكن فيها."], ["ولا ترتدّوا على أدباركم", "لا ترجعوا منهزمين إلى الوراء."], ["قوماً جبّارين", "عظام الأجسام أقوياء الأبدان، يجبرون على طاعتهم من شاؤوا."], ["يخافون", "مخالفة أمر الله ومعصية رسوله."], ["أنعم الله عليهما", "بنعمة العصمة، فلم يُفشيا سرّ ما شاهداه في أرض الجبّارين، وهما يوشع وكالب من النقباء."]], "m": "ما زال السياق في اليهود، فقال الله لرسوله ﷺ: واذكر إذ قال موسى لقومه: اذكروا نعمة الله عليكم إذ جعل فيكم أنبياء، وجعلكم ملوكاً تملكون أنفسكم، وآتاكم ما لم يؤتِ أحداً من العالمين، يا قوم ادخلوا الأرض المقدسة التي كتب الله لكم، فافتحوا باب المدينة وباغتوا العدو، ولا ترجعوا منهزمين فتنقلبوا خاسرين. فقالوا: يا موسى إن فيها قوماً جبّارين، وإنا لن ندخلها حتى يخرجوا منها؛ وكان سبب هذه الهزيمة الروحية ما أذاعه النقباء من أخبار مهولة عن العمالقة، إلا اثنين منهم: يوشع بن نون وكالب بن يوحنا، خافا الله فعصمهما من إفشاء ما رأيا إلا لموسى، فقالا للقوم: ادخلوا عليهم الباب، فإذا دخلتموه فإنكم غالبون، لعنصر المباغتة، وعلى الله فتوكلوا إن كنتم مؤمنين. وفي ذلك تسلية للرسول ﷺ ليزول استعظامه همّهم بقتله.", "h": ["تسلية الرسول ﷺ بإعلامه بخبث اليهود وشدة ضعفهم ومرض قلوبهم.", "فضح اليهود بكشف الآيات عن مخازيهم مع أنبيائهم.", "بيان الأثر السيئ الذي تركته إذاعة النقباء للأخبار الكاذبة المهولة.", "بيان سنة الله تعالى أنه لا يخلو زمان ولا مكان من عبد صالح تقوم به الحجة.", "فائدة عنصر المباغتة في الحرب، وأنه عنصر فعّال في كسب الانتصار."], "k": "«قال رجلان من الذين يخافون أنعم الله عليهما»… هل أكون صوت الثبات حين يُرجف الناس، أم أنشر الخوف؟"}, {"lbl": "الآيات ٢٤ – ٢٦", "q": "قَالُواْ يَٰمُوسَىٰٓ إِنَّا لَن نَّدۡخُلَهَآ أَبَدٗا مَّا دَامُواْ فِيهَا فَٱذۡهَبۡ أَنتَ وَرَبُّكَ فَقَٰتِلَآ إِنَّا هَٰهُنَا قَٰعِدُونَ ﴿٢٤﴾ قَالَ رَبِّ إِنِّي لَآ أَمۡلِكُ إِلَّا نَفۡسِي وَأَخِيۖ فَٱفۡرُقۡ بَيۡنَنَا وَبَيۡنَ ٱلۡقَوۡمِ ٱلۡفَٰسِقِينَ ﴿٢٥﴾ قَالَ فَإِنَّهَا مُحَرَّمَةٌ عَلَيۡهِمۡۛ أَرۡبَعِينَ سَنَةٗۛ يَتِيهُونَ فِي ٱلۡأَرۡضِۚ فَلَا تَأۡسَ عَلَى ٱلۡقَوۡمِ ٱلۡفَٰسِقِينَ ﴿٢٦﴾", "w": [["الفاسقين", "الخارجين عن أمر الله ورسوله بتركهم الجهاد جبناً وخوفاً."], ["محرّمة عليهم", "تحريماً كونياً قضائياً، لا شرعياً تعبّدياً."], ["يتيهون في الأرض", "في أرض سيناء متحيّرين، لا يدرون أين يذهبون، مدة أربعين سنة."], ["فلا تأسَ", "لا تحزن ولا تتأسّف."]], "m": "هذا جواب القوم على الرجلين الصالحين، إذ قالوا بكل وقاحة: يا موسى إنا لن ندخلها أبداً ما داموا فيها، فاذهب أنت وربك فقاتلا إنا هاهنا قاعدون؛ فأيّ تمرّد وجبن وسوء أدب أعظم من هذا؟ فقال موسى متبرّئاً منهم: رب إني لا أملك إلا نفسي وأخي هارون، فافرق بيننا وبين القوم الفاسقين. فأجابه ربه: فإنها محرّمة عليهم أربعين سنة، فما دخلوها إلا بعد مضيّها، يتيهون في أرض سيناء متحيّرين لا يدرون أين يذهبون ولا من أين يأتون، فلا تأسَ على القوم الفاسقين، فهذا جزاؤهم عُجّل لهم.", "h": ["بيان جبن اليهود، وسوء أدبهم مع ربهم وأنبيائهم.", "وجوب البراءة من أهل الفسق ببغض عملهم، وتركهم لنقمة الله تنزل بهم.", "حرمة الحزن والتأسّف على الفاسقين والظالمين إذا حلّت بهم العقوبة الإلهية جزاء فسقهم وظلمهم."], "k": "«إنا هاهنا قاعدون»… في أي خير قعدتُ وانتظرت غيري أن يقوم به عني؟"}, {"lbl": "الآيات ٢٧ – ٣١", "q": "۞وَٱتۡلُ عَلَيۡهِمۡ نَبَأَ ٱبۡنَيۡ ءَادَمَ بِٱلۡحَقِّ إِذۡ قَرَّبَا قُرۡبَانٗا فَتُقُبِّلَ مِنۡ أَحَدِهِمَا وَلَمۡ يُتَقَبَّلۡ مِنَ ٱلۡأٓخَرِ قَالَ لَأَقۡتُلَنَّكَۖ قَالَ إِنَّمَا يَتَقَبَّلُ ٱللَّهُ مِنَ ٱلۡمُتَّقِينَ ﴿٢٧﴾ لَئِنۢ بَسَطتَ إِلَيَّ يَدَكَ لِتَقۡتُلَنِي مَآ أَنَا۠ بِبَاسِطٖ يَدِيَ إِلَيۡكَ لِأَقۡتُلَكَۖ إِنِّيٓ أَخَافُ ٱللَّهَ رَبَّ ٱلۡعَٰلَمِينَ ﴿٢٨﴾ إِنِّيٓ أُرِيدُ أَن تَبُوٓأَ بِإِثۡمِي وَإِثۡمِكَ فَتَكُونَ مِنۡ أَصۡحَٰبِ ٱلنَّارِۚ وَذَٰلِكَ جَزَـٰٓؤُاْ ٱلظَّـٰلِمِينَ ﴿٢٩﴾ فَطَوَّعَتۡ لَهُۥ نَفۡسُهُۥ قَتۡلَ أَخِيهِ فَقَتَلَهُۥ فَأَصۡبَحَ مِنَ ٱلۡخَٰسِرِينَ ﴿٣٠﴾ فَبَعَثَ ٱللَّهُ غُرَابٗا يَبۡحَثُ فِي ٱلۡأَرۡضِ لِيُرِيَهُۥ كَيۡفَ يُوَٰرِي سَوۡءَةَ أَخِيهِۚ قَالَ يَٰوَيۡلَتَىٰٓ أَعَجَزۡتُ أَنۡ أَكُونَ مِثۡلَ هَٰذَا ٱلۡغُرَابِ فَأُوَٰرِيَ سَوۡءَةَ أَخِيۖ فَأَصۡبَحَ مِنَ ٱلنَّـٰدِمِينَ ﴿٣١﴾", "w": [["واتلُ عليهم", "واقرأ على اليهود الذين همّوا بقتلك وقتل أصحابك."], ["نبأ ابني آدم", "خبر ابني آدم: هابيل وقابيل."], ["قرباناً", "ما يُتقرّب به إلى الله تعالى كالصلاة والصدقات."], ["بسطت إليّ يدك", "مددت إليّ يدك."], ["أن تبوء بإثمي وإثمك", "ترجع إلى الله يوم القيامة بإثم قتلك إياي، وإثمك في معاصيك."], ["فطوّعت له نفسه", "شجّعته على القتل وزيّنته له حتى فعله."], ["غراباً", "طائراً أسود معروفاً."], ["يواري سوأة أخيه", "يستر بالتراب جسد أخيه، والسوأة ما يُكره النظر إليه."]], "m": "ما زال السياق في يهود بني النضير الذين همّوا بقتل النبي ﷺ، فقال تعالى لرسوله: اقرأ عليهم قصة ابني آدم ليعلموا عاقبة جريمة القتل التي همّوا بها، إذ قرّبا قرباناً، فتُقبّل من هابيل لأنه كان من أحسن ماله ونفسه به طيبة، ولم يُتقبّل من قابيل لأنه كان من أردأ ماله، فقال لأخيه حسداً: لأقتلنّك، كما حسدك اليهود على النبوة. فقال له أخوه: إنما يتقبّل الله من المتقين، فلو أخلصت لتُقبّل منك، والله لئن بسطت إليّ يدك لتقتلني ما أنا بباسط يدي إليك لأقتلك، إني أخاف الله رب العالمين، أن ألقاه بدم أرقته ظلماً، إني أريد أن تبوء بإثمي وإثمك فتكون من أصحاب النار، وذلك جزاء الظالمين. فزيّنت له نفسه قتل أخيه فقتله فأصبح من الخاسرين، وحمله على عاتقه لا يدري ما يصنع به حتى أنتن، فبعث الله غراباً ينبش الأرض ويواري غراباً ميتاً، ليريه كيف يواري سوأة أخيه، فقال متحسّراً: يا ويلتا أعجزت أن أكون مثل هذا الغراب فأواري سوأة أخي؟ فأصبح من النادمين، ومجرد الندم لا يكون توبة.", "h": ["مشروعية التقرّب إلى الله تعالى بما يحب أن يُتقرّب به إليه.", "عظم جريمة الحسد، وما يترتب عليها من الآثار السيئة.", "قبول الأعمال الصالحة يتوقف على الإخلاص فيها لله تعالى.", "بيان أول من سنّ جريمة القتل، وهو قابيل، ولذا ورد: «ما من نفس تُقتل ظلماً إلا كان على ابن آدم الأول كِفل منها، لأنه أول من سنّ القتل».", "مشروعية الدفن، وبيان زمنه.", "خير ابني آدم المقتول ظلماً، وشرّهما القاتل ظلماً."], "k": "«إنما يتقبّل الله من المتقين»… هل أعطي لله من أحسن ما عندي، أم من فُضول ما لا أحتاجه؟"}, {"lbl": "الآية ٣٢", "q": "مِنۡ أَجۡلِ ذَٰلِكَ كَتَبۡنَا عَلَىٰ بَنِيٓ إِسۡرَـٰٓءِيلَ أَنَّهُۥ مَن قَتَلَ نَفۡسَۢا بِغَيۡرِ نَفۡسٍ أَوۡ فَسَادٖ فِي ٱلۡأَرۡضِ فَكَأَنَّمَا قَتَلَ ٱلنَّاسَ جَمِيعٗا وَمَنۡ أَحۡيَاهَا فَكَأَنَّمَآ أَحۡيَا ٱلنَّاسَ جَمِيعٗاۚ وَلَقَدۡ جَآءَتۡهُمۡ رُسُلُنَا بِٱلۡبَيِّنَٰتِ ثُمَّ إِنَّ كَثِيرٗا مِّنۡهُم بَعۡدَ ذَٰلِكَ فِي ٱلۡأَرۡضِ لَمُسۡرِفُونَ ﴿٣٢﴾", "w": [["من أجل ذلك", "بسبب ذلك القتل."], ["كتبنا", "أوحينا."], ["أو فساد في الأرض", "بحربه لله ورسوله والمؤمنين."], ["ومن أحياها", "قدر على قتلها وهي مستوجبة له فتركها."], ["بالبيّنات", "الآيات الواضحات الحاملة للشرائع والدلائل."], ["مسرفون", "مكثرون من المعاصي والذنوب."]], "m": "من أجل قبح جريمة القتل وما يترتب عليها من مفاسد، شدّد الله على بني إسرائيل لكثرة ما شاع بينهم من سفك الدماء، فقد قتلوا زكريا ويحيى، وهمّوا بقتل عيسى ومحمد ﷺ: أنه من قتل نفساً بغير نفس، أو بغير فساد في الأرض بحرب الله ورسوله والمؤمنين، فكأنما قتل الناس جميعاً، بمعنى يُعذّب عذاب من قتل الناس جميعاً، ومن أحياها بأن عفا عنها وقد استوجبت القتل فكأنما أحيا الناس جميعاً، فيُعطى أجر ذلك، تنفيراً لهم من القتل وترغيباً في العفو. ولقد جاءتهم رسلهم بالبيّنات، فلم يكن شرّهم عن جهل، بل هم قوم متمرّدون، ثم إن كثيراً منهم بعد ذلك في الأرض لمسرفون. وبهذا انتهى الحديث عن اليهود المتعلق بهمّهم بقتل الرسول ﷺ وأصحابه، تسليةً له ولكل مؤمن يتعرّض لمكرهم.", "h": ["تأديب الرب تعالى لبني إسرائيل، ومع الأسف لم ينتفعوا به.", "فساد بني إسرائيل لم ينشأ عن الجهل وقلة العلم، بل كان اتباعاً للأهواء وجرياً وراء عرض الدنيا، فلذا غضب الله عليهم ولعنهم لأنهم عالمون.", "بالرغم من تضعيف جزاء الجريمة على اليهود ومضاعفة أجر الحسنة لهم، فإنهم أكثر الناس إسرافاً في الشر والفساد في الأرض."], "k": "«ومن أحياها فكأنما أحيا الناس جميعاً»… هل أستطيع اليوم أن «أحيي» نفساً: بإنقاذ، أو عفو، أو مساعدة مريض؟"}, {"lbl": "الآيتان ٣٣ – ٣٤", "q": "إِنَّمَا جَزَـٰٓؤُاْ ٱلَّذِينَ يُحَارِبُونَ ٱللَّهَ وَرَسُولَهُۥ وَيَسۡعَوۡنَ فِي ٱلۡأَرۡضِ فَسَادًا أَن يُقَتَّلُوٓاْ أَوۡ يُصَلَّبُوٓاْ أَوۡ تُقَطَّعَ أَيۡدِيهِمۡ وَأَرۡجُلُهُم مِّنۡ خِلَٰفٍ أَوۡ يُنفَوۡاْ مِنَ ٱلۡأَرۡضِۚ ذَٰلِكَ لَهُمۡ خِزۡيٞ فِي ٱلدُّنۡيَاۖ وَلَهُمۡ فِي ٱلۡأٓخِرَةِ عَذَابٌ عَظِيمٌ ﴿٣٣﴾ إِلَّا ٱلَّذِينَ تَابُواْ مِن قَبۡلِ أَن تَقۡدِرُواْ عَلَيۡهِمۡۖ فَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ غَفُورٞ رَّحِيمٞ ﴿٣٤﴾", "w": [["يحاربون الله ورسوله", "بالخروج عن طاعتهما، وحمل السلاح على المؤمنين وقتلهم وسلب أموالهم."], ["ويسعون في الأرض فساداً", "بإخافة الناس وقطع طرقهم وسلب أموالهم والاعتداء على حرماتهم."], ["أو يُصلّبوا", "يُشدّون على أعواد الخشب بعد أن يُقتلوا."], ["من خلاف", "بأن تُقطع اليد اليمنى والرجل اليسرى، أو العكس."], ["أو يُنفوا من الأرض", "من أرض الإسلام."], ["خزي في الدنيا", "ذلّ ومهانة."], ["عذاب عظيم", "عذاب جهنم."]], "m": "لما ذكر الله ما أوجبه على اليهود من شدة العقوبة على القتل والفساد، ذكر حكم من يحارب المسلمين ويسعى بالفساد في ديارهم: إنما جزاء الذين يحاربون الله ورسوله بالقتل والسلب، ويسعون في الأرض فساداً بتخويف المسلمين وقطع طرقهم وأخذ أموالهم والاعتداء على أعراضهم، أن يُقتّلوا، أو يُصلّبوا بعد القتل مدة، أو تُقطّع أيديهم وأرجلهم من خلاف، أو يُنفوا من دار الإسلام أو يُحبسوا حتى ينجو المسلمون من شرّهم، ذلك لهم خزي في الدنيا، ولهم في الآخرة عذاب عظيم. إلا الذين تابوا من قبل أن تقدروا عليهم، فجاؤوا تائبين، فاعلموا أن الله غفور رحيم: فإن كان كافراً فأسلم فالإسلام يجُبّ ما قبله، وإن كان مسلماً سقط عنه حدّ الحرابة ووجب عليه ردّ المال إن بقي في يده.", "h": ["بيان حكم الحرابة وحقيقتها: خروج جماعة لهم شوكة وبأيديهم سلاح، بعيداً عن المدن، يشنّون هجمات على المسلمين فيقتلون ويسلبون ويعتدون على الأعراض.", "الإمام مخيّر في إنزال العقوبة التي يرى أنها مناسبة لاستتباب الأمن.", "من تاب من المحاربين قبل التمكّن منه عُفي عنه، إلا أن يكون بيده مال سلبه فيردّه على ذويه.", "عظم عفو الله ورحمته بعباده، لمغفرته لمن تاب ورحمته له."], "k": "أمن الناس على أنفسهم وأموالهم عند الله عظيم… فهل يأمن الناس من لساني ويدي؟"}, {"lbl": "الآيات ٣٥ – ٣٧", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱتَّقُواْ ٱللَّهَ وَٱبۡتَغُوٓاْ إِلَيۡهِ ٱلۡوَسِيلَةَ وَجَٰهِدُواْ فِي سَبِيلِهِۦ لَعَلَّكُمۡ تُفۡلِحُونَ ﴿٣٥﴾ إِنَّ ٱلَّذِينَ كَفَرُواْ لَوۡ أَنَّ لَهُم مَّا فِي ٱلۡأَرۡضِ جَمِيعٗا وَمِثۡلَهُۥ مَعَهُۥ لِيَفۡتَدُواْ بِهِۦ مِنۡ عَذَابِ يَوۡمِ ٱلۡقِيَٰمَةِ مَا تُقُبِّلَ مِنۡهُمۡۖ وَلَهُمۡ عَذَابٌ أَلِيمٞ ﴿٣٦﴾ يُرِيدُونَ أَن يَخۡرُجُواْ مِنَ ٱلنَّارِ وَمَا هُم بِخَٰرِجِينَ مِنۡهَاۖ وَلَهُمۡ عَذَابٞ مُّقِيمٞ ﴿٣٧﴾", "w": [["اتقوا الله", "خافوا عذابه، فامتثلوا أمره وأمر رسوله واجتنبوا نهيهما."], ["وابتغوا", "اطلبوا."], ["الوسيلة", "تقرّبوا إليه بفعل محابّه وترك مساخطه تظفروا بالقرب منه."], ["وجاهدوا في سبيله", "جاهدوا أنفسكم بحملها على أن تتعلم وتعمل وتعلّم، وأعداءه بدعوتهم إلى الإسلام."], ["تفلحون", "تنجون من النار وتدخلون الجنة."], ["عذاب مقيم", "دائم لا يزول."]], "m": "ينادي الله عباده المؤمنين ليرشدهم إلى ما ينجيهم من العذاب وما يدنيهم من الرحمة: اتقوا الله، فإن عذابه لا يُتّقى إلا بالتقوى، وابتغوا إليه الوسيلة، أي تقرّبوا إليه بفعل ما يحب وترك ما يكره تفوزوا بالقرب منه، وجاهدوا في سبيله أنفسكم في طاعته، والشيطان في معصيته، والكفار في دعوتهم إلى الإسلام، باذلين كل ما في وسعكم، لعلكم تفلحون. ثم علّل ذلك بأن العذاب الذي أُمروا باتقائه لا يُطاق: فلو أن للذين كفروا ما في الأرض جميعاً ومثله معه ليفتدوا به من عذاب يوم القيامة ما تُقبّل منهم، ولهم عذاب أليم، يتمنّون بكل قلوبهم أن يخرجوا من النار وما هم بخارجين منها، ولهم عذاب مقيم.", "h": ["وجوب تقوى الله عز وجل، وطلب القربة إليه، والجهاد في سبيله.", "مشروعية التوسّل إلى الله تعالى بالإيمان وصالح الأعمال.", "عظم عذاب يوم القيامة وشدته غير المتناهية.", "لا فدية يوم القيامة، ولا شفاعة تنفع الكافر فيخرج بها من النار.", "حسن التعليل للأمر والنهي، بما يشجّع على الامتثال والترك."], "k": "«وابتغوا إليه الوسيلة»… ما العمل الذي أتقرّب به إلى الله اليوم، وأرجو أن يكون وسيلتي إليه؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (83, 5, 38, 50, 'سورة المائدة ٣٨ – ٥٠', 'حدّ السرقة، وتحاكم أهل الكتاب، و«ومن لم يحكم بما أنزل الله»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 83) = $j$[{"lbl": "الآيات ٣٨ – ٤٠", "q": "وَٱلسَّارِقُ وَٱلسَّارِقَةُ فَٱقۡطَعُوٓاْ أَيۡدِيَهُمَا جَزَآءَۢ بِمَا كَسَبَا نَكَٰلٗا مِّنَ ٱللَّهِۗ وَٱللَّهُ عَزِيزٌ حَكِيمٞ ﴿٣٨﴾ فَمَن تَابَ مِنۢ بَعۡدِ ظُلۡمِهِۦ وَأَصۡلَحَ فَإِنَّ ٱللَّهَ يَتُوبُ عَلَيۡهِۚ إِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٌ ﴿٣٩﴾ أَلَمۡ تَعۡلَمۡ أَنَّ ٱللَّهَ لَهُۥ مُلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ يُعَذِّبُ مَن يَشَآءُ وَيَغۡفِرُ لِمَن يَشَآءُۗ وَٱللَّهُ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ ﴿٤٠﴾", "w": [["السارقة", "التي أخذت مالاً من حرز خفية، يُقدّر بربع دينار فأكثر."], ["فاقطعوا أيديهما", "اقطعوا ممن سرق منهما يده من الكوع."], ["نكالاً", "عقوبة من الله تجعل غيره ينكل أن يسرق."], ["عزيز حكيم", "عزيز: غالب لا يُحال بينه وبين مراده، حكيم في تدبيره."], ["من بعد ظلمه", "بعد ظلمه لنفسه بأخذ أموال الناس."], ["وأصلح", "أصلح نفسه بالتوبة والعمل الصالح."], ["فإن الله يتوب عليه", "يقبل توبته ويغفر له ويرحمه."]], "m": "يقرّر الله حكماً من أحكام شرعه: أن الذي يسرق مالاً يُقدّر بربع دينار فأكثر من حرز مثله خفية، وهو عاقل بالغ، ورُفع إلى الحاكم، والسارقة كذلك، تُقطع يد كلٍّ منهما اليمنى من الكوع، جزاءً بما كسبا، نكالاً من الله يجعل غيرهما لا يُقدم على أخذ أموال الناس بالسرقة، والله عزيز حكيم. فمن تاب من بعد ظلمه وأصلح نفسه بالتوبة، ومن ذلك ردّ المال المسروق، فإن الله يتوب عليه، إن الله غفور رحيم. ألم تعلم أن الله له ملك السموات والأرض؟ فالحكم له لا يُنازع فيه، يعذّب من يشاء ويغفر لمن يشاء، والله على كل شيء قدير.", "h": ["بيان حكم حد السرقة، وهو قطع يد السارق والسارقة.", "بيان أن التائب من السرّاق إذا أصلح يتوب الله عليه، أي يقبل توبته.", "إذا لم يُرفع السارق إلى الحاكم تصح توبته ولو لم تُقطع يده، وإن رُفع فلا توبة له إلا بالقطع، فإذا قُطعت يده خرج من ذنبه كأن لم يذنب.", "وجوب التسليم لقضاء الله تعالى والرضا بحكمه، لأنه عزيز حكيم."], "k": "حرمة المال عند الله عظيمة… هل في يدي شيء لغيري: أمانة لم أردّها، أو حقٌّ تأخّرت في أدائه؟"}, {"lbl": "الآيات ٤١ – ٤٣", "q": "۞يَـٰٓأَيُّهَا ٱلرَّسُولُ لَا يَحۡزُنكَ ٱلَّذِينَ يُسَٰرِعُونَ فِي ٱلۡكُفۡرِ مِنَ ٱلَّذِينَ قَالُوٓاْ ءَامَنَّا بِأَفۡوَٰهِهِمۡ وَلَمۡ تُؤۡمِن قُلُوبُهُمۡۛ وَمِنَ ٱلَّذِينَ هَادُواْۛ سَمَّـٰعُونَ لِلۡكَذِبِ سَمَّـٰعُونَ لِقَوۡمٍ ءَاخَرِينَ لَمۡ يَأۡتُوكَۖ يُحَرِّفُونَ ٱلۡكَلِمَ مِنۢ بَعۡدِ مَوَاضِعِهِۦۖ يَقُولُونَ إِنۡ أُوتِيتُمۡ هَٰذَا فَخُذُوهُ وَإِن لَّمۡ تُؤۡتَوۡهُ فَٱحۡذَرُواْۚ وَمَن يُرِدِ ٱللَّهُ فِتۡنَتَهُۥ فَلَن تَمۡلِكَ لَهُۥ مِنَ ٱللَّهِ شَيۡـًٔاۚ أُوْلَـٰٓئِكَ ٱلَّذِينَ لَمۡ يُرِدِ ٱللَّهُ أَن يُطَهِّرَ قُلُوبَهُمۡۚ لَهُمۡ فِي ٱلدُّنۡيَا خِزۡيٞۖ وَلَهُمۡ فِي ٱلۡأٓخِرَةِ عَذَابٌ عَظِيمٞ ﴿٤١﴾ سَمَّـٰعُونَ لِلۡكَذِبِ أَكَّـٰلُونَ لِلسُّحۡتِۚ فَإِن جَآءُوكَ فَٱحۡكُم بَيۡنَهُمۡ أَوۡ أَعۡرِضۡ عَنۡهُمۡۖ وَإِن تُعۡرِضۡ عَنۡهُمۡ فَلَن يَضُرُّوكَ شَيۡـٔٗاۖ وَإِنۡ حَكَمۡتَ فَٱحۡكُم بَيۡنَهُم بِٱلۡقِسۡطِۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلۡمُقۡسِطِينَ ﴿٤٢﴾ وَكَيۡفَ يُحَكِّمُونَكَ وَعِندَهُمُ ٱلتَّوۡرَىٰةُ فِيهَا حُكۡمُ ٱللَّهِ ثُمَّ يَتَوَلَّوۡنَ مِنۢ بَعۡدِ ذَٰلِكَۚ وَمَآ أُوْلَـٰٓئِكَ بِٱلۡمُؤۡمِنِينَ ﴿٤٣﴾", "w": [["لا يحزنك", "الحزن: ألم نفسيّ يسبّبه خوف فوات محبوب."], ["يسارعون في الكفر", "يُسرعون فيه، إذ ما خرجوا منه، كلما سنحت فرصة للكفر."], ["قالوا آمنّا بأفواههم", "هؤلاء هم المنافقون."], ["ومن الذين هادوا", "اليهود."], ["سمّاعون للكذب", "كثيرو الاستماع للكذب."], ["يحرّفون الكلم", "يبدّلون الكلام ويغيّرونه ليوافق أهواءهم."], ["إن أوتيتم هذا", "إن أُعطيتم."], ["فتنته", "ضلاله، لما سبق له من موجبات الضلال."], ["أن يطهّر قلوبهم", "من الكفر والنفاق."], ["أكّالون للسحت", "كثيرو الأكل للحرام كالرشوة والربا."], ["أو أعرض عنهم", "لا تحكم بينهم."], ["بالقسط", "بالعدل."], ["وما أولئك بالمؤمنين", "صدقاً وحقاً، وإن ادّعوه نطقاً."]], "m": "نزلت الآيات تسلية لرسول الله ﷺ مما كان يجده من ألم نفسي مما يسمع ويرى من المنافقين واليهود، فناداه بعنوان الرسالة: لا يحزنك الذين يسارعون في الكفر بتكذيبك، من المنافقين الذين قالوا آمنّا بأفواههم ولم تؤمن قلوبهم، ومن اليهود، سمّاعون للكذب الذي يقوله أحبارهم، سمّاعون لقوم آخرين لم يأتوك، وهم يهود فدك وخيبر، أوعزوا إليهم أن يسألوا النبي ﷺ عن حدّ الزنى، يحرّفون حكم الله عن مواضعه، يقولون: إن أفتاكم بالجلد والتحميم فخذوه، وإن أفتاكم بالرجم فاحذروه. ومن يرد الله فتنته، أي إضلاله، لما اقترف من عظائم الذنوب، فلن تملك له من الله شيئاً، أولئك الذين لم يرد الله أن يطهّر قلوبهم، لهم في الدنيا خزي، ولهم في الآخرة عذاب عظيم. ثم وصفهم بكثرة سماع الكذب وأكل السحت، وخيّر الرسول ﷺ إن جاؤوه للتحاكم: إن شاء حكم بينهم بالعدل، وإن شاء أعرض عنهم فلن يضروه شيئاً. ثم تعجّب من حالهم: وكيف يحكّمونك وعندهم التوراة فيها حكم الله برجم الزناة، ثم يتولّون من بعد ذلك اتباعاً لأهوائهم، وما أولئك بالمؤمنين.", "h": ["استحباب ترك الحزن باجتناب أسبابه ومثيراته.", "حرمة سماع الكذب لغير حاجة تدعو إلى ذلك.", "حرمة تحريف الكلام وتشويهه للإفساد.", "الحاكم المسلم مخيّر في الحكم بين أهل الكتاب، إن شاء حكم بينهم، وإن شاء أحالهم على علمائهم.", "وجوب العدل في الحكم، ولو كان المحكوم عليه غير مسلم.", "تقرير كفر اليهود وعدم إيمانهم."], "k": "«سمّاعون للكذب»… ماذا أسمع كل يوم؟ وكم منه أتثبّت من صدقه قبل أن أصدّقه؟"}, {"lbl": "الآيات ٤٤ – ٤٧", "q": "إِنَّآ أَنزَلۡنَا ٱلتَّوۡرَىٰةَ فِيهَا هُدٗى وَنُورٞۚ يَحۡكُمُ بِهَا ٱلنَّبِيُّونَ ٱلَّذِينَ أَسۡلَمُواْ لِلَّذِينَ هَادُواْ وَٱلرَّبَّـٰنِيُّونَ وَٱلۡأَحۡبَارُ بِمَا ٱسۡتُحۡفِظُواْ مِن كِتَٰبِ ٱللَّهِ وَكَانُواْ عَلَيۡهِ شُهَدَآءَۚ فَلَا تَخۡشَوُاْ ٱلنَّاسَ وَٱخۡشَوۡنِ وَلَا تَشۡتَرُواْ بِـَٔايَٰتِي ثَمَنٗا قَلِيلٗاۚ وَمَن لَّمۡ يَحۡكُم بِمَآ أَنزَلَ ٱللَّهُ فَأُوْلَـٰٓئِكَ هُمُ ٱلۡكَٰفِرُونَ ﴿٤٤﴾ وَكَتَبۡنَا عَلَيۡهِمۡ فِيهَآ أَنَّ ٱلنَّفۡسَ بِٱلنَّفۡسِ وَٱلۡعَيۡنَ بِٱلۡعَيۡنِ وَٱلۡأَنفَ بِٱلۡأَنفِ وَٱلۡأُذُنَ بِٱلۡأُذُنِ وَٱلسِّنَّ بِٱلسِّنِّ وَٱلۡجُرُوحَ قِصَاصٞۚ فَمَن تَصَدَّقَ بِهِۦ فَهُوَ كَفَّارَةٞ لَّهُۥۚ وَمَن لَّمۡ يَحۡكُم بِمَآ أَنزَلَ ٱللَّهُ فَأُوْلَـٰٓئِكَ هُمُ ٱلظَّـٰلِمُونَ ﴿٤٥﴾ وَقَفَّيۡنَا عَلَىٰٓ ءَاثَٰرِهِم بِعِيسَى ٱبۡنِ مَرۡيَمَ مُصَدِّقٗا لِّمَا بَيۡنَ يَدَيۡهِ مِنَ ٱلتَّوۡرَىٰةِۖ وَءَاتَيۡنَٰهُ ٱلۡإِنجِيلَ فِيهِ هُدٗى وَنُورٞ وَمُصَدِّقٗا لِّمَا بَيۡنَ يَدَيۡهِ مِنَ ٱلتَّوۡرَىٰةِ وَهُدٗى وَمَوۡعِظَةٗ لِّلۡمُتَّقِينَ ﴿٤٦﴾ وَلۡيَحۡكُمۡ أَهۡلُ ٱلۡإِنجِيلِ بِمَآ أَنزَلَ ٱللَّهُ فِيهِۚ وَمَن لَّمۡ يَحۡكُم بِمَآ أَنزَلَ ٱللَّهُ فَأُوْلَـٰٓئِكَ هُمُ ٱلۡفَٰسِقُونَ ﴿٤٧﴾", "w": [["التوراة", "كتاب موسى ﵇."], ["هدى ونور", "الهدى: ما يوصل إلى المقصود، والنور: ما يهدي السائر إلى غرضه."], ["هادوا", "اليهود."], ["الأحبار", "جمع حبر، وهو العالم من أهل الكتاب."], ["وكتبنا", "فرضنا عليهم وأوجبنا."], ["قصاص", "مساواة."], ["وقفّينا", "أتبعناهم بعيسى ابن مريم."], ["الفاسقون", "الخارجون عن طاعة الله ورسله."]], "m": "إنا أنزلنا التوراة فيها هدى من كل ضلالة ونور مبيّن للأحكام، يحكم بها النبيون الذين أسلموا لله ظاهراً وباطناً، للذين هادوا، والربانيون والأحبار من أهل العلم، بما استحفظهم الله من كتابه فلا يبدّلونه، وكانوا عليه شهداء، بخلافكم أيها اليهود فقد حرّفتم وتركتم الحكم به؛ فأظهروا الحق من نعت محمد ﷺ وحكم الرجم، ولا تخشوا الناس واخشوا الله، ولا تشتروا بآيات الله ثمناً قليلاً تأخذونه ممن تداهنونهم، ومن لم يحكم بما أنزل الله فأولئك هم الكافرون. وكتبنا عليهم في التوراة القود في النفس والقصاص في الجراحات: النفس بالنفس، والعين بالعين، والأنف بالأنف، والأذن بالأذن، والسن بالسن، والجروح قصاص، فمن تصدّق بالعفو عن الجاني فهو كفارة لذنوبه، ومن لم يحكم بما أنزل الله، بأن قتل غير القاتل أو قتل بالواحد اثنين، كما كان بنو النضير يعاملون قريظة، فأولئك هم الظالمون. ثم أتبع الله أنبياء بني إسرائيل بعيسى ابن مريم مصدّقاً لما بين يديه من التوراة، وآتاه الإنجيل فيه هدى ونور، ومصدّقاً للتوراة إلا ما نسخه منها، وهدى وموعظة للمتقين، وأمر أهل الإنجيل أن يحكموا بما أنزل الله فيه، ومن لم يحكم بما أنزل الله فأولئك هم الفاسقون.", "h": ["وجوب خشية الله بأداء ما أوجب وترك ما حرّم.", "كفر من جحد أحكام الله فعطّلها، أو تلاعب بها فحكم بالبعض دون البعض.", "وجوب القود في النفس والقصاص في الجراحات؛ لأن ما كُتب على بني إسرائيل كُتب على هذه الأمة.", "من الظلم أن يُعتدى في القصاص، بأن يُقتل بالواحد اثنان، أو يُقتل غير القاتل، أو يُفقأ بالعين الواحدة عينان، وهو كفر مع الاستحلال وظلم في نفس الوقت.", "مشروعية القصاص في الإنجيل، وإلزام أهله بتطبيقه، وتقرير فسقهم إن عطّلوا تلك الأحكام وهم مؤمنون بها."], "k": "«فمن تصدّق به فهو كفّارة له»… هل أعفو عمن ظلمني راجياً أن يكفّر الله به ذنوبي؟"}, {"lbl": "الآيات ٤٨ – ٥٠", "q": "وَأَنزَلۡنَآ إِلَيۡكَ ٱلۡكِتَٰبَ بِٱلۡحَقِّ مُصَدِّقٗا لِّمَا بَيۡنَ يَدَيۡهِ مِنَ ٱلۡكِتَٰبِ وَمُهَيۡمِنًا عَلَيۡهِۖ فَٱحۡكُم بَيۡنَهُم بِمَآ أَنزَلَ ٱللَّهُۖ وَلَا تَتَّبِعۡ أَهۡوَآءَهُمۡ عَمَّا جَآءَكَ مِنَ ٱلۡحَقِّۚ لِكُلّٖ جَعَلۡنَا مِنكُمۡ شِرۡعَةٗ وَمِنۡهَاجٗاۚ وَلَوۡ شَآءَ ٱللَّهُ لَجَعَلَكُمۡ أُمَّةٗ وَٰحِدَةٗ وَلَٰكِن لِّيَبۡلُوَكُمۡ فِي مَآ ءَاتَىٰكُمۡۖ فَٱسۡتَبِقُواْ ٱلۡخَيۡرَٰتِۚ إِلَى ٱللَّهِ مَرۡجِعُكُمۡ جَمِيعٗا فَيُنَبِّئُكُم بِمَا كُنتُمۡ فِيهِ تَخۡتَلِفُونَ ﴿٤٨﴾ وَأَنِ ٱحۡكُم بَيۡنَهُم بِمَآ أَنزَلَ ٱللَّهُ وَلَا تَتَّبِعۡ أَهۡوَآءَهُمۡ وَٱحۡذَرۡهُمۡ أَن يَفۡتِنُوكَ عَنۢ بَعۡضِ مَآ أَنزَلَ ٱللَّهُ إِلَيۡكَۖ فَإِن تَوَلَّوۡاْ فَٱعۡلَمۡ أَنَّمَا يُرِيدُ ٱللَّهُ أَن يُصِيبَهُم بِبَعۡضِ ذُنُوبِهِمۡۗ وَإِنَّ كَثِيرٗا مِّنَ ٱلنَّاسِ لَفَٰسِقُونَ ﴿٤٩﴾ أَفَحُكۡمَ ٱلۡجَٰهِلِيَّةِ يَبۡغُونَۚ وَمَنۡ أَحۡسَنُ مِنَ ٱللَّهِ حُكۡمٗا لِّقَوۡمٖ يُوقِنُونَ ﴿٥٠﴾", "w": [["من الكتاب", "اسم جنس بمعنى الكتب السابقة كالتوراة والإنجيل."], ["مهيمناً عليه", "حاكماً عليه، محقّقاً للحق الذي فيه، مبطلاً للباطل الذي التصق به."], ["شِرعة ومنهاجاً", "شريعة تعملون بها، وسبيلاً تسلكونه لسعادتكم وكمالكم."], ["أمة واحدة", "لا اختلاف بينكم في عقيدة ولا عبادة ولا قضاء."], ["فاستبقوا", "بادروا فعل الخيرات ليفوز السابقون."], ["أن يفتنوك", "يضلّوك عن الحق."], ["فإن تولّوا", "أعرضوا عن قبول الحق."], ["حكم الجاهلية", "ما عليه أهل الجاهلية من الأحكام القبلية التي لا تقوم على وحي الله، وإنما على الآراء والأهواء."]], "m": "لما ذكر الله التوراة والإنجيل، ذكر القرآن: وأنزلنا إليك الكتاب بالحق، مصدّقاً لما بين يديه من الكتب، ومهيمناً عليها، فالحق ما أحقّه منها والباطل ما أبطله، فاحكم بين المتحاكمين إليك بما أنزل الله، بقتل القاتل ورجم الزاني، لا كما يريد اليهود، ولا تتّبع أهواءهم عما جاءك من الحق. لكلٍّ جعلنا شرعة ومنهاجاً، ولو شاء الله لجعلكم أمة واحدة على شريعة واحدة، ولكن نوّع الشرائع ليبتليكم فيما آتاكم فيتبيّن المطيع من العاصي، فاستبقوا الخيرات، إلى الله مرجعكم جميعاً فينبّئكم بما كنتم فيه تختلفون. ثم أمر رسوله أن يحكم بينهم بما أنزل الله، ونهاه أن يتّبع أهواءهم، وحذّره أن يفتنوه عن بعض ما أنزل الله إليه، وأعلمه أنهم إن تولّوا فإنما يريد الله أن يصيبهم ببعض ذنوبهم، وإن كثيراً من الناس لفاسقون، تسليةً له. ثم أنكر عليهم: أفحكم الجاهلية يبغون، حيث لا وحي ولا تشريع إلهي، وإنما العادات والأهواء؟ ومن أحسن من الله حكماً لقوم يوقنون؟", "h": ["وجوب الحكم في كل القضايا بالكتاب والسنة.", "لا يجوز تحكيم أية شريعة أو قانون غير الوحي الإلهي: الكتاب والسنة.", "التحذير من اتباع أهواء الناس خشية الإضلال عن الحق.", "بيان الحكمة من اختلاف الشرائع، وهي الابتلاء.", "أكثر المصائب في الدنيا ناتجة عن بعض الذنوب.", "حكم الشريعة الإسلامية أحسن الأحكام عدلاً ورحمة."], "k": "«فاستبقوا الخيرات»… ما الخير الذي أسابق إليه اليوم قبل أن يفوتني؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 83;
insert into public.tdb_cards(topic, i, body) select 83, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٣٨ – ٤٠", "q": "وَٱلسَّارِقُ وَٱلسَّارِقَةُ فَٱقۡطَعُوٓاْ أَيۡدِيَهُمَا جَزَآءَۢ بِمَا كَسَبَا نَكَٰلٗا مِّنَ ٱللَّهِۗ وَٱللَّهُ عَزِيزٌ حَكِيمٞ ﴿٣٨﴾ فَمَن تَابَ مِنۢ بَعۡدِ ظُلۡمِهِۦ وَأَصۡلَحَ فَإِنَّ ٱللَّهَ يَتُوبُ عَلَيۡهِۚ إِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٌ ﴿٣٩﴾ أَلَمۡ تَعۡلَمۡ أَنَّ ٱللَّهَ لَهُۥ مُلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ يُعَذِّبُ مَن يَشَآءُ وَيَغۡفِرُ لِمَن يَشَآءُۗ وَٱللَّهُ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ ﴿٤٠﴾", "w": [["السارقة", "التي أخذت مالاً من حرز خفية، يُقدّر بربع دينار فأكثر."], ["فاقطعوا أيديهما", "اقطعوا ممن سرق منهما يده من الكوع."], ["نكالاً", "عقوبة من الله تجعل غيره ينكل أن يسرق."], ["عزيز حكيم", "عزيز: غالب لا يُحال بينه وبين مراده، حكيم في تدبيره."], ["من بعد ظلمه", "بعد ظلمه لنفسه بأخذ أموال الناس."], ["وأصلح", "أصلح نفسه بالتوبة والعمل الصالح."], ["فإن الله يتوب عليه", "يقبل توبته ويغفر له ويرحمه."]], "m": "يقرّر الله حكماً من أحكام شرعه: أن الذي يسرق مالاً يُقدّر بربع دينار فأكثر من حرز مثله خفية، وهو عاقل بالغ، ورُفع إلى الحاكم، والسارقة كذلك، تُقطع يد كلٍّ منهما اليمنى من الكوع، جزاءً بما كسبا، نكالاً من الله يجعل غيرهما لا يُقدم على أخذ أموال الناس بالسرقة، والله عزيز حكيم. فمن تاب من بعد ظلمه وأصلح نفسه بالتوبة، ومن ذلك ردّ المال المسروق، فإن الله يتوب عليه، إن الله غفور رحيم. ألم تعلم أن الله له ملك السموات والأرض؟ فالحكم له لا يُنازع فيه، يعذّب من يشاء ويغفر لمن يشاء، والله على كل شيء قدير.", "h": ["بيان حكم حد السرقة، وهو قطع يد السارق والسارقة.", "بيان أن التائب من السرّاق إذا أصلح يتوب الله عليه، أي يقبل توبته.", "إذا لم يُرفع السارق إلى الحاكم تصح توبته ولو لم تُقطع يده، وإن رُفع فلا توبة له إلا بالقطع، فإذا قُطعت يده خرج من ذنبه كأن لم يذنب.", "وجوب التسليم لقضاء الله تعالى والرضا بحكمه، لأنه عزيز حكيم."], "k": "حرمة المال عند الله عظيمة… هل في يدي شيء لغيري: أمانة لم أردّها، أو حقٌّ تأخّرت في أدائه؟"}, {"lbl": "الآيات ٤١ – ٤٣", "q": "۞يَـٰٓأَيُّهَا ٱلرَّسُولُ لَا يَحۡزُنكَ ٱلَّذِينَ يُسَٰرِعُونَ فِي ٱلۡكُفۡرِ مِنَ ٱلَّذِينَ قَالُوٓاْ ءَامَنَّا بِأَفۡوَٰهِهِمۡ وَلَمۡ تُؤۡمِن قُلُوبُهُمۡۛ وَمِنَ ٱلَّذِينَ هَادُواْۛ سَمَّـٰعُونَ لِلۡكَذِبِ سَمَّـٰعُونَ لِقَوۡمٍ ءَاخَرِينَ لَمۡ يَأۡتُوكَۖ يُحَرِّفُونَ ٱلۡكَلِمَ مِنۢ بَعۡدِ مَوَاضِعِهِۦۖ يَقُولُونَ إِنۡ أُوتِيتُمۡ هَٰذَا فَخُذُوهُ وَإِن لَّمۡ تُؤۡتَوۡهُ فَٱحۡذَرُواْۚ وَمَن يُرِدِ ٱللَّهُ فِتۡنَتَهُۥ فَلَن تَمۡلِكَ لَهُۥ مِنَ ٱللَّهِ شَيۡـًٔاۚ أُوْلَـٰٓئِكَ ٱلَّذِينَ لَمۡ يُرِدِ ٱللَّهُ أَن يُطَهِّرَ قُلُوبَهُمۡۚ لَهُمۡ فِي ٱلدُّنۡيَا خِزۡيٞۖ وَلَهُمۡ فِي ٱلۡأٓخِرَةِ عَذَابٌ عَظِيمٞ ﴿٤١﴾ سَمَّـٰعُونَ لِلۡكَذِبِ أَكَّـٰلُونَ لِلسُّحۡتِۚ فَإِن جَآءُوكَ فَٱحۡكُم بَيۡنَهُمۡ أَوۡ أَعۡرِضۡ عَنۡهُمۡۖ وَإِن تُعۡرِضۡ عَنۡهُمۡ فَلَن يَضُرُّوكَ شَيۡـٔٗاۖ وَإِنۡ حَكَمۡتَ فَٱحۡكُم بَيۡنَهُم بِٱلۡقِسۡطِۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلۡمُقۡسِطِينَ ﴿٤٢﴾ وَكَيۡفَ يُحَكِّمُونَكَ وَعِندَهُمُ ٱلتَّوۡرَىٰةُ فِيهَا حُكۡمُ ٱللَّهِ ثُمَّ يَتَوَلَّوۡنَ مِنۢ بَعۡدِ ذَٰلِكَۚ وَمَآ أُوْلَـٰٓئِكَ بِٱلۡمُؤۡمِنِينَ ﴿٤٣﴾", "w": [["لا يحزنك", "الحزن: ألم نفسيّ يسبّبه خوف فوات محبوب."], ["يسارعون في الكفر", "يُسرعون فيه، إذ ما خرجوا منه، كلما سنحت فرصة للكفر."], ["قالوا آمنّا بأفواههم", "هؤلاء هم المنافقون."], ["ومن الذين هادوا", "اليهود."], ["سمّاعون للكذب", "كثيرو الاستماع للكذب."], ["يحرّفون الكلم", "يبدّلون الكلام ويغيّرونه ليوافق أهواءهم."], ["إن أوتيتم هذا", "إن أُعطيتم."], ["فتنته", "ضلاله، لما سبق له من موجبات الضلال."], ["أن يطهّر قلوبهم", "من الكفر والنفاق."], ["أكّالون للسحت", "كثيرو الأكل للحرام كالرشوة والربا."], ["أو أعرض عنهم", "لا تحكم بينهم."], ["بالقسط", "بالعدل."], ["وما أولئك بالمؤمنين", "صدقاً وحقاً، وإن ادّعوه نطقاً."]], "m": "نزلت الآيات تسلية لرسول الله ﷺ مما كان يجده من ألم نفسي مما يسمع ويرى من المنافقين واليهود، فناداه بعنوان الرسالة: لا يحزنك الذين يسارعون في الكفر بتكذيبك، من المنافقين الذين قالوا آمنّا بأفواههم ولم تؤمن قلوبهم، ومن اليهود، سمّاعون للكذب الذي يقوله أحبارهم، سمّاعون لقوم آخرين لم يأتوك، وهم يهود فدك وخيبر، أوعزوا إليهم أن يسألوا النبي ﷺ عن حدّ الزنى، يحرّفون حكم الله عن مواضعه، يقولون: إن أفتاكم بالجلد والتحميم فخذوه، وإن أفتاكم بالرجم فاحذروه. ومن يرد الله فتنته، أي إضلاله، لما اقترف من عظائم الذنوب، فلن تملك له من الله شيئاً، أولئك الذين لم يرد الله أن يطهّر قلوبهم، لهم في الدنيا خزي، ولهم في الآخرة عذاب عظيم. ثم وصفهم بكثرة سماع الكذب وأكل السحت، وخيّر الرسول ﷺ إن جاؤوه للتحاكم: إن شاء حكم بينهم بالعدل، وإن شاء أعرض عنهم فلن يضروه شيئاً. ثم تعجّب من حالهم: وكيف يحكّمونك وعندهم التوراة فيها حكم الله برجم الزناة، ثم يتولّون من بعد ذلك اتباعاً لأهوائهم، وما أولئك بالمؤمنين.", "h": ["استحباب ترك الحزن باجتناب أسبابه ومثيراته.", "حرمة سماع الكذب لغير حاجة تدعو إلى ذلك.", "حرمة تحريف الكلام وتشويهه للإفساد.", "الحاكم المسلم مخيّر في الحكم بين أهل الكتاب، إن شاء حكم بينهم، وإن شاء أحالهم على علمائهم.", "وجوب العدل في الحكم، ولو كان المحكوم عليه غير مسلم.", "تقرير كفر اليهود وعدم إيمانهم."], "k": "«سمّاعون للكذب»… ماذا أسمع كل يوم؟ وكم منه أتثبّت من صدقه قبل أن أصدّقه؟"}, {"lbl": "الآيات ٤٤ – ٤٧", "q": "إِنَّآ أَنزَلۡنَا ٱلتَّوۡرَىٰةَ فِيهَا هُدٗى وَنُورٞۚ يَحۡكُمُ بِهَا ٱلنَّبِيُّونَ ٱلَّذِينَ أَسۡلَمُواْ لِلَّذِينَ هَادُواْ وَٱلرَّبَّـٰنِيُّونَ وَٱلۡأَحۡبَارُ بِمَا ٱسۡتُحۡفِظُواْ مِن كِتَٰبِ ٱللَّهِ وَكَانُواْ عَلَيۡهِ شُهَدَآءَۚ فَلَا تَخۡشَوُاْ ٱلنَّاسَ وَٱخۡشَوۡنِ وَلَا تَشۡتَرُواْ بِـَٔايَٰتِي ثَمَنٗا قَلِيلٗاۚ وَمَن لَّمۡ يَحۡكُم بِمَآ أَنزَلَ ٱللَّهُ فَأُوْلَـٰٓئِكَ هُمُ ٱلۡكَٰفِرُونَ ﴿٤٤﴾ وَكَتَبۡنَا عَلَيۡهِمۡ فِيهَآ أَنَّ ٱلنَّفۡسَ بِٱلنَّفۡسِ وَٱلۡعَيۡنَ بِٱلۡعَيۡنِ وَٱلۡأَنفَ بِٱلۡأَنفِ وَٱلۡأُذُنَ بِٱلۡأُذُنِ وَٱلسِّنَّ بِٱلسِّنِّ وَٱلۡجُرُوحَ قِصَاصٞۚ فَمَن تَصَدَّقَ بِهِۦ فَهُوَ كَفَّارَةٞ لَّهُۥۚ وَمَن لَّمۡ يَحۡكُم بِمَآ أَنزَلَ ٱللَّهُ فَأُوْلَـٰٓئِكَ هُمُ ٱلظَّـٰلِمُونَ ﴿٤٥﴾ وَقَفَّيۡنَا عَلَىٰٓ ءَاثَٰرِهِم بِعِيسَى ٱبۡنِ مَرۡيَمَ مُصَدِّقٗا لِّمَا بَيۡنَ يَدَيۡهِ مِنَ ٱلتَّوۡرَىٰةِۖ وَءَاتَيۡنَٰهُ ٱلۡإِنجِيلَ فِيهِ هُدٗى وَنُورٞ وَمُصَدِّقٗا لِّمَا بَيۡنَ يَدَيۡهِ مِنَ ٱلتَّوۡرَىٰةِ وَهُدٗى وَمَوۡعِظَةٗ لِّلۡمُتَّقِينَ ﴿٤٦﴾ وَلۡيَحۡكُمۡ أَهۡلُ ٱلۡإِنجِيلِ بِمَآ أَنزَلَ ٱللَّهُ فِيهِۚ وَمَن لَّمۡ يَحۡكُم بِمَآ أَنزَلَ ٱللَّهُ فَأُوْلَـٰٓئِكَ هُمُ ٱلۡفَٰسِقُونَ ﴿٤٧﴾", "w": [["التوراة", "كتاب موسى ﵇."], ["هدى ونور", "الهدى: ما يوصل إلى المقصود، والنور: ما يهدي السائر إلى غرضه."], ["هادوا", "اليهود."], ["الأحبار", "جمع حبر، وهو العالم من أهل الكتاب."], ["وكتبنا", "فرضنا عليهم وأوجبنا."], ["قصاص", "مساواة."], ["وقفّينا", "أتبعناهم بعيسى ابن مريم."], ["الفاسقون", "الخارجون عن طاعة الله ورسله."]], "m": "إنا أنزلنا التوراة فيها هدى من كل ضلالة ونور مبيّن للأحكام، يحكم بها النبيون الذين أسلموا لله ظاهراً وباطناً، للذين هادوا، والربانيون والأحبار من أهل العلم، بما استحفظهم الله من كتابه فلا يبدّلونه، وكانوا عليه شهداء، بخلافكم أيها اليهود فقد حرّفتم وتركتم الحكم به؛ فأظهروا الحق من نعت محمد ﷺ وحكم الرجم، ولا تخشوا الناس واخشوا الله، ولا تشتروا بآيات الله ثمناً قليلاً تأخذونه ممن تداهنونهم، ومن لم يحكم بما أنزل الله فأولئك هم الكافرون. وكتبنا عليهم في التوراة القود في النفس والقصاص في الجراحات: النفس بالنفس، والعين بالعين، والأنف بالأنف، والأذن بالأذن، والسن بالسن، والجروح قصاص، فمن تصدّق بالعفو عن الجاني فهو كفارة لذنوبه، ومن لم يحكم بما أنزل الله، بأن قتل غير القاتل أو قتل بالواحد اثنين، كما كان بنو النضير يعاملون قريظة، فأولئك هم الظالمون. ثم أتبع الله أنبياء بني إسرائيل بعيسى ابن مريم مصدّقاً لما بين يديه من التوراة، وآتاه الإنجيل فيه هدى ونور، ومصدّقاً للتوراة إلا ما نسخه منها، وهدى وموعظة للمتقين، وأمر أهل الإنجيل أن يحكموا بما أنزل الله فيه، ومن لم يحكم بما أنزل الله فأولئك هم الفاسقون.", "h": ["وجوب خشية الله بأداء ما أوجب وترك ما حرّم.", "كفر من جحد أحكام الله فعطّلها، أو تلاعب بها فحكم بالبعض دون البعض.", "وجوب القود في النفس والقصاص في الجراحات؛ لأن ما كُتب على بني إسرائيل كُتب على هذه الأمة.", "من الظلم أن يُعتدى في القصاص، بأن يُقتل بالواحد اثنان، أو يُقتل غير القاتل، أو يُفقأ بالعين الواحدة عينان، وهو كفر مع الاستحلال وظلم في نفس الوقت.", "مشروعية القصاص في الإنجيل، وإلزام أهله بتطبيقه، وتقرير فسقهم إن عطّلوا تلك الأحكام وهم مؤمنون بها."], "k": "«فمن تصدّق به فهو كفّارة له»… هل أعفو عمن ظلمني راجياً أن يكفّر الله به ذنوبي؟"}, {"lbl": "الآيات ٤٨ – ٥٠", "q": "وَأَنزَلۡنَآ إِلَيۡكَ ٱلۡكِتَٰبَ بِٱلۡحَقِّ مُصَدِّقٗا لِّمَا بَيۡنَ يَدَيۡهِ مِنَ ٱلۡكِتَٰبِ وَمُهَيۡمِنًا عَلَيۡهِۖ فَٱحۡكُم بَيۡنَهُم بِمَآ أَنزَلَ ٱللَّهُۖ وَلَا تَتَّبِعۡ أَهۡوَآءَهُمۡ عَمَّا جَآءَكَ مِنَ ٱلۡحَقِّۚ لِكُلّٖ جَعَلۡنَا مِنكُمۡ شِرۡعَةٗ وَمِنۡهَاجٗاۚ وَلَوۡ شَآءَ ٱللَّهُ لَجَعَلَكُمۡ أُمَّةٗ وَٰحِدَةٗ وَلَٰكِن لِّيَبۡلُوَكُمۡ فِي مَآ ءَاتَىٰكُمۡۖ فَٱسۡتَبِقُواْ ٱلۡخَيۡرَٰتِۚ إِلَى ٱللَّهِ مَرۡجِعُكُمۡ جَمِيعٗا فَيُنَبِّئُكُم بِمَا كُنتُمۡ فِيهِ تَخۡتَلِفُونَ ﴿٤٨﴾ وَأَنِ ٱحۡكُم بَيۡنَهُم بِمَآ أَنزَلَ ٱللَّهُ وَلَا تَتَّبِعۡ أَهۡوَآءَهُمۡ وَٱحۡذَرۡهُمۡ أَن يَفۡتِنُوكَ عَنۢ بَعۡضِ مَآ أَنزَلَ ٱللَّهُ إِلَيۡكَۖ فَإِن تَوَلَّوۡاْ فَٱعۡلَمۡ أَنَّمَا يُرِيدُ ٱللَّهُ أَن يُصِيبَهُم بِبَعۡضِ ذُنُوبِهِمۡۗ وَإِنَّ كَثِيرٗا مِّنَ ٱلنَّاسِ لَفَٰسِقُونَ ﴿٤٩﴾ أَفَحُكۡمَ ٱلۡجَٰهِلِيَّةِ يَبۡغُونَۚ وَمَنۡ أَحۡسَنُ مِنَ ٱللَّهِ حُكۡمٗا لِّقَوۡمٖ يُوقِنُونَ ﴿٥٠﴾", "w": [["من الكتاب", "اسم جنس بمعنى الكتب السابقة كالتوراة والإنجيل."], ["مهيمناً عليه", "حاكماً عليه، محقّقاً للحق الذي فيه، مبطلاً للباطل الذي التصق به."], ["شِرعة ومنهاجاً", "شريعة تعملون بها، وسبيلاً تسلكونه لسعادتكم وكمالكم."], ["أمة واحدة", "لا اختلاف بينكم في عقيدة ولا عبادة ولا قضاء."], ["فاستبقوا", "بادروا فعل الخيرات ليفوز السابقون."], ["أن يفتنوك", "يضلّوك عن الحق."], ["فإن تولّوا", "أعرضوا عن قبول الحق."], ["حكم الجاهلية", "ما عليه أهل الجاهلية من الأحكام القبلية التي لا تقوم على وحي الله، وإنما على الآراء والأهواء."]], "m": "لما ذكر الله التوراة والإنجيل، ذكر القرآن: وأنزلنا إليك الكتاب بالحق، مصدّقاً لما بين يديه من الكتب، ومهيمناً عليها، فالحق ما أحقّه منها والباطل ما أبطله، فاحكم بين المتحاكمين إليك بما أنزل الله، بقتل القاتل ورجم الزاني، لا كما يريد اليهود، ولا تتّبع أهواءهم عما جاءك من الحق. لكلٍّ جعلنا شرعة ومنهاجاً، ولو شاء الله لجعلكم أمة واحدة على شريعة واحدة، ولكن نوّع الشرائع ليبتليكم فيما آتاكم فيتبيّن المطيع من العاصي، فاستبقوا الخيرات، إلى الله مرجعكم جميعاً فينبّئكم بما كنتم فيه تختلفون. ثم أمر رسوله أن يحكم بينهم بما أنزل الله، ونهاه أن يتّبع أهواءهم، وحذّره أن يفتنوه عن بعض ما أنزل الله إليه، وأعلمه أنهم إن تولّوا فإنما يريد الله أن يصيبهم ببعض ذنوبهم، وإن كثيراً من الناس لفاسقون، تسليةً له. ثم أنكر عليهم: أفحكم الجاهلية يبغون، حيث لا وحي ولا تشريع إلهي، وإنما العادات والأهواء؟ ومن أحسن من الله حكماً لقوم يوقنون؟", "h": ["وجوب الحكم في كل القضايا بالكتاب والسنة.", "لا يجوز تحكيم أية شريعة أو قانون غير الوحي الإلهي: الكتاب والسنة.", "التحذير من اتباع أهواء الناس خشية الإضلال عن الحق.", "بيان الحكمة من اختلاف الشرائع، وهي الابتلاء.", "أكثر المصائب في الدنيا ناتجة عن بعض الذنوب.", "حكم الشريعة الإسلامية أحسن الأحكام عدلاً ورحمة."], "k": "«فاستبقوا الخيرات»… ما الخير الذي أسابق إليه اليوم قبل أن يفوتني؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (84, 5, 51, 66, 'سورة المائدة ٥١ – ٦٦', 'لا تتخذوا اليهود والنصارى أولياء، و«يحبهم ويحبونه»، و«بل يداه مبسوطتان»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 84) = $j$[{"lbl": "الآيات ٥١ – ٥٣", "q": "۞يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَتَّخِذُواْ ٱلۡيَهُودَ وَٱلنَّصَٰرَىٰٓ أَوۡلِيَآءَۘ بَعۡضُهُمۡ أَوۡلِيَآءُ بَعۡضٖۚ وَمَن يَتَوَلَّهُم مِّنكُمۡ فَإِنَّهُۥ مِنۡهُمۡۗ إِنَّ ٱللَّهَ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلظَّـٰلِمِينَ ﴿٥١﴾ فَتَرَى ٱلَّذِينَ فِي قُلُوبِهِم مَّرَضٞ يُسَٰرِعُونَ فِيهِمۡ يَقُولُونَ نَخۡشَىٰٓ أَن تُصِيبَنَا دَآئِرَةٞۚ فَعَسَى ٱللَّهُ أَن يَأۡتِيَ بِٱلۡفَتۡحِ أَوۡ أَمۡرٖ مِّنۡ عِندِهِۦ فَيُصۡبِحُواْ عَلَىٰ مَآ أَسَرُّواْ فِيٓ أَنفُسِهِمۡ نَٰدِمِينَ ﴿٥٢﴾ وَيَقُولُ ٱلَّذِينَ ءَامَنُوٓاْ أَهَـٰٓؤُلَآءِ ٱلَّذِينَ أَقۡسَمُواْ بِٱللَّهِ جَهۡدَ أَيۡمَٰنِهِمۡ إِنَّهُمۡ لَمَعَكُمۡۚ حَبِطَتۡ أَعۡمَٰلُهُمۡ فَأَصۡبَحُواْ خَٰسِرِينَ ﴿٥٣﴾", "w": [["آمنوا", "صدّقوا بالله ورسوله ووعد الله ووعيده."], ["أولياء", "توالونهم بالنصرة والمحبة."], ["بعضهم أولياء بعض", "اليهودي ولي أخيه اليهودي، والنصراني ولي أخيه النصراني."], ["الظالمين", "الذين يوالون أعداء الله ورسوله ويتركون موالاة الله ورسوله."], ["مرض", "نفاق وشك وشرك."], ["يسارعون فيهم", "في البقاء على موالاتهم."], ["دائرة", "تدور علينا من جدب أو انتهاء أمر الإسلام."], ["بالفتح", "نصر المؤمنين على الكافرين، كفتح مكة."], ["جهد أيمانهم", "أقصاها وأبلغها."], ["حبطت أعمالهم", "بطلت وفسدت فلم ينتفعوا منها بشيء، لأنها ما كانت لله تعالى."]], "m": "ورد في سبب نزولها أن عبادة بن الصامت الأنصاري وعبد الله بن أُبيّ كان لهما حلفاء من اليهود، فلما أعلن اليهود سوء نياتهم تبرّأ عبادة من حلفائه ورضي بموالاة الله ورسوله والمؤمنين، وأبى ابن أُبيّ ذلك، فنزلت: يا أيها الذين آمنوا لا تتخذوا اليهود والنصارى أولياء، بعضهم أولياء بعض على المسلمين، فكيف تجوز موالاتهم؟ ومن يتولّهم منكم فإنه منهم، لأنه بحكم موالاتهم سيكون حرباً على الله ورسوله والمؤمنين، إن الله لا يهدي القوم الظالمين الذين وضعوا الموالاة في غير محلها. ثم قال لرسوله: فترى الذين في قلوبهم مرض، كابن أُبيّ، يسارعون في موالاتهم، يقولون: نخشى أن تصيبنا دائرة من تقلّب الأحوال فننتفع بأحلافنا، فعسى الله أن يأتي بالفتح، وعسى من الله للتحقيق، أو أمر من عنده فيصبحوا على ما أسرّوا في أنفسهم من النفاق نادمين. ويقول الذين آمنوا عند الفتح، مشيرين إلى المنافقين: أهؤلاء الذين أقسموا بالله جهد أيمانهم إنهم لمعكم؟ حبطت أعمالهم فأصبحوا خاسرين.", "h": ["حرمة موالاة اليهود والنصارى وسائر الكافرين.", "موالاة الكافر على المؤمن تُعتبر ردّة عن الإسلام.", "موالاة الكافرين ناجمة عن ضعف الإيمان، فلذا تؤدي إلى الكفر.", "عاقبة النفاق سيئة، ونهاية الكفر مريرة."], "k": "لمن ولائي ومحبتي ونصرتي؟ وهل يقدّمني ولائي يوم القيامة أم يُخجلني؟"}, {"lbl": "الآيات ٥٤ – ٥٦", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ مَن يَرۡتَدَّ مِنكُمۡ عَن دِينِهِۦ فَسَوۡفَ يَأۡتِي ٱللَّهُ بِقَوۡمٖ يُحِبُّهُمۡ وَيُحِبُّونَهُۥٓ أَذِلَّةٍ عَلَى ٱلۡمُؤۡمِنِينَ أَعِزَّةٍ عَلَى ٱلۡكَٰفِرِينَ يُجَٰهِدُونَ فِي سَبِيلِ ٱللَّهِ وَلَا يَخَافُونَ لَوۡمَةَ لَآئِمٖۚ ذَٰلِكَ فَضۡلُ ٱللَّهِ يُؤۡتِيهِ مَن يَشَآءُۚ وَٱللَّهُ وَٰسِعٌ عَلِيمٌ ﴿٥٤﴾ إِنَّمَا وَلِيُّكُمُ ٱللَّهُ وَرَسُولُهُۥ وَٱلَّذِينَ ءَامَنُواْ ٱلَّذِينَ يُقِيمُونَ ٱلصَّلَوٰةَ وَيُؤۡتُونَ ٱلزَّكَوٰةَ وَهُمۡ رَٰكِعُونَ ﴿٥٥﴾ وَمَن يَتَوَلَّ ٱللَّهَ وَرَسُولَهُۥ وَٱلَّذِينَ ءَامَنُواْ فَإِنَّ حِزۡبَ ٱللَّهِ هُمُ ٱلۡغَٰلِبُونَ ﴿٥٦﴾", "w": [["من يرتدّ", "يرجع إلى الكفر بعد إيمانه."], ["أذلّة على المؤمنين", "أرقّاء عليهم، رحماء بهم."], ["أعزّة على الكافرين", "أشدّاء غلاظ عليهم."], ["لومة لائم", "عذل عاذل."]], "m": "تضمّنت الآية خبراً من أخبار الغيب تمّ طبق ما أخبر، فكان آية أنه كلام الله: من يرتدّ منكم عن دينه فسوف يأتي الله بقوم خير منه، يحبهم ويحبونه، رحماء بالمؤمنين، أشدّاء على الكافرين، يجاهدون في سبيل الله ولا يخافون لومة لائم؛ فما إن مات الرسول ﷺ حتى ارتدّت فئات من الأعراب ومنعوا الزكاة، فقاتلهم أبو بكر الصديق مع الصحابة حتى أخضعوهم للإسلام، فكانوا ممن وصف الله. وصحّ أن النبي ﷺ لما تلاها أشار إلى أبي موسى الأشعري وقال: «قوم هذا»، فجاء الأشعريون بعد وفاته وظهرت الآية. ذلك فضل الله يؤتيه من يشاء، والله واسع عليم. ثم طمأن عبادة بن الصامت وعبد الله بن سلام ومن تبرّأ من حلف اليهود: إنما وليّكم الله ورسوله والذين آمنوا، الذين يقيمون الصلاة ويؤتون الزكاة وهم خاشعون متطامنون، ومن يتولّ الله ورسوله والذين آمنوا ينصره الله ويكفه ما أهمّه، فإن حزب الله هم الغالبون.", "h": ["إخبار القرآن الكريم بالغيب وصدقه في ذلك، فكان آية أنه كلام الله.", "فضيلة أبي بكر والصحابة والأشعريين، قوم أبي موسى الأشعري من أهل اليمن.", "فضل حب الله، والتواضع للمؤمنين، وإظهار العزة على الكافرين، وفضل الجهاد في سبيل الله، وقول الحق والثبات عليه، وعدم المبالاة بمن يلوم.", "فضيلة إقام الصلاة وإيتاء الزكاة والخشوع والتواضع.", "ولاية الله ورسوله والمؤمنين الصادقين توجب لصاحبها النصر والغلبة على أعدائه."], "k": "«يحبهم ويحبونه»… ما علامة حبي لله في يومي؟ وهل أنا رحيم بإخواني، لا أخاف في الحق لومة لائم؟"}, {"lbl": "الآيات ٥٧ – ٦٠", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَتَّخِذُواْ ٱلَّذِينَ ٱتَّخَذُواْ دِينَكُمۡ هُزُوٗا وَلَعِبٗا مِّنَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ مِن قَبۡلِكُمۡ وَٱلۡكُفَّارَ أَوۡلِيَآءَۚ وَٱتَّقُواْ ٱللَّهَ إِن كُنتُم مُّؤۡمِنِينَ ﴿٥٧﴾ وَإِذَا نَادَيۡتُمۡ إِلَى ٱلصَّلَوٰةِ ٱتَّخَذُوهَا هُزُوٗا وَلَعِبٗاۚ ذَٰلِكَ بِأَنَّهُمۡ قَوۡمٞ لَّا يَعۡقِلُونَ ﴿٥٨﴾ قُلۡ يَـٰٓأَهۡلَ ٱلۡكِتَٰبِ هَلۡ تَنقِمُونَ مِنَّآ إِلَّآ أَنۡ ءَامَنَّا بِٱللَّهِ وَمَآ أُنزِلَ إِلَيۡنَا وَمَآ أُنزِلَ مِن قَبۡلُ وَأَنَّ أَكۡثَرَكُمۡ فَٰسِقُونَ ﴿٥٩﴾ قُلۡ هَلۡ أُنَبِّئُكُم بِشَرّٖ مِّن ذَٰلِكَ مَثُوبَةً عِندَ ٱللَّهِۚ مَن لَّعَنَهُ ٱللَّهُ وَغَضِبَ عَلَيۡهِ وَجَعَلَ مِنۡهُمُ ٱلۡقِرَدَةَ وَٱلۡخَنَازِيرَ وَعَبَدَ ٱلطَّـٰغُوتَۚ أُوْلَـٰٓئِكَ شَرّٞ مَّكَانٗا وَأَضَلُّ عَن سَوَآءِ ٱلسَّبِيلِ ﴿٦٠﴾", "w": [["هزواً ولعباً", "الهزء: ما يُستهزأ به ويُسخر منه، واللعب: ما يُلعب به."], ["أوتوا الكتاب", "هم اليهود في هذا السياق."], ["والكفّار", "المشركون والمنافقون."], ["هل تنقمون منا", "ما تنكرون منا وتعيبون علينا."], ["مثوبة", "جزاء."], ["فاسقون", "خارجون عن طاعة الله بالكفر والمعاصي."], ["القردة", "جمع قرد، حيوان مجبول على التقليد والمحاكاة."], ["والخنازير", "جمع خنزير، حيوان خبيث محرّم الأكل."]], "m": "ما زال السياق في تحذير المؤمنين من موالاة أعداء الله: يا أيها الذين آمنوا لا تتخذوا الذين اتخذوا دينكم هزواً ولعباً من اليهود والكفار أولياء، واتقوا الله إن كنتم مؤمنين، فإن حب الله ورسوله يتنافى مع حب أعدائه. ثم ذكر ما يؤكد وجوب معاداتهم: إذا سمعوا الأذان ينادي للصلاة اتخذوه هزواً ولعباً، ذلك بأنهم قوم لا يعقلون، فلو عقلوا لكان النداء إلى الصلاة أطيب ما يسمعون، لأنه نداء إلى الطهر وذكر الله. ثم علّم رسوله أن يقول: يا أهل الكتاب، هل تنكرون منا إلا أن آمنّا بالله وما أنزل إلينا وما أنزل من قبل، وأن أكثركم فاسقون؟ ولما قالوا للنبي ﷺ حين ذكر الإيمان بعيسى: لا نعلم ديناً شراً من دينكم، أنزل الله: قل هل أنبئكم بشرّ من ذلك جزاءً عند الله؟ من لعنه الله وغضب عليه، وجعل منهم القردة والخنازير، وعبد الطاغوت، أولئك شرٌّ مكاناً يوم القيامة، وأضلّ عن سواء السبيل في الدنيا.", "h": ["حرمة اتخاذ اليهود والنصارى والمشركين أولياء، لا سيما أهل الظلم منهم.", "سوء أخلاق اليهود وفساد عقولهم.", "شعور اليهود بفسقهم وبعد ضلالهم جعلهم يعملون على إضلال المسلمين.", "تقرير وجود مسخ في اليهود قردة وخنازير.", "اليهود شرّ الناس مكاناً يوم القيامة، وأضلّ الناس في هذه الدنيا."], "k": "الأذان نداء إلى الطهر وذكر الله… كيف أستقبله: بانشغال، أم بترديد وإجابة؟"}, {"lbl": "الآيات ٦١ – ٦٣", "q": "وَإِذَا جَآءُوكُمۡ قَالُوٓاْ ءَامَنَّا وَقَد دَّخَلُواْ بِٱلۡكُفۡرِ وَهُمۡ قَدۡ خَرَجُواْ بِهِۦۚ وَٱللَّهُ أَعۡلَمُ بِمَا كَانُواْ يَكۡتُمُونَ ﴿٦١﴾ وَتَرَىٰ كَثِيرٗا مِّنۡهُمۡ يُسَٰرِعُونَ فِي ٱلۡإِثۡمِ وَٱلۡعُدۡوَٰنِ وَأَكۡلِهِمُ ٱلسُّحۡتَۚ لَبِئۡسَ مَا كَانُواْ يَعۡمَلُونَ ﴿٦٢﴾ لَوۡلَا يَنۡهَىٰهُمُ ٱلرَّبَّـٰنِيُّونَ وَٱلۡأَحۡبَارُ عَن قَوۡلِهِمُ ٱلۡإِثۡمَ وَأَكۡلِهِمُ ٱلسُّحۡتَۚ لَبِئۡسَ مَا كَانُواْ يَصۡنَعُونَ ﴿٦٣﴾", "w": [["يكتمون", "يُضمرون في نفوسهم ويخفونه."], ["في الإثم والعدوان", "الإثم: كل ضارّ وفاسد مما حرّمه الله من اعتقاد أو قول أو عمل، والعدوان: الظلم."], ["السحت", "المال الحرام كالرشوة والربا، وما يأخذونه مقابل تحريف الكلم وتأويله."], ["الربانيون والأحبار", "الربانيون هنا: العبّاد المربّون، والأحبار: العلماء."]], "m": "ما زال السياق في فضح اليهود زيادةً في التنفير من موالاتهم: وإذا جاؤوكم في مجالسكم قالوا آمنّا، وما آمنوا، فقد دخلوا بالكفر وخرجوا به، والله أعلم بما كانوا يكتمون من الكفر والكيد لكم. وترى كثيراً منهم يسارعون في الإثم والعدوان وأكلهم السحت علناً لا يستترون به، لبئس ما كانوا يعملون. ثم أنكر على عبّادهم وعلمائهم سكوتهم عن جرائم عوامّهم مصانعةً ومداهنة: لولا ينهاهم الربانيون والأحبار عن قولهم الإثم، أي الكذب، وأكلهم السحت، لبئس ما كانوا يصنعون، إذ أصبح السكوت المتعمّد لمنافع خاصة صنعةً لهم أتقنوها.", "h": ["وجود منافقين من اليهود على عهد الرسول ﷺ بالمدينة.", "بيان استهتار اليهود وعدم مبالاتهم بارتكاب الجرائم علانية.", "قبح سكوت العلماء على المنكر وإغضائهم عن فاعليه، ولذا قال كثير من السلف: هذه أشدّ آية وأخطرها على العلماء."], "k": "«لولا ينهاهم الربانيون والأحبار»… هل أسكت عن منكر أستطيع أن أنكره بالحكمة، مجاملةً لأحد؟"}, {"lbl": "الآيات ٦٤ – ٦٦", "q": "وَقَالَتِ ٱلۡيَهُودُ يَدُ ٱللَّهِ مَغۡلُولَةٌۚ غُلَّتۡ أَيۡدِيهِمۡ وَلُعِنُواْ بِمَا قَالُواْۘ بَلۡ يَدَاهُ مَبۡسُوطَتَانِ يُنفِقُ كَيۡفَ يَشَآءُۚ وَلَيَزِيدَنَّ كَثِيرٗا مِّنۡهُم مَّآ أُنزِلَ إِلَيۡكَ مِن رَّبِّكَ طُغۡيَٰنٗا وَكُفۡرٗاۚ وَأَلۡقَيۡنَا بَيۡنَهُمُ ٱلۡعَدَٰوَةَ وَٱلۡبَغۡضَآءَ إِلَىٰ يَوۡمِ ٱلۡقِيَٰمَةِۚ كُلَّمَآ أَوۡقَدُواْ نَارٗا لِّلۡحَرۡبِ أَطۡفَأَهَا ٱللَّهُۚ وَيَسۡعَوۡنَ فِي ٱلۡأَرۡضِ فَسَادٗاۚ وَٱللَّهُ لَا يُحِبُّ ٱلۡمُفۡسِدِينَ ﴿٦٤﴾ وَلَوۡ أَنَّ أَهۡلَ ٱلۡكِتَٰبِ ءَامَنُواْ وَٱتَّقَوۡاْ لَكَفَّرۡنَا عَنۡهُمۡ سَيِّـَٔاتِهِمۡ وَلَأَدۡخَلۡنَٰهُمۡ جَنَّـٰتِ ٱلنَّعِيمِ ﴿٦٥﴾ وَلَوۡ أَنَّهُمۡ أَقَامُواْ ٱلتَّوۡرَىٰةَ وَٱلۡإِنجِيلَ وَمَآ أُنزِلَ إِلَيۡهِم مِّن رَّبِّهِمۡ لَأَكَلُواْ مِن فَوۡقِهِمۡ وَمِن تَحۡتِ أَرۡجُلِهِمۚ مِّنۡهُمۡ أُمَّةٞ مُّقۡتَصِدَةٞۖ وَكَثِيرٞ مِّنۡهُمۡ سَآءَ مَا يَعۡمَلُونَ ﴿٦٦﴾", "w": [["يد الله مغلولة", "يريدون أنه تعالى ضيّق عليهم الرزق ولم يوسّع عليهم."], ["غُلّت أيديهم", "دعاء عليهم بأن يُحرموا الإنفاق في الخير وفيما ينفعهم."], ["لُعنوا بما قالوا", "طُردوا من رحمة الله بسبب وصفهم الرب تعالى بالبخل."], ["بل يداه مبسوطتان", "لا كما قالوا: ممسكة عن الإنفاق."], ["طغياناً", "تجاوزاً لحد الاعتدال في قولهم الكاذب وعملهم الفاسد."], ["وألقينا بينهم", "بين اليهود والنصارى."], ["أوقدوا ناراً", "نار الفتنة والتحريش والعداوات للحرب."], ["من فوقهم ومن تحت أرجلهم", "كناية عن بسط الرزق عليهم."], ["أمة مقتصدة", "معتدلة، لا غالية مُفرِطة ولا جافية مُفرّطة."]], "m": "يخبر الله عن جرأة اليهود عليه: وقالت اليهود يد الله مغلولة، يريدون أنه أمسك عنهم الرزق، فدعا عليهم: غُلّت أيديهم ولُعنوا بما قالوا، وأكذبهم: بل يداه مبسوطتان ينفق كيف يشاء، كما في الصحيح: «يمين الله ملأى، سحّاء الليل والنهار». ثم سلّى نبيه ﷺ: وليزيدنّ كثيراً منهم ما أُنزل إليك من ربك طغياناً وكفراً، دفعاً للحق وتبريراً لباطلهم، وألقينا بينهم وبين النصارى العداوة والبغضاء إلى يوم القيامة، كلما أوقدوا ناراً للحرب بالتحريش بين الأفراد والشعوب أطفأها الله، فأذلّهم على يد رسوله والمؤمنين، ويسعون في الأرض فساداً، والله لا يحب المفسدين. ثم وعد: ولو أن أهل الكتاب آمنوا واتقوا الكفر والشرك والكبائر لكفّر عنهم سيئاتهم ولأدخلهم جنات النعيم. ولو أنهم أقاموا التوراة والإنجيل وما أُنزل إليهم من ربهم، ومنه القرآن، فآمنوا بعقائدها الصحيحة وعملوا بشرائعها، لأكلوا من فوقهم ومن تحت أرجلهم، ولبسط الله عليهم الرزق. منهم أمة مقتصدة لم تغلُ في عيسى ولم تجفُ، فلما جاء النبي الأمي آمنوا به، كعبد الله بن سلام والنجاشي، وكثير منهم ساء ما يعملون.", "h": ["قبح وصف الله تعالى بما لا يليق بجلاله وكماله.", "ثبوت صفة اليدين لله تعالى، ووجوب الإيمان بها على مراد الله وعلى ما يليق بجلاله.", "تقرير ما هو موجود بين اليهود والنصارى من عداوة وبغضاء، وهو من تدبير الله تعالى.", "سعي اليهود الدائم في الفساد في الأرض.", "وعد الله لأهل الكتاب لو آمنوا واتقوا لأدخلهم الجنة.", "وعده تعالى لأهل الكتاب ببسط الرزق وسعته لو أقاموا التوراة والإنجيل وما أُنزل إليهم من ربهم، كما حصل للمسلمين طيلة ثلاثة قرون وزيادة، وما زال العرض قائماً لكل الأمم."], "k": "«لأكلوا من فوقهم ومن تحت أرجلهم»… هل أطلب سعة الرزق بإقامة كتاب الله، قبل الأسباب؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 84;
insert into public.tdb_cards(topic, i, body) select 84, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٥١ – ٥٣", "q": "۞يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَتَّخِذُواْ ٱلۡيَهُودَ وَٱلنَّصَٰرَىٰٓ أَوۡلِيَآءَۘ بَعۡضُهُمۡ أَوۡلِيَآءُ بَعۡضٖۚ وَمَن يَتَوَلَّهُم مِّنكُمۡ فَإِنَّهُۥ مِنۡهُمۡۗ إِنَّ ٱللَّهَ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلظَّـٰلِمِينَ ﴿٥١﴾ فَتَرَى ٱلَّذِينَ فِي قُلُوبِهِم مَّرَضٞ يُسَٰرِعُونَ فِيهِمۡ يَقُولُونَ نَخۡشَىٰٓ أَن تُصِيبَنَا دَآئِرَةٞۚ فَعَسَى ٱللَّهُ أَن يَأۡتِيَ بِٱلۡفَتۡحِ أَوۡ أَمۡرٖ مِّنۡ عِندِهِۦ فَيُصۡبِحُواْ عَلَىٰ مَآ أَسَرُّواْ فِيٓ أَنفُسِهِمۡ نَٰدِمِينَ ﴿٥٢﴾ وَيَقُولُ ٱلَّذِينَ ءَامَنُوٓاْ أَهَـٰٓؤُلَآءِ ٱلَّذِينَ أَقۡسَمُواْ بِٱللَّهِ جَهۡدَ أَيۡمَٰنِهِمۡ إِنَّهُمۡ لَمَعَكُمۡۚ حَبِطَتۡ أَعۡمَٰلُهُمۡ فَأَصۡبَحُواْ خَٰسِرِينَ ﴿٥٣﴾", "w": [["آمنوا", "صدّقوا بالله ورسوله ووعد الله ووعيده."], ["أولياء", "توالونهم بالنصرة والمحبة."], ["بعضهم أولياء بعض", "اليهودي ولي أخيه اليهودي، والنصراني ولي أخيه النصراني."], ["الظالمين", "الذين يوالون أعداء الله ورسوله ويتركون موالاة الله ورسوله."], ["مرض", "نفاق وشك وشرك."], ["يسارعون فيهم", "في البقاء على موالاتهم."], ["دائرة", "تدور علينا من جدب أو انتهاء أمر الإسلام."], ["بالفتح", "نصر المؤمنين على الكافرين، كفتح مكة."], ["جهد أيمانهم", "أقصاها وأبلغها."], ["حبطت أعمالهم", "بطلت وفسدت فلم ينتفعوا منها بشيء، لأنها ما كانت لله تعالى."]], "m": "ورد في سبب نزولها أن عبادة بن الصامت الأنصاري وعبد الله بن أُبيّ كان لهما حلفاء من اليهود، فلما أعلن اليهود سوء نياتهم تبرّأ عبادة من حلفائه ورضي بموالاة الله ورسوله والمؤمنين، وأبى ابن أُبيّ ذلك، فنزلت: يا أيها الذين آمنوا لا تتخذوا اليهود والنصارى أولياء، بعضهم أولياء بعض على المسلمين، فكيف تجوز موالاتهم؟ ومن يتولّهم منكم فإنه منهم، لأنه بحكم موالاتهم سيكون حرباً على الله ورسوله والمؤمنين، إن الله لا يهدي القوم الظالمين الذين وضعوا الموالاة في غير محلها. ثم قال لرسوله: فترى الذين في قلوبهم مرض، كابن أُبيّ، يسارعون في موالاتهم، يقولون: نخشى أن تصيبنا دائرة من تقلّب الأحوال فننتفع بأحلافنا، فعسى الله أن يأتي بالفتح، وعسى من الله للتحقيق، أو أمر من عنده فيصبحوا على ما أسرّوا في أنفسهم من النفاق نادمين. ويقول الذين آمنوا عند الفتح، مشيرين إلى المنافقين: أهؤلاء الذين أقسموا بالله جهد أيمانهم إنهم لمعكم؟ حبطت أعمالهم فأصبحوا خاسرين.", "h": ["حرمة موالاة اليهود والنصارى وسائر الكافرين.", "موالاة الكافر على المؤمن تُعتبر ردّة عن الإسلام.", "موالاة الكافرين ناجمة عن ضعف الإيمان، فلذا تؤدي إلى الكفر.", "عاقبة النفاق سيئة، ونهاية الكفر مريرة."], "k": "لمن ولائي ومحبتي ونصرتي؟ وهل يقدّمني ولائي يوم القيامة أم يُخجلني؟"}, {"lbl": "الآيات ٥٤ – ٥٦", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ مَن يَرۡتَدَّ مِنكُمۡ عَن دِينِهِۦ فَسَوۡفَ يَأۡتِي ٱللَّهُ بِقَوۡمٖ يُحِبُّهُمۡ وَيُحِبُّونَهُۥٓ أَذِلَّةٍ عَلَى ٱلۡمُؤۡمِنِينَ أَعِزَّةٍ عَلَى ٱلۡكَٰفِرِينَ يُجَٰهِدُونَ فِي سَبِيلِ ٱللَّهِ وَلَا يَخَافُونَ لَوۡمَةَ لَآئِمٖۚ ذَٰلِكَ فَضۡلُ ٱللَّهِ يُؤۡتِيهِ مَن يَشَآءُۚ وَٱللَّهُ وَٰسِعٌ عَلِيمٌ ﴿٥٤﴾ إِنَّمَا وَلِيُّكُمُ ٱللَّهُ وَرَسُولُهُۥ وَٱلَّذِينَ ءَامَنُواْ ٱلَّذِينَ يُقِيمُونَ ٱلصَّلَوٰةَ وَيُؤۡتُونَ ٱلزَّكَوٰةَ وَهُمۡ رَٰكِعُونَ ﴿٥٥﴾ وَمَن يَتَوَلَّ ٱللَّهَ وَرَسُولَهُۥ وَٱلَّذِينَ ءَامَنُواْ فَإِنَّ حِزۡبَ ٱللَّهِ هُمُ ٱلۡغَٰلِبُونَ ﴿٥٦﴾", "w": [["من يرتدّ", "يرجع إلى الكفر بعد إيمانه."], ["أذلّة على المؤمنين", "أرقّاء عليهم، رحماء بهم."], ["أعزّة على الكافرين", "أشدّاء غلاظ عليهم."], ["لومة لائم", "عذل عاذل."]], "m": "تضمّنت الآية خبراً من أخبار الغيب تمّ طبق ما أخبر، فكان آية أنه كلام الله: من يرتدّ منكم عن دينه فسوف يأتي الله بقوم خير منه، يحبهم ويحبونه، رحماء بالمؤمنين، أشدّاء على الكافرين، يجاهدون في سبيل الله ولا يخافون لومة لائم؛ فما إن مات الرسول ﷺ حتى ارتدّت فئات من الأعراب ومنعوا الزكاة، فقاتلهم أبو بكر الصديق مع الصحابة حتى أخضعوهم للإسلام، فكانوا ممن وصف الله. وصحّ أن النبي ﷺ لما تلاها أشار إلى أبي موسى الأشعري وقال: «قوم هذا»، فجاء الأشعريون بعد وفاته وظهرت الآية. ذلك فضل الله يؤتيه من يشاء، والله واسع عليم. ثم طمأن عبادة بن الصامت وعبد الله بن سلام ومن تبرّأ من حلف اليهود: إنما وليّكم الله ورسوله والذين آمنوا، الذين يقيمون الصلاة ويؤتون الزكاة وهم خاشعون متطامنون، ومن يتولّ الله ورسوله والذين آمنوا ينصره الله ويكفه ما أهمّه، فإن حزب الله هم الغالبون.", "h": ["إخبار القرآن الكريم بالغيب وصدقه في ذلك، فكان آية أنه كلام الله.", "فضيلة أبي بكر والصحابة والأشعريين، قوم أبي موسى الأشعري من أهل اليمن.", "فضل حب الله، والتواضع للمؤمنين، وإظهار العزة على الكافرين، وفضل الجهاد في سبيل الله، وقول الحق والثبات عليه، وعدم المبالاة بمن يلوم.", "فضيلة إقام الصلاة وإيتاء الزكاة والخشوع والتواضع.", "ولاية الله ورسوله والمؤمنين الصادقين توجب لصاحبها النصر والغلبة على أعدائه."], "k": "«يحبهم ويحبونه»… ما علامة حبي لله في يومي؟ وهل أنا رحيم بإخواني، لا أخاف في الحق لومة لائم؟"}, {"lbl": "الآيات ٥٧ – ٦٠", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَتَّخِذُواْ ٱلَّذِينَ ٱتَّخَذُواْ دِينَكُمۡ هُزُوٗا وَلَعِبٗا مِّنَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ مِن قَبۡلِكُمۡ وَٱلۡكُفَّارَ أَوۡلِيَآءَۚ وَٱتَّقُواْ ٱللَّهَ إِن كُنتُم مُّؤۡمِنِينَ ﴿٥٧﴾ وَإِذَا نَادَيۡتُمۡ إِلَى ٱلصَّلَوٰةِ ٱتَّخَذُوهَا هُزُوٗا وَلَعِبٗاۚ ذَٰلِكَ بِأَنَّهُمۡ قَوۡمٞ لَّا يَعۡقِلُونَ ﴿٥٨﴾ قُلۡ يَـٰٓأَهۡلَ ٱلۡكِتَٰبِ هَلۡ تَنقِمُونَ مِنَّآ إِلَّآ أَنۡ ءَامَنَّا بِٱللَّهِ وَمَآ أُنزِلَ إِلَيۡنَا وَمَآ أُنزِلَ مِن قَبۡلُ وَأَنَّ أَكۡثَرَكُمۡ فَٰسِقُونَ ﴿٥٩﴾ قُلۡ هَلۡ أُنَبِّئُكُم بِشَرّٖ مِّن ذَٰلِكَ مَثُوبَةً عِندَ ٱللَّهِۚ مَن لَّعَنَهُ ٱللَّهُ وَغَضِبَ عَلَيۡهِ وَجَعَلَ مِنۡهُمُ ٱلۡقِرَدَةَ وَٱلۡخَنَازِيرَ وَعَبَدَ ٱلطَّـٰغُوتَۚ أُوْلَـٰٓئِكَ شَرّٞ مَّكَانٗا وَأَضَلُّ عَن سَوَآءِ ٱلسَّبِيلِ ﴿٦٠﴾", "w": [["هزواً ولعباً", "الهزء: ما يُستهزأ به ويُسخر منه، واللعب: ما يُلعب به."], ["أوتوا الكتاب", "هم اليهود في هذا السياق."], ["والكفّار", "المشركون والمنافقون."], ["هل تنقمون منا", "ما تنكرون منا وتعيبون علينا."], ["مثوبة", "جزاء."], ["فاسقون", "خارجون عن طاعة الله بالكفر والمعاصي."], ["القردة", "جمع قرد، حيوان مجبول على التقليد والمحاكاة."], ["والخنازير", "جمع خنزير، حيوان خبيث محرّم الأكل."]], "m": "ما زال السياق في تحذير المؤمنين من موالاة أعداء الله: يا أيها الذين آمنوا لا تتخذوا الذين اتخذوا دينكم هزواً ولعباً من اليهود والكفار أولياء، واتقوا الله إن كنتم مؤمنين، فإن حب الله ورسوله يتنافى مع حب أعدائه. ثم ذكر ما يؤكد وجوب معاداتهم: إذا سمعوا الأذان ينادي للصلاة اتخذوه هزواً ولعباً، ذلك بأنهم قوم لا يعقلون، فلو عقلوا لكان النداء إلى الصلاة أطيب ما يسمعون، لأنه نداء إلى الطهر وذكر الله. ثم علّم رسوله أن يقول: يا أهل الكتاب، هل تنكرون منا إلا أن آمنّا بالله وما أنزل إلينا وما أنزل من قبل، وأن أكثركم فاسقون؟ ولما قالوا للنبي ﷺ حين ذكر الإيمان بعيسى: لا نعلم ديناً شراً من دينكم، أنزل الله: قل هل أنبئكم بشرّ من ذلك جزاءً عند الله؟ من لعنه الله وغضب عليه، وجعل منهم القردة والخنازير، وعبد الطاغوت، أولئك شرٌّ مكاناً يوم القيامة، وأضلّ عن سواء السبيل في الدنيا.", "h": ["حرمة اتخاذ اليهود والنصارى والمشركين أولياء، لا سيما أهل الظلم منهم.", "سوء أخلاق اليهود وفساد عقولهم.", "شعور اليهود بفسقهم وبعد ضلالهم جعلهم يعملون على إضلال المسلمين.", "تقرير وجود مسخ في اليهود قردة وخنازير.", "اليهود شرّ الناس مكاناً يوم القيامة، وأضلّ الناس في هذه الدنيا."], "k": "الأذان نداء إلى الطهر وذكر الله… كيف أستقبله: بانشغال، أم بترديد وإجابة؟"}, {"lbl": "الآيات ٦١ – ٦٣", "q": "وَإِذَا جَآءُوكُمۡ قَالُوٓاْ ءَامَنَّا وَقَد دَّخَلُواْ بِٱلۡكُفۡرِ وَهُمۡ قَدۡ خَرَجُواْ بِهِۦۚ وَٱللَّهُ أَعۡلَمُ بِمَا كَانُواْ يَكۡتُمُونَ ﴿٦١﴾ وَتَرَىٰ كَثِيرٗا مِّنۡهُمۡ يُسَٰرِعُونَ فِي ٱلۡإِثۡمِ وَٱلۡعُدۡوَٰنِ وَأَكۡلِهِمُ ٱلسُّحۡتَۚ لَبِئۡسَ مَا كَانُواْ يَعۡمَلُونَ ﴿٦٢﴾ لَوۡلَا يَنۡهَىٰهُمُ ٱلرَّبَّـٰنِيُّونَ وَٱلۡأَحۡبَارُ عَن قَوۡلِهِمُ ٱلۡإِثۡمَ وَأَكۡلِهِمُ ٱلسُّحۡتَۚ لَبِئۡسَ مَا كَانُواْ يَصۡنَعُونَ ﴿٦٣﴾", "w": [["يكتمون", "يُضمرون في نفوسهم ويخفونه."], ["في الإثم والعدوان", "الإثم: كل ضارّ وفاسد مما حرّمه الله من اعتقاد أو قول أو عمل، والعدوان: الظلم."], ["السحت", "المال الحرام كالرشوة والربا، وما يأخذونه مقابل تحريف الكلم وتأويله."], ["الربانيون والأحبار", "الربانيون هنا: العبّاد المربّون، والأحبار: العلماء."]], "m": "ما زال السياق في فضح اليهود زيادةً في التنفير من موالاتهم: وإذا جاؤوكم في مجالسكم قالوا آمنّا، وما آمنوا، فقد دخلوا بالكفر وخرجوا به، والله أعلم بما كانوا يكتمون من الكفر والكيد لكم. وترى كثيراً منهم يسارعون في الإثم والعدوان وأكلهم السحت علناً لا يستترون به، لبئس ما كانوا يعملون. ثم أنكر على عبّادهم وعلمائهم سكوتهم عن جرائم عوامّهم مصانعةً ومداهنة: لولا ينهاهم الربانيون والأحبار عن قولهم الإثم، أي الكذب، وأكلهم السحت، لبئس ما كانوا يصنعون، إذ أصبح السكوت المتعمّد لمنافع خاصة صنعةً لهم أتقنوها.", "h": ["وجود منافقين من اليهود على عهد الرسول ﷺ بالمدينة.", "بيان استهتار اليهود وعدم مبالاتهم بارتكاب الجرائم علانية.", "قبح سكوت العلماء على المنكر وإغضائهم عن فاعليه، ولذا قال كثير من السلف: هذه أشدّ آية وأخطرها على العلماء."], "k": "«لولا ينهاهم الربانيون والأحبار»… هل أسكت عن منكر أستطيع أن أنكره بالحكمة، مجاملةً لأحد؟"}, {"lbl": "الآيات ٦٤ – ٦٦", "q": "وَقَالَتِ ٱلۡيَهُودُ يَدُ ٱللَّهِ مَغۡلُولَةٌۚ غُلَّتۡ أَيۡدِيهِمۡ وَلُعِنُواْ بِمَا قَالُواْۘ بَلۡ يَدَاهُ مَبۡسُوطَتَانِ يُنفِقُ كَيۡفَ يَشَآءُۚ وَلَيَزِيدَنَّ كَثِيرٗا مِّنۡهُم مَّآ أُنزِلَ إِلَيۡكَ مِن رَّبِّكَ طُغۡيَٰنٗا وَكُفۡرٗاۚ وَأَلۡقَيۡنَا بَيۡنَهُمُ ٱلۡعَدَٰوَةَ وَٱلۡبَغۡضَآءَ إِلَىٰ يَوۡمِ ٱلۡقِيَٰمَةِۚ كُلَّمَآ أَوۡقَدُواْ نَارٗا لِّلۡحَرۡبِ أَطۡفَأَهَا ٱللَّهُۚ وَيَسۡعَوۡنَ فِي ٱلۡأَرۡضِ فَسَادٗاۚ وَٱللَّهُ لَا يُحِبُّ ٱلۡمُفۡسِدِينَ ﴿٦٤﴾ وَلَوۡ أَنَّ أَهۡلَ ٱلۡكِتَٰبِ ءَامَنُواْ وَٱتَّقَوۡاْ لَكَفَّرۡنَا عَنۡهُمۡ سَيِّـَٔاتِهِمۡ وَلَأَدۡخَلۡنَٰهُمۡ جَنَّـٰتِ ٱلنَّعِيمِ ﴿٦٥﴾ وَلَوۡ أَنَّهُمۡ أَقَامُواْ ٱلتَّوۡرَىٰةَ وَٱلۡإِنجِيلَ وَمَآ أُنزِلَ إِلَيۡهِم مِّن رَّبِّهِمۡ لَأَكَلُواْ مِن فَوۡقِهِمۡ وَمِن تَحۡتِ أَرۡجُلِهِمۚ مِّنۡهُمۡ أُمَّةٞ مُّقۡتَصِدَةٞۖ وَكَثِيرٞ مِّنۡهُمۡ سَآءَ مَا يَعۡمَلُونَ ﴿٦٦﴾", "w": [["يد الله مغلولة", "يريدون أنه تعالى ضيّق عليهم الرزق ولم يوسّع عليهم."], ["غُلّت أيديهم", "دعاء عليهم بأن يُحرموا الإنفاق في الخير وفيما ينفعهم."], ["لُعنوا بما قالوا", "طُردوا من رحمة الله بسبب وصفهم الرب تعالى بالبخل."], ["بل يداه مبسوطتان", "لا كما قالوا: ممسكة عن الإنفاق."], ["طغياناً", "تجاوزاً لحد الاعتدال في قولهم الكاذب وعملهم الفاسد."], ["وألقينا بينهم", "بين اليهود والنصارى."], ["أوقدوا ناراً", "نار الفتنة والتحريش والعداوات للحرب."], ["من فوقهم ومن تحت أرجلهم", "كناية عن بسط الرزق عليهم."], ["أمة مقتصدة", "معتدلة، لا غالية مُفرِطة ولا جافية مُفرّطة."]], "m": "يخبر الله عن جرأة اليهود عليه: وقالت اليهود يد الله مغلولة، يريدون أنه أمسك عنهم الرزق، فدعا عليهم: غُلّت أيديهم ولُعنوا بما قالوا، وأكذبهم: بل يداه مبسوطتان ينفق كيف يشاء، كما في الصحيح: «يمين الله ملأى، سحّاء الليل والنهار». ثم سلّى نبيه ﷺ: وليزيدنّ كثيراً منهم ما أُنزل إليك من ربك طغياناً وكفراً، دفعاً للحق وتبريراً لباطلهم، وألقينا بينهم وبين النصارى العداوة والبغضاء إلى يوم القيامة، كلما أوقدوا ناراً للحرب بالتحريش بين الأفراد والشعوب أطفأها الله، فأذلّهم على يد رسوله والمؤمنين، ويسعون في الأرض فساداً، والله لا يحب المفسدين. ثم وعد: ولو أن أهل الكتاب آمنوا واتقوا الكفر والشرك والكبائر لكفّر عنهم سيئاتهم ولأدخلهم جنات النعيم. ولو أنهم أقاموا التوراة والإنجيل وما أُنزل إليهم من ربهم، ومنه القرآن، فآمنوا بعقائدها الصحيحة وعملوا بشرائعها، لأكلوا من فوقهم ومن تحت أرجلهم، ولبسط الله عليهم الرزق. منهم أمة مقتصدة لم تغلُ في عيسى ولم تجفُ، فلما جاء النبي الأمي آمنوا به، كعبد الله بن سلام والنجاشي، وكثير منهم ساء ما يعملون.", "h": ["قبح وصف الله تعالى بما لا يليق بجلاله وكماله.", "ثبوت صفة اليدين لله تعالى، ووجوب الإيمان بها على مراد الله وعلى ما يليق بجلاله.", "تقرير ما هو موجود بين اليهود والنصارى من عداوة وبغضاء، وهو من تدبير الله تعالى.", "سعي اليهود الدائم في الفساد في الأرض.", "وعد الله لأهل الكتاب لو آمنوا واتقوا لأدخلهم الجنة.", "وعده تعالى لأهل الكتاب ببسط الرزق وسعته لو أقاموا التوراة والإنجيل وما أُنزل إليهم من ربهم، كما حصل للمسلمين طيلة ثلاثة قرون وزيادة، وما زال العرض قائماً لكل الأمم."], "k": "«لأكلوا من فوقهم ومن تحت أرجلهم»… هل أطلب سعة الرزق بإقامة كتاب الله، قبل الأسباب؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (85, 5, 67, 81, 'سورة المائدة ٦٧ – ٨١', '«بلّغ ما أُنزل إليك»، وإبطال التثليث، و«كانوا لا يتناهون عن منكر فعلوه»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 85) = $j$[{"lbl": "الآيات ٦٧ – ٦٩", "q": "۞يَـٰٓأَيُّهَا ٱلرَّسُولُ بَلِّغۡ مَآ أُنزِلَ إِلَيۡكَ مِن رَّبِّكَۖ وَإِن لَّمۡ تَفۡعَلۡ فَمَا بَلَّغۡتَ رِسَالَتَهُۥۚ وَٱللَّهُ يَعۡصِمُكَ مِنَ ٱلنَّاسِۗ إِنَّ ٱللَّهَ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلۡكَٰفِرِينَ ﴿٦٧﴾ قُلۡ يَـٰٓأَهۡلَ ٱلۡكِتَٰبِ لَسۡتُمۡ عَلَىٰ شَيۡءٍ حَتَّىٰ تُقِيمُواْ ٱلتَّوۡرَىٰةَ وَٱلۡإِنجِيلَ وَمَآ أُنزِلَ إِلَيۡكُم مِّن رَّبِّكُمۡۗ وَلَيَزِيدَنَّ كَثِيرٗا مِّنۡهُم مَّآ أُنزِلَ إِلَيۡكَ مِن رَّبِّكَ طُغۡيَٰنٗا وَكُفۡرٗاۖ فَلَا تَأۡسَ عَلَى ٱلۡقَوۡمِ ٱلۡكَٰفِرِينَ ﴿٦٨﴾ إِنَّ ٱلَّذِينَ ءَامَنُواْ وَٱلَّذِينَ هَادُواْ وَٱلصَّـٰبِـُٔونَ وَٱلنَّصَٰرَىٰ مَنۡ ءَامَنَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ وَعَمِلَ صَٰلِحٗا فَلَا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَنُونَ ﴿٦٩﴾", "w": [["الرسول", "ذكر من بني آدم أُوحي إليه شرع وأُمر بتبليغه، وهو هنا محمد ﷺ."], ["بلّغ ما أُنزل إليك", "من التوحيد والشرائع والأحكام."], ["يعصمك", "يحفظك حفظاً لا يصل إليك معه أحد بسوء."], ["هادوا", "اليهود."], ["الصابئون", "جمع صابئ، وهم فرقة من أهل الكتاب."]], "m": "ينادي الله رسوله معظّماً له: يا أيها الرسول بلّغ ما أُنزل إليك من ربك من العقائد والشرائع والأحكام، وإن لم تفعل، أي إن قصّرت في شيء لم تبلّغه، فما بلّغت رسالته، والله يعصمك من الناس، فلا عذر لك في ترك إبلاغ أي شيء، ولذا لم يكتم رسول الله ﷺ شيئاً مما أُمر بإبلاغه البتة، إن الله لا يهدي القوم الكافرين لما يريدون من أذيته، ولما نزلت قال ﷺ: «لا تحرسوني فإن الله قد عصمني». ثم قال: قل يا أهل الكتاب لستم على شيء من الدين الحق حتى تقيموا التوراة والإنجيل وما أُنزل إليكم من ربكم، والقرآن أيضاً، وليزيدنّ كثيراً منهم ما أُنزل إليك طغياناً وكفراً، فلا تحزن على القوم الكافرين. ثم قال: إن الذين آمنوا، وهم المسلمون، والذين هادوا والصابئون والنصارى، من آمن منهم الإيمان الحق بالله واليوم الآخر وعمل صالحاً، فلا خوف عليهم ولا هم يحزنون.", "h": ["وجوب البلاغ على الرسل، ونهوض رسولنا محمد ﷺ بهذا الواجب على أكمل وجه وأتمّه.", "عصمة الرسول ﷺ المطلقة.", "كفر أهل الكتاب، إلا من آمن منهم بالنبي محمد ﷺ واتبع ما جاء به من الدين الحق.", "أهل العناد والمكابرة لا تزيدهم الأدلة والبراهين إلا عتوّاً ونفوراً وطغياناً وكفراً.", "العبرة بالإيمان والعمل الصالح وترك الشرك والمعاصي، لا بالانتساب إلى دين من الأديان."], "k": "«بلّغ ما أُنزل إليك»… ما الآية أو الحديث الذي تعلّمته ولم أبلّغه لأحد بعد؟"}, {"lbl": "الآيات ٧٠ – ٧٢", "q": "لَقَدۡ أَخَذۡنَا مِيثَٰقَ بَنِيٓ إِسۡرَـٰٓءِيلَ وَأَرۡسَلۡنَآ إِلَيۡهِمۡ رُسُلٗاۖ كُلَّمَا جَآءَهُمۡ رَسُولُۢ بِمَا لَا تَهۡوَىٰٓ أَنفُسُهُمۡ فَرِيقٗا كَذَّبُواْ وَفَرِيقٗا يَقۡتُلُونَ ﴿٧٠﴾ وَحَسِبُوٓاْ أَلَّا تَكُونَ فِتۡنَةٞ فَعَمُواْ وَصَمُّواْ ثُمَّ تَابَ ٱللَّهُ عَلَيۡهِمۡ ثُمَّ عَمُواْ وَصَمُّواْ كَثِيرٞ مِّنۡهُمۡۚ وَٱللَّهُ بَصِيرُۢ بِمَا يَعۡمَلُونَ ﴿٧١﴾ لَقَدۡ كَفَرَ ٱلَّذِينَ قَالُوٓاْ إِنَّ ٱللَّهَ هُوَ ٱلۡمَسِيحُ ٱبۡنُ مَرۡيَمَۖ وَقَالَ ٱلۡمَسِيحُ يَٰبَنِيٓ إِسۡرَـٰٓءِيلَ ٱعۡبُدُواْ ٱللَّهَ رَبِّي وَرَبَّكُمۡۖ إِنَّهُۥ مَن يُشۡرِكۡ بِٱللَّهِ فَقَدۡ حَرَّمَ ٱللَّهُ عَلَيۡهِ ٱلۡجَنَّةَ وَمَأۡوَىٰهُ ٱلنَّارُۖ وَمَا لِلظَّـٰلِمِينَ مِنۡ أَنصَارٖ ﴿٧٢﴾", "w": [["الميثاق", "العهد المؤكد باليمين."], ["بما لا تهوى أنفسهم", "بما لا يحبونه ولا تميل إليه أنفسهم المريضة."], ["فريقاً كذّبوا", "كذّبوا طائفة من الرسل، وقتلوا طائفة أخرى."], ["ألا تكون فتنة", "ألا يُبتلوا بذنوبهم بالشدائد والمحن."], ["فعموا وصمّوا", "عموا عن العِبر، وصمّوا عن سماع المواعظ."], ["من يشرك بالله", "يعبد مع الله غيره بأي نوع من العبادات."], ["حرّم الله عليه الجنة", "حكم بمنعه من دخولها أبداً، إلا أن يتوب من الشرك."]], "m": "ما زال السياق في أهل الكتاب: أقسم الله أنه أخذ ميثاق بني إسرائيل في التوراة أن يعبدوه وحده ويطيعوه، وأرسل إليهم رسله تترى، كلما جاءهم رسول بما لا يوافق أهواءهم كذّبوه أو قتلوه، وحسبوا ألا يؤاخذوا بذنوبهم، فعموا عن الحق وصمّوا عن المواعظ، فسلّط عليهم من سامهم سوء العذاب، ثم تاب الله عليهم فاستقام أمرهم، ثم عموا وصمّوا مرة أخرى كثير منهم، والله بصير بما يعملون. ثم قرّر حكمه بالكفر على من قالوا إن الله هو المسيح ابن مريم، وحاشا عيسى أن يرضى بذلك، وهو القائل: يا بني إسرائيل اعبدوا الله ربي وربكم، إنه من يشرك بالله فقد حرّم الله عليه الجنة ومأواه النار، وما للظالمين من أنصار، فهل يصدر هذا عمن يدّعي أنه الله؟ سبحانك هذا بهتان عظيم.", "h": ["بيان تاريخ بني إسرائيل، والكشف عن مخبّآت جرائمهم من الكفر والقتل.", "إكرام الله تعالى لبني إسرائيل ولطفه بهم مع تمرّدهم عليه ورفض ميثاقه وقتل أنبيائه وتكذيبهم.", "تقرير كفر النصارى بقولهم: المسيح هو الله.", "تقرير عبودية عيسى ﵇ لربه تعالى."], "k": "«فعموا وصمّوا»… هل مرّت بي عِبرة أو موعظة ولم أنتفع بها؟"}, {"lbl": "الآيات ٧٣ – ٧٦", "q": "لَّقَدۡ كَفَرَ ٱلَّذِينَ قَالُوٓاْ إِنَّ ٱللَّهَ ثَالِثُ ثَلَٰثَةٖۘ وَمَا مِنۡ إِلَٰهٍ إِلَّآ إِلَٰهٞ وَٰحِدٞۚ وَإِن لَّمۡ يَنتَهُواْ عَمَّا يَقُولُونَ لَيَمَسَّنَّ ٱلَّذِينَ كَفَرُواْ مِنۡهُمۡ عَذَابٌ أَلِيمٌ ﴿٧٣﴾ أَفَلَا يَتُوبُونَ إِلَى ٱللَّهِ وَيَسۡتَغۡفِرُونَهُۥۚ وَٱللَّهُ غَفُورٞ رَّحِيمٞ ﴿٧٤﴾ مَّا ٱلۡمَسِيحُ ٱبۡنُ مَرۡيَمَ إِلَّا رَسُولٞ قَدۡ خَلَتۡ مِن قَبۡلِهِ ٱلرُّسُلُ وَأُمُّهُۥ صِدِّيقَةٞۖ كَانَا يَأۡكُلَانِ ٱلطَّعَامَۗ ٱنظُرۡ كَيۡفَ نُبَيِّنُ لَهُمُ ٱلۡأٓيَٰتِ ثُمَّ ٱنظُرۡ أَنَّىٰ يُؤۡفَكُونَ ﴿٧٥﴾ قُلۡ أَتَعۡبُدُونَ مِن دُونِ ٱللَّهِ مَا لَا يَمۡلِكُ لَكُمۡ ضَرّٗا وَلَا نَفۡعٗاۚ وَٱللَّهُ هُوَ ٱلسَّمِيعُ ٱلۡعَلِيمُ ﴿٧٦﴾", "w": [["ثالث ثلاثة", "الثلاثة عندهم: الأب والابن وروح القدس، وكلها إله واحد."], ["خلت من قبله الرسل", "مضت قبله رسل كثيرون."], ["وأمه صدّيقة", "كانت مريم كثيرة الصدق في قولها وعملها."], ["أنّى يؤفكون", "كيف يُصرفون عن الحق وقد ظهر واضحاً؟"]], "m": "ما زال السياق في بيان كفر النصارى: لقد كفر الذين قالوا إن الله ثالث ثلاثة، يعنون الأب والابن وروح القدس، فأكذبهم الله: وما من إله إلا إله واحد؛ فجبريل أحد ملائكته، وعيسى عبده ورسوله، ومريم أمته، والكل عبيد لله، وإن لم ينتهوا عما يقولون ليمسّنّ الذين كفروا منهم عذاب أليم. ثم دعاهم لكمال رحمته إلى التوبة: أفلا يتوبون إلى الله ويستغفرونه، والله غفور رحيم؟ ثم علّم رسوله الاحتجاج: ما المسيح ابن مريم إلا رسول قد خلت من قبله الرسل، وأمه صدّيقة لا تعرف الكذب، كانا يأكلان الطعام احتياجاً إليه، فهل من يأكل الطعام افتقاراً إليه ثم يُخرج فضلاته يصلح أن يكون إلهاً؟ انظر كيف نبيّن لهم الآيات ثم انظر أنّى يُصرفون عنها. ثم أمره أن يوبّخهم: أتعبدون من دون الله ما لا يملك لكم ضراً ولا نفعاً، وتتركون من يملك ذلك، والله هو السميع العليم؟", "h": ["إبطال التثليث في عقيدة النصارى، وتقرير التوحيد.", "إبراء عيسى ووالدته ﵉ من دعوى الألوهية لهما.", "فتح باب التوبة في وجه النصارى لو أنهم يتوبون.", "تقرير بشرية عيسى ومريم ﵉، بدليل احتياجهما إلى الطعام لقوام بنيتهما، ومن كان مفتقراً لا تصح ألوهيته عقلاً وشرعاً.", "ذم كل من يعبد غير الله، إذ كل الخلائق مفتقرة لا تملك لنفسها ولا لعابدها ضراً ولا نفعاً، والله وحده السميع العليم، فهو المعبود بحق."], "k": "«أفلا يتوبون إلى الله ويستغفرونه»… باب التوبة مفتوح حتى لمن قال أعظم الباطل، فما الذي يؤخّرني عنه؟"}, {"lbl": "الآيات ٧٧ – ٨١", "q": "قُلۡ يَـٰٓأَهۡلَ ٱلۡكِتَٰبِ لَا تَغۡلُواْ فِي دِينِكُمۡ غَيۡرَ ٱلۡحَقِّ وَلَا تَتَّبِعُوٓاْ أَهۡوَآءَ قَوۡمٖ قَدۡ ضَلُّواْ مِن قَبۡلُ وَأَضَلُّواْ كَثِيرٗا وَضَلُّواْ عَن سَوَآءِ ٱلسَّبِيلِ ﴿٧٧﴾ لُعِنَ ٱلَّذِينَ كَفَرُواْ مِنۢ بَنِيٓ إِسۡرَـٰٓءِيلَ عَلَىٰ لِسَانِ دَاوُۥدَ وَعِيسَى ٱبۡنِ مَرۡيَمَۚ ذَٰلِكَ بِمَا عَصَواْ وَّكَانُواْ يَعۡتَدُونَ ﴿٧٨﴾ كَانُواْ لَا يَتَنَاهَوۡنَ عَن مُّنكَرٖ فَعَلُوهُۚ لَبِئۡسَ مَا كَانُواْ يَفۡعَلُونَ ﴿٧٩﴾ تَرَىٰ كَثِيرٗا مِّنۡهُمۡ يَتَوَلَّوۡنَ ٱلَّذِينَ كَفَرُواْۚ لَبِئۡسَ مَا قَدَّمَتۡ لَهُمۡ أَنفُسُهُمۡ أَن سَخِطَ ٱللَّهُ عَلَيۡهِمۡ وَفِي ٱلۡعَذَابِ هُمۡ خَٰلِدُونَ ﴿٨٠﴾ وَلَوۡ كَانُواْ يُؤۡمِنُونَ بِٱللَّهِ وَٱلنَّبِيِّ وَمَآ أُنزِلَ إِلَيۡهِ مَا ٱتَّخَذُوهُمۡ أَوۡلِيَآءَ وَلَٰكِنَّ كَثِيرٗا مِّنۡهُمۡ فَٰسِقُونَ ﴿٨١﴾", "w": [["لا تغلوا في دينكم", "الغلو: الإفراط في الشيء ومجاوزة الحد فيه."], ["أهواء قوم قد ضلّوا", "جمع هوى، وصاحب الهوى هو الذي يعتقد ويقول ويعمل بهواه، لا بما قام عليه الدليل من دين الله."], ["وأضلّوا كثيراً", "أضلّوا عدداً كثيراً من الناس بأهوائهم وأباطيلهم."], ["عن سواء السبيل", "وسط الطريق العدل، لا ميل فيه."], ["لُعن", "دُعي عليهم باللعنة، وهي الإبعاد من الخير والرحمة."], ["بما عصوا وكانوا يعتدون", "بسبب عصيانهم رسلهم واعتدائهم في دينهم."], ["لا يتناهون", "لا ينهى بعضهم بعضاً عن المنكر."], ["يتولّون الذين كفروا", "يوادّونهم ويتعاونون معهم دون المؤمنين."]], "m": "ما زال السياق في أهل الكتاب: قل يا أهل الكتاب، والمراد هنا النصارى، لا تغلوا في دينكم غير الحق، فتبتدعوا البدع وتتغالوا في التمسك بها، فالتشدّد محمود في الحق الذي أمر الله به لا في المحدثات، ولا تتّبعوا أهواء قوم قد ضلّوا من قبل، وهم اليهود، إذ قالوا في عيسى ساحر وفي أمه بغيّ، وأضلّوا كثيراً، وضلّوا عن سواء السبيل. ثم أخبر أن الذين كفروا من بني إسرائيل لُعنوا على لسان داود وعيسى ابن مريم ومحمد ﷺ، بعصيانهم واعتدائهم، وذكر نوع عصيانهم: كانوا لا يتناهون عن منكر فعلوه، كما قال ﷺ: «إن أول ما دخل النقص على بني إسرائيل أنه كان الرجل يلقى الرجل فيقول: يا هذا اتق الله ودع ما تصنع، ثم يلقاه من الغد وهو على حاله فلا يمنعه ذلك أن يكون أكيله وشريبه وقعيده»، فضرب الله قلوب بعضهم ببعض، لبئس ما كانوا يفعلون. ترى كثيراً منهم، من يهود المدينة، يتولّون المشركين والمنافقين، لبئس ما قدّمت لهم أنفسهم: أن سخط الله عليهم وفي العذاب هم خالدون، ولو كانوا يؤمنون بالله والنبي وما أُنزل إليه ما اتخذوهم أولياء، ولكن كثيراً منهم فاسقون.", "h": ["حرمة الغلو والابتداع في الدين، واتباع أهل الأهواء.", "العصيان والاعتداء ينتجان لصاحبهما الحرمان والخسران.", "حرمة السكوت عن المنكر، ووخامة عاقبته على المجتمع.", "حرمة موالاة أهل الكفر والشر والفساد.", "موالاة أهل الكفر بالمودة والنصرة دون المؤمنين آية الكفر وعلامته في صاحبه."], "k": "«كانوا لا يتناهون عن منكر فعلوه»… هل يمنعني الحرج أو المجاملة من نصح صديق أحبه؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 85;
insert into public.tdb_cards(topic, i, body) select 85, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٦٧ – ٦٩", "q": "۞يَـٰٓأَيُّهَا ٱلرَّسُولُ بَلِّغۡ مَآ أُنزِلَ إِلَيۡكَ مِن رَّبِّكَۖ وَإِن لَّمۡ تَفۡعَلۡ فَمَا بَلَّغۡتَ رِسَالَتَهُۥۚ وَٱللَّهُ يَعۡصِمُكَ مِنَ ٱلنَّاسِۗ إِنَّ ٱللَّهَ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلۡكَٰفِرِينَ ﴿٦٧﴾ قُلۡ يَـٰٓأَهۡلَ ٱلۡكِتَٰبِ لَسۡتُمۡ عَلَىٰ شَيۡءٍ حَتَّىٰ تُقِيمُواْ ٱلتَّوۡرَىٰةَ وَٱلۡإِنجِيلَ وَمَآ أُنزِلَ إِلَيۡكُم مِّن رَّبِّكُمۡۗ وَلَيَزِيدَنَّ كَثِيرٗا مِّنۡهُم مَّآ أُنزِلَ إِلَيۡكَ مِن رَّبِّكَ طُغۡيَٰنٗا وَكُفۡرٗاۖ فَلَا تَأۡسَ عَلَى ٱلۡقَوۡمِ ٱلۡكَٰفِرِينَ ﴿٦٨﴾ إِنَّ ٱلَّذِينَ ءَامَنُواْ وَٱلَّذِينَ هَادُواْ وَٱلصَّـٰبِـُٔونَ وَٱلنَّصَٰرَىٰ مَنۡ ءَامَنَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ وَعَمِلَ صَٰلِحٗا فَلَا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَنُونَ ﴿٦٩﴾", "w": [["الرسول", "ذكر من بني آدم أُوحي إليه شرع وأُمر بتبليغه، وهو هنا محمد ﷺ."], ["بلّغ ما أُنزل إليك", "من التوحيد والشرائع والأحكام."], ["يعصمك", "يحفظك حفظاً لا يصل إليك معه أحد بسوء."], ["هادوا", "اليهود."], ["الصابئون", "جمع صابئ، وهم فرقة من أهل الكتاب."]], "m": "ينادي الله رسوله معظّماً له: يا أيها الرسول بلّغ ما أُنزل إليك من ربك من العقائد والشرائع والأحكام، وإن لم تفعل، أي إن قصّرت في شيء لم تبلّغه، فما بلّغت رسالته، والله يعصمك من الناس، فلا عذر لك في ترك إبلاغ أي شيء، ولذا لم يكتم رسول الله ﷺ شيئاً مما أُمر بإبلاغه البتة، إن الله لا يهدي القوم الكافرين لما يريدون من أذيته، ولما نزلت قال ﷺ: «لا تحرسوني فإن الله قد عصمني». ثم قال: قل يا أهل الكتاب لستم على شيء من الدين الحق حتى تقيموا التوراة والإنجيل وما أُنزل إليكم من ربكم، والقرآن أيضاً، وليزيدنّ كثيراً منهم ما أُنزل إليك طغياناً وكفراً، فلا تحزن على القوم الكافرين. ثم قال: إن الذين آمنوا، وهم المسلمون، والذين هادوا والصابئون والنصارى، من آمن منهم الإيمان الحق بالله واليوم الآخر وعمل صالحاً، فلا خوف عليهم ولا هم يحزنون.", "h": ["وجوب البلاغ على الرسل، ونهوض رسولنا محمد ﷺ بهذا الواجب على أكمل وجه وأتمّه.", "عصمة الرسول ﷺ المطلقة.", "كفر أهل الكتاب، إلا من آمن منهم بالنبي محمد ﷺ واتبع ما جاء به من الدين الحق.", "أهل العناد والمكابرة لا تزيدهم الأدلة والبراهين إلا عتوّاً ونفوراً وطغياناً وكفراً.", "العبرة بالإيمان والعمل الصالح وترك الشرك والمعاصي، لا بالانتساب إلى دين من الأديان."], "k": "«بلّغ ما أُنزل إليك»… ما الآية أو الحديث الذي تعلّمته ولم أبلّغه لأحد بعد؟"}, {"lbl": "الآيات ٧٠ – ٧٢", "q": "لَقَدۡ أَخَذۡنَا مِيثَٰقَ بَنِيٓ إِسۡرَـٰٓءِيلَ وَأَرۡسَلۡنَآ إِلَيۡهِمۡ رُسُلٗاۖ كُلَّمَا جَآءَهُمۡ رَسُولُۢ بِمَا لَا تَهۡوَىٰٓ أَنفُسُهُمۡ فَرِيقٗا كَذَّبُواْ وَفَرِيقٗا يَقۡتُلُونَ ﴿٧٠﴾ وَحَسِبُوٓاْ أَلَّا تَكُونَ فِتۡنَةٞ فَعَمُواْ وَصَمُّواْ ثُمَّ تَابَ ٱللَّهُ عَلَيۡهِمۡ ثُمَّ عَمُواْ وَصَمُّواْ كَثِيرٞ مِّنۡهُمۡۚ وَٱللَّهُ بَصِيرُۢ بِمَا يَعۡمَلُونَ ﴿٧١﴾ لَقَدۡ كَفَرَ ٱلَّذِينَ قَالُوٓاْ إِنَّ ٱللَّهَ هُوَ ٱلۡمَسِيحُ ٱبۡنُ مَرۡيَمَۖ وَقَالَ ٱلۡمَسِيحُ يَٰبَنِيٓ إِسۡرَـٰٓءِيلَ ٱعۡبُدُواْ ٱللَّهَ رَبِّي وَرَبَّكُمۡۖ إِنَّهُۥ مَن يُشۡرِكۡ بِٱللَّهِ فَقَدۡ حَرَّمَ ٱللَّهُ عَلَيۡهِ ٱلۡجَنَّةَ وَمَأۡوَىٰهُ ٱلنَّارُۖ وَمَا لِلظَّـٰلِمِينَ مِنۡ أَنصَارٖ ﴿٧٢﴾", "w": [["الميثاق", "العهد المؤكد باليمين."], ["بما لا تهوى أنفسهم", "بما لا يحبونه ولا تميل إليه أنفسهم المريضة."], ["فريقاً كذّبوا", "كذّبوا طائفة من الرسل، وقتلوا طائفة أخرى."], ["ألا تكون فتنة", "ألا يُبتلوا بذنوبهم بالشدائد والمحن."], ["فعموا وصمّوا", "عموا عن العِبر، وصمّوا عن سماع المواعظ."], ["من يشرك بالله", "يعبد مع الله غيره بأي نوع من العبادات."], ["حرّم الله عليه الجنة", "حكم بمنعه من دخولها أبداً، إلا أن يتوب من الشرك."]], "m": "ما زال السياق في أهل الكتاب: أقسم الله أنه أخذ ميثاق بني إسرائيل في التوراة أن يعبدوه وحده ويطيعوه، وأرسل إليهم رسله تترى، كلما جاءهم رسول بما لا يوافق أهواءهم كذّبوه أو قتلوه، وحسبوا ألا يؤاخذوا بذنوبهم، فعموا عن الحق وصمّوا عن المواعظ، فسلّط عليهم من سامهم سوء العذاب، ثم تاب الله عليهم فاستقام أمرهم، ثم عموا وصمّوا مرة أخرى كثير منهم، والله بصير بما يعملون. ثم قرّر حكمه بالكفر على من قالوا إن الله هو المسيح ابن مريم، وحاشا عيسى أن يرضى بذلك، وهو القائل: يا بني إسرائيل اعبدوا الله ربي وربكم، إنه من يشرك بالله فقد حرّم الله عليه الجنة ومأواه النار، وما للظالمين من أنصار، فهل يصدر هذا عمن يدّعي أنه الله؟ سبحانك هذا بهتان عظيم.", "h": ["بيان تاريخ بني إسرائيل، والكشف عن مخبّآت جرائمهم من الكفر والقتل.", "إكرام الله تعالى لبني إسرائيل ولطفه بهم مع تمرّدهم عليه ورفض ميثاقه وقتل أنبيائه وتكذيبهم.", "تقرير كفر النصارى بقولهم: المسيح هو الله.", "تقرير عبودية عيسى ﵇ لربه تعالى."], "k": "«فعموا وصمّوا»… هل مرّت بي عِبرة أو موعظة ولم أنتفع بها؟"}, {"lbl": "الآيات ٧٣ – ٧٦", "q": "لَّقَدۡ كَفَرَ ٱلَّذِينَ قَالُوٓاْ إِنَّ ٱللَّهَ ثَالِثُ ثَلَٰثَةٖۘ وَمَا مِنۡ إِلَٰهٍ إِلَّآ إِلَٰهٞ وَٰحِدٞۚ وَإِن لَّمۡ يَنتَهُواْ عَمَّا يَقُولُونَ لَيَمَسَّنَّ ٱلَّذِينَ كَفَرُواْ مِنۡهُمۡ عَذَابٌ أَلِيمٌ ﴿٧٣﴾ أَفَلَا يَتُوبُونَ إِلَى ٱللَّهِ وَيَسۡتَغۡفِرُونَهُۥۚ وَٱللَّهُ غَفُورٞ رَّحِيمٞ ﴿٧٤﴾ مَّا ٱلۡمَسِيحُ ٱبۡنُ مَرۡيَمَ إِلَّا رَسُولٞ قَدۡ خَلَتۡ مِن قَبۡلِهِ ٱلرُّسُلُ وَأُمُّهُۥ صِدِّيقَةٞۖ كَانَا يَأۡكُلَانِ ٱلطَّعَامَۗ ٱنظُرۡ كَيۡفَ نُبَيِّنُ لَهُمُ ٱلۡأٓيَٰتِ ثُمَّ ٱنظُرۡ أَنَّىٰ يُؤۡفَكُونَ ﴿٧٥﴾ قُلۡ أَتَعۡبُدُونَ مِن دُونِ ٱللَّهِ مَا لَا يَمۡلِكُ لَكُمۡ ضَرّٗا وَلَا نَفۡعٗاۚ وَٱللَّهُ هُوَ ٱلسَّمِيعُ ٱلۡعَلِيمُ ﴿٧٦﴾", "w": [["ثالث ثلاثة", "الثلاثة عندهم: الأب والابن وروح القدس، وكلها إله واحد."], ["خلت من قبله الرسل", "مضت قبله رسل كثيرون."], ["وأمه صدّيقة", "كانت مريم كثيرة الصدق في قولها وعملها."], ["أنّى يؤفكون", "كيف يُصرفون عن الحق وقد ظهر واضحاً؟"]], "m": "ما زال السياق في بيان كفر النصارى: لقد كفر الذين قالوا إن الله ثالث ثلاثة، يعنون الأب والابن وروح القدس، فأكذبهم الله: وما من إله إلا إله واحد؛ فجبريل أحد ملائكته، وعيسى عبده ورسوله، ومريم أمته، والكل عبيد لله، وإن لم ينتهوا عما يقولون ليمسّنّ الذين كفروا منهم عذاب أليم. ثم دعاهم لكمال رحمته إلى التوبة: أفلا يتوبون إلى الله ويستغفرونه، والله غفور رحيم؟ ثم علّم رسوله الاحتجاج: ما المسيح ابن مريم إلا رسول قد خلت من قبله الرسل، وأمه صدّيقة لا تعرف الكذب، كانا يأكلان الطعام احتياجاً إليه، فهل من يأكل الطعام افتقاراً إليه ثم يُخرج فضلاته يصلح أن يكون إلهاً؟ انظر كيف نبيّن لهم الآيات ثم انظر أنّى يُصرفون عنها. ثم أمره أن يوبّخهم: أتعبدون من دون الله ما لا يملك لكم ضراً ولا نفعاً، وتتركون من يملك ذلك، والله هو السميع العليم؟", "h": ["إبطال التثليث في عقيدة النصارى، وتقرير التوحيد.", "إبراء عيسى ووالدته ﵉ من دعوى الألوهية لهما.", "فتح باب التوبة في وجه النصارى لو أنهم يتوبون.", "تقرير بشرية عيسى ومريم ﵉، بدليل احتياجهما إلى الطعام لقوام بنيتهما، ومن كان مفتقراً لا تصح ألوهيته عقلاً وشرعاً.", "ذم كل من يعبد غير الله، إذ كل الخلائق مفتقرة لا تملك لنفسها ولا لعابدها ضراً ولا نفعاً، والله وحده السميع العليم، فهو المعبود بحق."], "k": "«أفلا يتوبون إلى الله ويستغفرونه»… باب التوبة مفتوح حتى لمن قال أعظم الباطل، فما الذي يؤخّرني عنه؟"}, {"lbl": "الآيات ٧٧ – ٨١", "q": "قُلۡ يَـٰٓأَهۡلَ ٱلۡكِتَٰبِ لَا تَغۡلُواْ فِي دِينِكُمۡ غَيۡرَ ٱلۡحَقِّ وَلَا تَتَّبِعُوٓاْ أَهۡوَآءَ قَوۡمٖ قَدۡ ضَلُّواْ مِن قَبۡلُ وَأَضَلُّواْ كَثِيرٗا وَضَلُّواْ عَن سَوَآءِ ٱلسَّبِيلِ ﴿٧٧﴾ لُعِنَ ٱلَّذِينَ كَفَرُواْ مِنۢ بَنِيٓ إِسۡرَـٰٓءِيلَ عَلَىٰ لِسَانِ دَاوُۥدَ وَعِيسَى ٱبۡنِ مَرۡيَمَۚ ذَٰلِكَ بِمَا عَصَواْ وَّكَانُواْ يَعۡتَدُونَ ﴿٧٨﴾ كَانُواْ لَا يَتَنَاهَوۡنَ عَن مُّنكَرٖ فَعَلُوهُۚ لَبِئۡسَ مَا كَانُواْ يَفۡعَلُونَ ﴿٧٩﴾ تَرَىٰ كَثِيرٗا مِّنۡهُمۡ يَتَوَلَّوۡنَ ٱلَّذِينَ كَفَرُواْۚ لَبِئۡسَ مَا قَدَّمَتۡ لَهُمۡ أَنفُسُهُمۡ أَن سَخِطَ ٱللَّهُ عَلَيۡهِمۡ وَفِي ٱلۡعَذَابِ هُمۡ خَٰلِدُونَ ﴿٨٠﴾ وَلَوۡ كَانُواْ يُؤۡمِنُونَ بِٱللَّهِ وَٱلنَّبِيِّ وَمَآ أُنزِلَ إِلَيۡهِ مَا ٱتَّخَذُوهُمۡ أَوۡلِيَآءَ وَلَٰكِنَّ كَثِيرٗا مِّنۡهُمۡ فَٰسِقُونَ ﴿٨١﴾", "w": [["لا تغلوا في دينكم", "الغلو: الإفراط في الشيء ومجاوزة الحد فيه."], ["أهواء قوم قد ضلّوا", "جمع هوى، وصاحب الهوى هو الذي يعتقد ويقول ويعمل بهواه، لا بما قام عليه الدليل من دين الله."], ["وأضلّوا كثيراً", "أضلّوا عدداً كثيراً من الناس بأهوائهم وأباطيلهم."], ["عن سواء السبيل", "وسط الطريق العدل، لا ميل فيه."], ["لُعن", "دُعي عليهم باللعنة، وهي الإبعاد من الخير والرحمة."], ["بما عصوا وكانوا يعتدون", "بسبب عصيانهم رسلهم واعتدائهم في دينهم."], ["لا يتناهون", "لا ينهى بعضهم بعضاً عن المنكر."], ["يتولّون الذين كفروا", "يوادّونهم ويتعاونون معهم دون المؤمنين."]], "m": "ما زال السياق في أهل الكتاب: قل يا أهل الكتاب، والمراد هنا النصارى، لا تغلوا في دينكم غير الحق، فتبتدعوا البدع وتتغالوا في التمسك بها، فالتشدّد محمود في الحق الذي أمر الله به لا في المحدثات، ولا تتّبعوا أهواء قوم قد ضلّوا من قبل، وهم اليهود، إذ قالوا في عيسى ساحر وفي أمه بغيّ، وأضلّوا كثيراً، وضلّوا عن سواء السبيل. ثم أخبر أن الذين كفروا من بني إسرائيل لُعنوا على لسان داود وعيسى ابن مريم ومحمد ﷺ، بعصيانهم واعتدائهم، وذكر نوع عصيانهم: كانوا لا يتناهون عن منكر فعلوه، كما قال ﷺ: «إن أول ما دخل النقص على بني إسرائيل أنه كان الرجل يلقى الرجل فيقول: يا هذا اتق الله ودع ما تصنع، ثم يلقاه من الغد وهو على حاله فلا يمنعه ذلك أن يكون أكيله وشريبه وقعيده»، فضرب الله قلوب بعضهم ببعض، لبئس ما كانوا يفعلون. ترى كثيراً منهم، من يهود المدينة، يتولّون المشركين والمنافقين، لبئس ما قدّمت لهم أنفسهم: أن سخط الله عليهم وفي العذاب هم خالدون، ولو كانوا يؤمنون بالله والنبي وما أُنزل إليه ما اتخذوهم أولياء، ولكن كثيراً منهم فاسقون.", "h": ["حرمة الغلو والابتداع في الدين، واتباع أهل الأهواء.", "العصيان والاعتداء ينتجان لصاحبهما الحرمان والخسران.", "حرمة السكوت عن المنكر، ووخامة عاقبته على المجتمع.", "حرمة موالاة أهل الكفر والشر والفساد.", "موالاة أهل الكفر بالمودة والنصرة دون المؤمنين آية الكفر وعلامته في صاحبه."], "k": "«كانوا لا يتناهون عن منكر فعلوه»… هل يمنعني الحرج أو المجاملة من نصح صديق أحبه؟"}]$j$::jsonb) with ordinality x(e, i);
